(window.GIM_TS=window.GIM_TS||{})["Chullin.1"]={"from":24,"a":[["\u0003השוחט בשבת וביום הכיפורים, אף על פי שמתחייב בנפשו,\u0004 שעבר עבירה שיש בה עונש מיתה במזיד — בכל זאת \u0003שחיטתו כשרה.\u0004","\u0003אמר רב הונא, דרש חייא בר רב משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב:\u0004 אם שחט בשבת וביום הכיפורים, למרות ששחיטתו כשרה, בהמה זו \u0003אסורה באכילה ליומא\u0004 \u0005[לאותו יום],\u0006 \u0003ונסבין חבריא למימר\u0004 \u0005[ונטו בני החבורה\u0006 החכמים \u0005לומר]\u0006 שרב מבין שמשנתנו שיטת \u0003רבי יהודה היא.\u0004","ושואלים: \u0003הי\u0004 \u0005[\u0006ל\u0005איזה]\u0006 מדבריו של \u0003רבי יהודה\u0004 הכוונה? \u0003אמר ר' אבא:\u0004 דברי \u0003רבי יהודה\u0004 שבענין \u0003הכנה\u0004 בשבת \u0003היא. דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003מחתכין\u0004 בשבת \u0003את הדילועין לפני הבהמה\u0004 כדי שתאכלם, \u0003ואת הנבלה לפני הכלבים. רבי יהודה אומר: אם לא היתה\u0004 זו \u0003נבלה\u0004 כבר \u0003מערב שבת\u0004 — \u0003אסורה, לפי ש\u0004בשעה שנכנסה השבת \u0003אינה מן המוכן\u0004 לאכילת כלבים. \u0003אלמא\u0004 \u0005[מכאן]\u0006 \u0003כיון\u0004 ש\u0003לא איתכן\u0004 \u0005[היתה מוכנה]\u0006 \u0003מאתמול\u0004 — הריהי \u0003אסורה, הכא נמי\u0004 \u0005[כאן גם כן],\u0006 במשנתנו, כשנשחטה בשבת, \u0003כיון\u0004 ש\u0003לא איתכן\u0004 \u0005[היתה מוכנה]\u0006 לאכילה \u0003מאתמול\u0004 — הריהי \u0003אסורה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מי דמי\u0004 \u0005[האם דומה\u0006 הדבר\u0005]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 הרי \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 היתה הבהמה בגדר \u0003מוכן לאדם,\u0004 שהיתה עומדת לשחיטה לצורך אכילת אדם, \u0003והשתא\u0004 \u0005[ו\u0006רק \u0005עכשיו],\u0006 משנתנבלה בשבת, נעשתה \u0003מוכן לכלבים.\u0004 אבל \u0003הכא\u0004 \u0005[כאן,\u0006 במשנתנו\u0005],\u0006 \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 היתה הבהמה \u0003מוכן ל\u0004צורך אכילת \u0003אדם והשתא\u0004 \u0005[ועכשיו]\u0006 גם כן היא \u0003מוכן לאדם!\u0004 דחה ר' אבא: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 ש\u0003בהמה בחייה לאכילה עומדת,\u0004 שתיחשב מוכנה לאדם? לא, \u0003בהמה בחייה לגדל\u0004 ולדות \u0003עומדת!\u0004","שאל אביי: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה אומר, \u0003בהמה לרבי יהודה ביום טוב היכי שחטינן\u0004 \u0005[כיצד אנו שוחטים]?\u0006 והרי אינה עומדת לאכילה! \u0003אמר לו:\u0004 בהמה בחייה \u0003עומדת לאכילה ו\u0004גם \u0003עומדת לגדל,\u0004 אם \u0003נשחטה\u0004 — \u0003הובררה\u0004 ש\u0003לאכילה עומדת, לא נשחטה\u0004 — \u0003הובררה\u0004 ש\u0003לגדל עומדת.\u0004","ומקשים: \u0003והא לית ליה\u0004 \u0005[והרי אין לו]\u0006 \u0003לרבי יהודה\u0004 עיקרון זה של \u0003ברירה!\u0004 ושואלים: \u0003מנא לן\u0004 \u0005[מנין לנו]\u0006 שאין לו ברירה? \u0003אי נימא מדתניא\u0004 \u0005[אם נאמר ממה ששנויה\u0006 ברייתא\u0005]:\u0006","\u0003הלוקח\u0004 (הקונה) \u0003יין מבין הכותים\u0004 סמוך לשבת, ומן הסתם לא הפרישו ממנו תרומות ומעשרות, ואין לו פנאי להפריש קודם השבת, אם רוצה לשתותו בשבת \u0003אומר: שני לוגין שאני עתיד להפריש\u0004 לאחר השבת מתוך מאה לוגים שיש כאן — \u0003הרי הן תרומה\u0004 מעכשיו, \u0003עשרה\u0004 לוגין שאני עתיד להפריש יהיו \u0003מעשר ראשון, תשעה\u0004 לוגין \u0003מעשר שני, ומיחל\u0004 \u0005[ומחלל]\u0006 את המעשר השני על כסף \u0003ושותה מיד,\u0004 ולאחר השבת מפריש בפועל ממה שנותר, ומתברר למפרע שזו היא התרומה, אלו \u0003דברי ר' מאיר. רבי יהודה ורבי יוסי ור' שמעון אוסרין\u0004 לעשות כן. ומכאן אתה למד שר' יהודה אינו מקבל את עקרון הברירה — אין זו ראיה,"],["\u0003התם\u0004 \u0005[שם]\u0006 טעמו של ר' יהודה אינו משום שלדעתו אין ברירה, אלא \u0003כדקתני טעמא\u0004 \u0005[כמו שהוא שונה את הטעם],\u0006 \u0003אמרו לו\u0004 ר' יהודה וחבריו \u0003לרבי מאיר: אי אתה מודה\u0004 שיש לחשוש \u0003שמא\u0004 קודם שהפריש את התרומה והמעשרות בפועל — \u0003יבקע הנוד\u0004 ויישפך כל היין שבו, \u0003ו\u0004כיון שלא נותר בחבית יין להפרשת תרומה ומעשרות \u0003נמצא\u0004 שהוא \u0003שותה טבלים למפרע? אמר להן\u0004 ר' מאיר: \u0003לכשיבקע\u0004 תהיה זו שאלה, ואין אני חושש לכך!","\u0003אלא\u0004 למדים שאין לר' יהודה ברירה ממקום אחר, \u0003מדתני\u0004 \u0005[ממה ששנה]\u0006 החכם \u0003איו\u0004 בשמו בענין עירובי תחומין, על מה ששנו חכמים, שאדם היודע ששני חכמים עומדים לדרוש בשבת חוץ לתחום העיר, אחד במזרח ואחד במערב, ובערב שבת עדיין לא החליט איזה מהם הוא רוצה לשמוע, יכול להניח בערב שבת שני עירובים בשני צידי העיר, ולהתנות שלאיזה צד שיבחר ללכת בסופו של דבר — שם הוא עירובו מעכשיו.","\u0003דתני\u0004 \u0005[ש\u0006על כך \u0005שנה]\u0006 \u0003איו, רבי יהודה\u0004 חולק על דעת חכמים ו\u0003אומר: אין אדם מתנה\u0004 שיקנה לו עירובו \u0003על שני דברים כאחד,\u0004 כגון בשני חכמים, \u0003אלא\u0004 רק בדבר אחד שיש בו שתי אפשרויות, וכגון על חכם אחד שאינו יודע לאיזה צד של העיר יבוא, שמתנה ש\u0003אם בא\u0004 ה\u0003חכם למזרח\u0004 — \u0003עירובו למזרח,\u0004 ואם \u0003למערב\u0004 — \u0003עירובו למערב;\u0004 \u0003ואילו\u0004 שיתנה \u0003לכאן ולכאן\u0004 לחכם זה או לחכם זה — \u0003לא.\u0004","\u0003והוינן\u0004 \u0005[והיינו עוסקים,\u0006 מתקשים\u0005]\u0006 \u0003בה: מאי שנא\u0004 \u0005[במה שונה]\u0006 כשמתנה \u0003לכאן ולכאן,\u0004 ש\u0003לא\u0004 קונה לו העירוב — מפני ש\u0003אין ברירה,\u0004 שאין אומרים שבחירתו למחרת קובעת למפרע מהו המקום שבחר מתחילה, והרי \u0003מזרח ומערב\u0004 באותו חכם \u0003נמי\u0004 \u0005[גם כן]\u0006 נאמר ש\u0003אין ברירה,\u0004 ולא יקנה העירוב על סמך מה שיתברר בשבת לאיזה צד יבוא החכם!","\u0003ואמר רבי יוחנן:\u0004 מדובר כאן שבשעה שהוא עושה את התנאי \u0003כבר בא\u0004 (הגיע) ה\u0003חכם\u0004 למזרח או למערב, אלא שהוא אינו יודע להיכן, ובמקרה זה אין אנו נזקקים לעקרון ה\"ברירה\". ועל כל פנים, למדנו שלדעת ר' יהודה אין ברירה. אלא לשיטתו, בהמה לאכילה עומדת, ואם כן, מנין שאם נשחטה בשבת הריהי אסורה ליומה משום הכנה?","\u0003אלא אמר רב יוסף:\u0004 מה שאמר רב שבהמה שנשחטה בשבת אסורה ליומה, ואמרו שהוא כשיטת ר' יהודה — שיטת \u0003רבי יהודה\u0004 של \u0003כלים היא, דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003כל הכלים הניטלין\u0004 (שמותר לטלטל אותם) \u0003בשבת,\u0004 שאינם מוקצה — גם \u0003שבריהן ניטלין, ובלבד שיהו\u0004 אותם שברים \u0003עושין\u0004 (ראויים שתיעשה בהם) \u0003מעין מלאכה,\u0004 כגון \u0003שברי עריבה\u0004 (מעין גיגית) — שנשברו ועדיין ראויים \u0003לכסות בהן פי חבית, שברי זכוכית\u0004 — \u0003לכסות בהן פי הפך.\u0004","\u0003רבי יהודה אומר:\u0004 לא די שיהיו ראויים לעשות בהם מלאכה כלשהי, אלא \u0003ובלבד שיהו עושין מעין מלאכתן\u0004 הראשונה, כגון \u0003שברי עריבה\u0004 — \u0003לצוק לתוכן מקפה\u0004 (תבשיל סמיך), \u0003שברי זכוכית\u0004 — \u0003לצוק לתוכן שמן.\u0004","ונדייק: אם ראויים לעשות \u0003מעין מלאכתן\u0004 הראשונה — \u0003אין\u0004 \u0005[כן],\u0006 מטלטלים אותם, \u0003מעין מלאכה אחרת\u0004 — \u0003לא, אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003כיון\u0004 ש\u0003לא איתכן\u0004 \u0005[היו מוכנים,\u0006 מיועדים\u0005]\u0006 \u0003מאתמול להך מלאכה\u0004 \u0005[למלאכה זו,\u0006 האחרת\u0005]\u0006 — \u0003אסירי\u0004 \u0005[אסורים הם]\u0006 בטלטול לדעת ר' יהודה; \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 בבהמה שנשחטה בשבת, \u0003כיון דלא איתכן\u0004 \u0005[שלא היתה מוכנה]\u0006 \u0003מאתמול\u0004 לאכילה — \u0003אסורה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מי דמי\u0004 \u0005[האם דומה\u0006 הדבר\u0005]?\u0006 \u0003התם מעיקרא\u0004 \u0005[שם מתחילה]\u0006 היה זה \u0003כלי והשתא\u0004 \u0005[ועכשיו]\u0006 נעשה \u0003שבר כלי, והוה ליה\u0004 \u0005[והרי זה]\u0006 כדבר חדש ש\u0003נולד,\u0004 \u0003ו\u0004לכן הוא \u0003אסור.\u0004 ואילו \u0003הכא\u0004 \u0005[כאן],\u0006 בבהמה שנשחטה בשבת, \u0003מעיקרא אוכלא\u0004 \u0005[מתחילה\u0006 היתה \u0005אוכל],\u0006 שהרי כבר בחייה מיועדת היא לאכילה, \u0003ו\u0004גם \u0003לבסוף\u0004 כשנשחטה הריהי \u0003אוכל,\u0004 ואם כן בגדר \u0003אוכלא דאיפרת\u0004 \u0005[אוכל שנפרד\u0006 ממקומו\u0005]\u0006 \u0003הוא,\u0004","\u0003ושמעינן ליה\u0004 \u0005[ו\u0006הרי \u0005שמענו אותו]\u0006 את \u0003רבי יהודה\u0004 ש\u0003אמר: אוכלא דאיפרת שפיר דמי\u0004 \u0005[אוכל שנפרד ראוי הוא]\u0006 לאכילה בשבת, ואינו אסור משום נולד. \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003אין סוחטין את הפירות\u0004 כדי \u0003להוציא מהן משקין\u0004 בשבת, \u0003ו\u0004גזרו חכמים שגם \u0003אם יצאו\u0004 המשקים \u0003מעצמן\u0004 — \u0003אסורין.\u0004","\u0003רבי יהודה אומר: אם\u0004 פירות אלה נועדו \u0003לאוכלין\u0004 (לאכילה, ולא לשתיה) — \u0003היוצא מהן\u0004 מעצמו \u0003מותר, ואם\u0004 מיועדים \u0003למשקין\u0004 (לסחיטה) — \u0003היוצא מהן אסור.\u0004 הרי שבפירות המיועדים לאכילה, הוא רואה את המשקים הזבים מהם, כאוכל שנפרד ממקומו, ומותר. ואם כן, הוא הדין בבהמה שנשחטה בשבת, הואיל ומתחילה היתה מיועדת לאכילה — אין זה נחשב כנולד, ויש לומר שאין ר' יהודה אוסרה!","ודוחים: אדרבה, ממקור זה עצמו יש להוכיח שר' יהודה יאסור פרה שנשחטה בשבת, \u0003לאו אתמר עלה\u0004 \u0005[\u0006וכי \u0005לא נאמר עליה],\u0006 ש\u0003אמר רב יהודה אמר שמואל: מודה היה רבי יהודה לחכמים בסלי זיתים וענבים,\u0004 העומדים בדרך כלל למשקים, שלמרות שהניחם לצורך אכילה, המשקה שזב מהם בשבת אסור?","\u0003אלמא\u0004 \u0005[מכאן]\u0006 שגם לדעת ר' יהודה, \u0003כיון\u0004 שזיתים וענבים בדרך כלל \u0003לסחיטה קיימי\u0004 \u0005[הם עומדים]\u0006 — \u0003יהיב דעתיה\u0004 \u0005[\u0006אדם \u0005נותן דעתו]\u0006 עליהם למשקה, ויש חשש שיבוא לסוחטם, ולכן אסרו חכמים את המשקה היוצא מהם בשבת. ואם כן \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בבהמה יש לומר: \u0003כיון\u0004 ש\u0003לשחיטה קיימא\u0004 \u0005[היא עומדת]\u0006 — \u0003יהיב דעתיה\u0004 \u0005[\u0006אדם \u0005נותן דעתו]\u0006 עליה לאכילה, ולכן כאשר שחטה בשבת ר' יהודה אוסרה באכילה, שמא יבוא לשחוט בשבת!","ומשיבים: \u0003מידי הוא טעמא\u0004 \u0005[כלום הוא הטעם],\u0006 כלומר, מה שאנו מביאים מקור לשיטת ר' יהודה, שבהמה שנשחטה בשבת אסורה ליומה, הרי אינו \u0003אלא ל\u0004דעת \u0003רב,\u0004 שאמר כן. ואולם \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003רב\u0004 עצמו: \u0003חלוק היה רבי יהודה אפילו בסלי זיתים וענבים,\u0004 ולדעתו אם ייעד את הפירות לאכילה — המשקים שזבו מהם בשבת מותרים. ולדרך זו נמצא שיש להתיר גם בהמה שנשחטה בשבת!","\u0003אלא אמר רב ששת בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי:\u0004 מה שאמר רב, שבהמה שנשחטה בשבת אסורה ליומה, ואמרו שהיא לשיטת ר' יהודה — שיטת \u0003רבי יהודה\u0004 של \u0003נרות היא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003מטלטלין\u0004 בשבת \u0003נר\u0004 חרס \u0003חדש,\u0004 שלא השתמשו בו עדיין, שלא לצורך הדלקה, \u0003אבל לא\u0004 מטלטלים נר \u0003ישן,\u0004 שיש בו שאריות של שמן ופיח, מפני שאדם מקצה אותו משימוש מחמת מיאוסו, וכיון שהיה מוקצה בכניסת השבת — הוקצה לשבת כולה, ונאסר בטלטול גם אם יש בו צורך, אלו \u0003דברי רבי יהודה.\u0004 ויש לומר כי לדעתו הוא הדין לבהמה שנשחטה בשבת, שהיא אסורה, מפני שכשנכנסה השבת היתה אסורה עליו משום אבר מן החי.","ודוחים: \u0003אימר דשמעת ליה\u0004 \u0005[אמור ששמעת אותו]\u0006 את \u0003רבי יהודה\u0004 שהוא אוסר \u0003ב\u0004דבר שהוא \u0003מוקצה מחמת מיאוס,\u0004 כמו נר ישן, אבל בדבר שהוא \u0003מוקצה\u0004 רק \u0003מחמת איסור מי שמעת ליה\u0004 \u0005[האם שמעת אותו]\u0006 שהוא אוסר אותו בשבת כולה? ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 שמענו שזו דעתו, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005],\u0006 \u0003רבי יהודה אומר:\u0004"],["\u0003כל נרות של מתכת מטלטלין\u0004 בשבת, ואפילו ישנים, משום שהם אינם מאוסים כנרות של חרס, \u0003חוץ מן הנר שהדליקו בו באותה שבת,\u0004 שהיה דולק כשנכנסה השבת, שהוא מוקצה מחמת איסור כיבוי.","ודוחים: \u0003ודלמא שאני התם\u0004 \u0005[ושמא שונה שם],\u0006 שהוא מוקצה מפני \u0003דהוא דחי ליה\u0004 \u0005[שהוא עצמו דחה אותו]\u0006 \u0003בידים,\u0004 שהדליק את הנר ובכך הקצה אותו. אבל בהמה — לא הוא הקצה אותה, ושמא משנשחטה הותרה!","\u0003אלא אמר רב אשי:\u0004 מה שאמר רב שבהמה שנשחטה בשבת אסורה בשבת עצמה, ולשיטת ר' יהודה, אין זה משום הכנה ולא משום מוקצה, אלא משום הנאה ממעשה איסור בשבת, וכשיטת \u0003רבי יהודה\u0004 בעניין \u0003מבשל היא. דתנן\u0004 \u0005[ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003המבשל בשבת,\u0004 אם עשה זאת \u0003בשוגג\u0004 — \u0003יאכל\u0004 בשבת ממה שבישל, \u0003במזיד\u0004 — \u0003לא יאכל,\u0004 אלו \u0003דברי רבי מאיר.\u0004","\u0003רבי יהודה אומר:\u0004 בישל \u0003בשוגג\u0004 — \u0003יאכל במוצאי שבת, במזיד\u0004 — \u0003לא יאכל עולמית.\u0004","\u0003רבי יוחנן הסנדלר אומר:\u0004 אם \u0003בשוגג\u0004 — \u0003יאכל\u0004 התבשיל \u0003למוצאי שבת,\u0004 ואולם רק \u0003לאחרים ולא לו, במזיד\u0004 — \u0003לא יאכל עולמית לא לו ולא לאחרים.\u0004 ולפי רב יש לפרש את משנתנו לשיטת ר' יהודה כששחט בשוגג, ובאופן זה שחיטתו כשרה, ואולם הבהמה אסורה בשבת עצמה.","ושואלים: \u0003ונוקמה\u0004 \u0005[ונעמיד אותה,\u0006 את משנתנו\u0005]\u0006 לדעת רב, בשוחט בשבת \u0003במזיד, ו\u0004כשיטת \u0003רבי מאיר!\u0004","ודוחים: \u0003לא סלקא דעתך\u0004 \u0005[לא יעלה על דעתך]\u0006 לומר כן, \u0003דקתני\u0004 \u0005[שהרי הוא שונה]\u0006 כאחת שוחט בשבת וביום הכיפורים, ומשם נלמד כי דין השבת הוא \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003יום הכפורים, מה יום הכפורים לא שנא\u0004 \u0005[אינו שונה]\u0006 אם היה זה \u0003בשוגג ולא שנא\u0004 \u0005[ואינו שונה]\u0006 \u0003במזיד\u0004 — \u0003לא אכיל\u0004 \u0005[אינו אוכל],\u0006 שהרי כל אכילה נאסרה בו, \u0003אף הכא נמי\u0004 \u0005[אף כאן,\u0006 בשבת, \u0005גם כן],\u0006 \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 \u0003בשוגג ולא שנא\u0004 \u0005[ואינו שונה]\u0006 \u0003במזיד\u0004 — \u0003לא אכיל\u0004 \u0005[אינו אוכל].\u0006","ושואלים: \u0003ומי מצית מוקמת לה\u0004 \u0005[והאם יכול אתה להעמיד אותה,\u0006 את משנתנו\u0005]\u0006 \u0003בשוגג ו\u0004כשיטת \u0003רבי יהודה? והא\u0004 \u0005[והרי]\u0006 \u0003\"אף על פי שמתחייב בנפשו\" קתני\u0004 \u0005[הוא שונה],\u0006 ואין אדם חייב מיתה אלא אם עשה במזיד! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 השוחט (בשוגג) בשבת וביום הכיפורים, \u0003אף על פי\u0004 ש\u0003במזיד מתחייב בנפשו הוא, הכא\u0004 \u0005[כאן]\u0006 שעשה \u0003בשוגג\u0004 — \u0003שחיטתו כשרה.\u0004","ושואלים: \u0003ונוקמה\u0004 \u0005[ונעמיד אותה,\u0006 את משנתנו\u0005]\u0006 בין בשוגג ובין במזיד, ו\u0003כ\u0004דעת \u0003רבי יוחנן הסנדלר\u0004 ש\u0003אמר: לא שנא\u0004 \u0005[אינו שונה]\u0006 אם בישל \u0003בשוגג ולא שנא\u0004 \u0005[ואינו שונה]\u0006 אם עשה \u0003במזיד\u0004 — \u0003לא אכיל\u0004 \u0005[אינו אוכל]\u0006 בשבת עצמה! ומשיבים: \u0003רבי יוחנן הסנדלר קמפליג\u0004 \u0005[מחלק]\u0006 \u0003במוצאי שבת,\u0004 שהוא מתיר \u0003לאחרים ולא לו,\u0004 ואילו ה\u0003תנא דידן\u0004 \u0005[שלנו]\u0006 \u0003\"שחיטתו כשרה\" קתני\u0004 \u0005[הוא שונה],\u0006 ומשמע — \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 \u0003לו ולא שנא\u0004 \u0005[ואינו שונה]\u0006 \u0003לאחרים.\u0004","מסופר, \u0003תני תנא קמיה\u0004 \u0005[שנה חוזר המשניות לפני]\u0006 \u0003רב: המבשל בשבת, בשוגג\u0004 — \u0003יאכל, במזיד\u0004 — \u0003לא יאכל, ומשתיק ליה\u0004 \u0005[והיה משתיק אותו]\u0006 \u0003רב,\u0004 משום שטעות היא.","ושואלים: \u0003מאי טעמא משתיק ליה\u0004 \u0005[מה טעם היה משתיק אותו]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום דסבירא ליה\u0004 \u0005[שסבור הוא,\u0006 רב\u0005]\u0006 \u0003כרבי יהודה, ו\u0004אילו ה\u0003תנא תני\u0004 \u0005[שנה]\u0006 \u0003כרבי מאיר,\u0004 וכי \u0003משום דסבירא ליה\u0004 \u0005[שסבור הוא]\u0006 \u0003כרבי יהודה, מאן דתני\u0004 \u0005[מי ששונה]\u0006 \u0003כ\u0004דעת \u0003רבי מאיר\u0004 נחשב כטועה ו\u0003משתיק ליה\u0004 \u0005[\u0006היה \u0005משתיק אותו]?!\u0006","\u0003ועוד\u0004 יש לשאול לעצם הדבר, \u0003מי סבר לה\u0004 \u0005[\u0006ו\u0005האם סבור]\u0006 רב \u0003כרבי יהודה? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב חנן בר אמי: כי מורי להו\u0004 \u0005[כאשר היה מורה]\u0006 \u0003רב לתלמידיה\u0004 \u0005[לתלמידיו]\u0006 הלכה למעשה — \u0003מורי להו\u0004 \u0005[היה מורה להם]\u0006 בענין מבשל בשבת \u0003כ\u0004דעת \u0003ר' מאיר, וכי דריש בפירקא\u0004 \u0005[וכאשר היה דורש לרבים]\u0006 — \u0003דריש\u0004 \u0005[היה דורש]\u0006 \u0003כרבי יהודה, משום\u0004 שחשש מ\u0003עמי הארץ\u0004 שיזלזלו במלאכת שבת!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 ה\u0003תנא\u0004 \u0003בפירקיה תנא קמיה\u0004 \u0005[חוזר המשניות בזמן הדרשה בציבור שנה לפניו]\u0006 כשיטת ר' מאיר, ולכן השתיק אותו, כדי שלא ילמדו מכך עמי הארץ — דבר זה קשה לומר, \u0003אטו כולי עלמא לתנא צייתי\u0004 \u0005[וכי הכל לחוזר המשניות הם מקשיבים]\u0006 לשמוע מה אמר? והלוא \u0003לאמורא צייתי\u0004 \u0005[הם מקשיבים],\u0006 לחכם הממונה להשמיע לרבים את דברי רב, והוא הרי שומע מפי רב כדברי ר' יהודה, וכך היה משמיע לרבים!","\u0003אמר רב נחמן בר יצחק:\u0004 כך הוא טעמו של דבר, ה\u0003תנא\u0004 \u0005[חוזר המשניות]\u0006 \u0003שוחט תנא קמיה\u0004 \u0005[שנה לפני]\u0006 \u0003רב:\u0004 \u0003השוחט בשבת, בשוגג\u0004 — \u0003יאכל, במזיד\u0004 — \u0003לא יאכל. אמר ליה\u0004 \u0005[לו]\u0006 רב: \u0003מאי דעתיך\u0004 \u0005[מה דעתך]?\u0006 כשיטת מי אתה שונה, \u0003כ\u0004שיטת \u0003רבי מאיר?\u0004 והרי \u0003עד כאן לא קשרי\u0004 \u0005[לא\u0006 שמענו ש\u0005התיר]\u0006 \u0003רבי מאיר\u0004 שיאכל בשבת אם עשה בשוגג, \u0003אלא במבשל,\u0004 מפני שמאכל שלא נתבשל \u0003ראוי\u0004 על כל פנים \u0003לכוס\u0004 (לכסיסה, ללעיסה), ולא היה מוקצה כשנכנסה השבת, \u0003אבל שוחט,\u0004 ש\u0003אין\u0004 הבשר \u0003ראוי לכוס\u0004 לפני שחיטה — \u0003לא\u0004 התיר, שהרי היה מוקצה כשנכנסה השבת!","ומקשים: \u0003והא מתניתין\u0004 \u0005[והרי\u0006 \u0005משנתנו]\u0006 ש\u0003שוחט הוא, ואמר רב הונא, דרש חייא בר רב משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: אסורה\u0004 הבהמה \u0003באכילה ליומא\u0004 \u0005[לאותו יום],\u0006 \u0003ונסבין חבריא למימר\u0004 \u0005[ונטו בני החבורה של החכמים לומר]\u0006 ששיטת \u0003רבי יהודה היא,\u0004 ומשמע: \u0003הא\u0004 \u0005[אבל]\u0006 \u0003רבי מאיר שרי\u0004 \u0005[מתיר]\u0006 בכגון זה, ואינו חושש למוקצה!","ומשיבים: \u0003כי שרי\u0004 \u0005[כאשר מתיר]\u0006 \u0003רבי מאיר,\u0004"],["הרי זה \u0003כגון שהיה לו חולה\u0004 שיש בו סכנה \u0003מבעוד יום,\u0004 שמצוה לשחוט בשבילו אפילו בשבת, ולכן לא היה בבהמה איסור מוקצה, שהרי זה כאילו יועדה לכך.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 אם בזה מדובר, \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רבי יהודה דאסר\u0004 \u0005[שאוסר]?\u0006 ומשיבים: הכוונה היא \u0003כגון שהיה לו חולה\u0004 בערב שבת \u0003והבריא\u0004 בינתיים, שאף על פי שאיסור מוקצה לא היה כאן, מכל מקום איסור שחיטה בשבת יש כאן, ולדעת ר' יהודה גם אם עשה כן בשוגג הרי זה אסור בשבת עצמה.","ושבים לעיקר הענין, ואומרים: \u0003ו\u0004מה שהסברנו שרב השתיק את התנא על שלא הבחין בין מבשל בשבת לשוחט בשבת, הריהו \u0003כי הא\u0004 \u0005[כמו זו]\u0006 ש\u0003אמר רב אחא בר אדא אמר רב, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר רבי יצחק בר אדא אמר רב: השוחט\u0004 בשבת \u0003ל\u0004צורך \u0003חולה\u0004 שחלה חולי שיש בו סכנה \u0003בשבת\u0004 — \u0003אסור לבריא\u0004 לאכול מן הבשר, \u0003המבשל לחולה\u0004 שחלה \u0003בשבת\u0004 בשר בהמה שנשחטה מערב שבת — \u0003מותר לבריא\u0004 לאכול ממנו.","\u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 ההבדל? \u0003האי\u0004 \u0005[זה]\u0006 הבשר שאינו מבושל \u0003ראוי\u0004 היה \u0003לכוס\u0004 אותו גם לפני הבישול, ולא היה מוקצה בכניסת השבת, \u0003ו\u0004אילו \u0003האי\u0004 \u0005[זה]\u0006 שלא נשחט קודם השבת \u0003אינו ראוי לכוס\u0004 קודם השבת, שהרי הוא אבר מן החי והוא נעשה מוקצה בכניסת השבת.","\u0003אמר רב פפא: פעמים ש\u0004גם \u0003השוחט\u0004 בשבת \u0003מותר\u0004 לבריא לאכול מן הבשר — \u0003כגון שהיה לו חולה מבעוד יום,\u0004 והבהמה עמדה לשחיטה בכניסת השבת, ולא היתה מוקצה. ומצד שני, פעמים ש\u0003מבשל\u0004 בשבת \u0003אסור\u0004 לבריא לאכול מן המבושל — \u0003כגון שקצץ לו\u0004 בשבת \u0003דלעת\u0004 מן המחובר ובישל אותה, מפני שהיתה מוקצה מחמת האיסור לקוצצה.","\u0003אמר רב דימי מנהרדעא, הלכתא\u0004 \u0005[הלכה היא]:\u0006 \u0003השוחט לחולה בשבת\u0004 — \u0003מותר לבריא\u0004 לאכול מן הבשר \u0003באומצא,\u0004 כלומר, בשר חי, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003כיון\u0004 ש\u0003אי אפשר לכזית בשר בלא שחיטה, כי קא שחיט\u0004 — \u0003אדעתא דחולה קא שחיט\u0004 \u0005[כאשר הוא שוחט\u0006 — \u0005על דעת החולה הוא שוחט],\u0006 שהרי גם אם החולה אוכל מעט צריך לשחוט עבורו בהמה שלימה, וכיון ששחט בהיתר — מותר גם לאחרים. אבל \u0003המבשל לחולה בשבת\u0004 — \u0003אסור לבריא\u0004 לאכול מן התבשיל, והטעם הוא: \u0003גזירה שמא ירבה\u0004 יוסיף לתבשיל גם \u0003בשבילו.\u0004","\u0003השוחט ב\u0004שפתו החלקה של \u0003מגל יד,\u0004 ששפתו האחת חלקה והשניה משוננת, או \u0003בצור\u0004 (אבן חדה), או \u0003בקנה\u0004 שנחתך לאורכו ושפתו חדה — \u0003שחיטתו כשרה.\u0004","\u0003הכל שוחטין, ולעולם שוחטין, ובכל שוחטין\u0004 (בכל דבר שחותך) \u0003חוץ ממגל קציר והמגירה\u0004 (משור), \u0003והשינים\u0004 כשהן קבועות בעצם הלחי של בהמה, \u0003והציפורן,\u0004 שאין שוחטים בהם \u0003מפני שהם חונקין\u0004 ולא חותכים, שיש להם פגימות הנאחזות בסימנים (הקנה והושט) וקורעות אותם.","שנינו במשנה \u0003\"השוחט\"\u0004 במגל יד בצור ובקנה, ומשמע: ב\u0003דיעבד\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 שחיטתו כשרה, אבל \u0003לכתחלה\u0004 — \u0003לא\u0004 ישחט באלה. ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003במגל יד\u0004 מובן הטעם — \u0003דלמא אתי למעבד באידך גיסא\u0004 \u0005[שמא יבוא לשחוט בצד האחר]\u0006 המשונן, \u0003אלא צור וקנה\u0004 שהיו חדים האם \u0003לכתחלה\u0004 \u0003לא\u0004 שוחטים בהם? \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 לכך ממה ששנינו בברייתא: \u0003בכל שוחטין, בין בצור, בין בזכוכית, בין בקרומית של קנה!\u0004","ומשיבים, \u0003לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003כאן\u0004 שמשמע ששוחטים לכתחילה — מדובר \u0003בתלוש,\u0004 \u0003כאן\u0004 שמשמע שהדבר נאסר לכתחילה — מדובר \u0003במחובר,\u0004 כששוחט על ידי צור או קנה המחובר לקרקע, וכשיטת ר' חייא. ש\u0003אמר רב כהנא: השוחט ב\u0004אמצעות דבר ה\u0003מחובר לקרקע\u0004 — \u0003רבי פוסל ור' חייא מכשיר;\u0004 והרי \u0003עד כאן לא\u0004 שמענו ש\u0003קא מכשיר רבי חייא\u0004 במחובר \u0003אלא בדיעבד, אבל לכתחלה לא.\u0004","ושואלים: \u0003במאי אוקימתא\u0004 \u0005[במה העמדת]\u0006 לפי זה את המשנה? \u0003כ\u0004דעת \u0003רבי חייא ודיעבד; אלא\u0004 \u0003הא דתניא\u0004 \u0005[זו ששנויה]\u0006 בברייתא: \u0003בכל שוחטין\u0004 לכתחילה, \u0003בין בתלוש, בין במחובר, בין שהסכין למעלה וצואר בהמה למטה, בין שהסכין למטה וצואר בהמה למעלה, מני\u0004 \u0005[\u0006כשיטת \u0005מי היא]?\u0006 \u0003לא\u0004 כשיטת \u0003רבי ולא\u0004 כשיטת \u0003ר' חייא,\u0004 שכן \u0003אי\u0004 \u0005[אם]\u0006 לשיטת \u0003ר' חייא\u0004 — הרי ב\u0003דיעבד\u0004 \u0003אין\u0004 \u0005[כן]\u0006 השחיטה כשרה, אבל \u0003לכתחלה\u0004 — \u0003לא\u0004 יעשה כן, \u0003אי\u0004 \u0005[אם]\u0006 לשיטת \u0003רבי\u0004 — ב\u0003דיעבד נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 כשרה השחיטה!","ומשיבים: \u0003לעולם\u0004 תפרש שברייתא זו היא כשיטת \u0003רבי חייא, ו\u0004הוא מתיר לשחוט במחובר \u0003אפילו לכתחלה, והאי דקמיפלגי\u0004 \u0005[וזה שנחלקו]\u0006 \u0003בדיעבד,\u0004 כפי שאמר רב כהנא — הרי זה כדי \u0003להודיעך כחו\u0004 של \u0003רבי,\u0004 שהוא אוסר אפילו בדיעבד.","\u0003ו\u0004שואלים: \u0003אלא,\u0004 לפי זה, \u0003מתניתין דקתני\u0004 \u0005[משנתנו שהוא שונה\u0006 בה\u0005]:\u0006 \u0003\"השוחט\",\u0004 ומשמע: ב\u0003דיעבד\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003לכתחלה\u0004 — \u0003לא, מני\u0004 \u0005[כשיטת מי היא]?\u0006 \u0003לא\u0004 שיטת \u0003רבי ולא\u0004 שיטת \u0003רבי חייא,\u0004 שכן \u0003אי\u0004 \u0005[אם]\u0006 שיטת \u0003רבי חייא\u0004 — הרי אמרת שלדעתו \u0003אפילו לכתחלה\u0004 מותר לשחוט במחובר, \u0003אי\u0004 \u0005[אם]\u0006 שיטת \u0003רבי\u0004 — הרי ב\u0003דיעבד נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 מכשיר!","ומשיבים: \u0003לעולם\u0004 יש לפרש שלשיטת \u0003רבי חייא\u0004 שוחטים במחובר \u0003ואפילו לכתחלה, ומתניתין דקתני\u0004 \u0005[ומשנתנו שהוא שונה\u0006 בה\u0005]\u0006 \u0003\"השוחט\",\u0004 ומשמע ששחיטה במחובר כשרה רק בדיעבד — שיטת \u0003רבי היא.\u0004","ושואלים: אם כן, \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003רבי\u0004 על דברי \u0003רבי,\u0004 שהרי במחלוקתו עם ר' חייא מפורש שהוא פוסל אפילו בדיעבד! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003כאן\u0004 ששנינו שהוא פוסל בדיעבד — מדובר כששוחט \u0003ב\u0004דבר שהוא \u0003מחובר מעיקרו, כאן\u0004 ששנינו שהוא מכשיר בדיעבד — מדובר כששוחט \u0003ב\u0004דבר שהיה \u0003תלוש ולבסוף חיברו.\u0004","ומוסיפים: \u0003ומנא תימרא דשני לן\u0004 \u0005[ומנין תאמר ששונה לנו],\u0006 שיש הבדל בהלכה \u0003בין מחובר מעיקרו לתלוש ולבסוף חיברו? דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003השוחט ב\u0004אמצעות \u0003מוכני\u0004 (סוג של מכונה שקבועה בה סכין) \u0003—\u0004 \u0003שחיטתו כשרה,\u0004 וכן השוחט \u0003במחובר לקרקע\u0004 — \u0003שחיטתו כשרה,\u0004 וכן אם \u0003נעץ סכין בכותל\u0004 כשהלהב בולט החוצה \u0003ושחט בה,\u0004 שהוליך והביא את צואר הבהמה עליה — \u0003שחיטתו כשרה.\u0004 אבל אם \u0003היה צור יוצא\u0004 (בולט) כמין זיז \u0003מן הכותל,\u0004 \u0003או קנה עולה מאליו\u0004 מן הקרקע, \u0003ושחט בו\u0004 — \u0003שחיטתו פסולה;\u0004"],["ולכאורה, שני חלקי הברייתא \u0003קשיין אהדדי\u0004 \u0005[קשים\u0006 הם \u0005זה על זה],\u0006 שהרי מצד אחד שנינו שהשוחט במחובר — שחיטתו כשרה, ובסוף שנינו שהשוחט בצור היוצא מן הכותל או בקנה העולה מאליו — שחיטתו פסולה! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 כי \u0003שאני\u0004 \u0005[שונה]\u0006 הדין \u0003בין מחובר מעיקרו,\u0004 כגון צור הבולט מכותל של סלע, או קנה הצומח מאליו, \u0003ל\u0004בין \u0003תלוש ולבסוף חברו?\u0004 ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003אמר מר\u0004 \u0005[החכם]\u0006 באותה ברייתא: \u0003השוחט במוכני\u0004 — \u0003שחיטתו כשרה.\u0004 ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003שחיטתו פסולה!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003הא בסרנא דפחרא\u0004 \u0005[זו\u0006 הברייתא שמכשירה עוסקת \u0005ב\u0006סכין שמחוברת ל\u0005גלגל של יוצר כלי חרס],\u0006 שהוא מניע את הגלגל ברגלו ומקרב אליו את צואר הבהמה, וכך הוא שוחט, ושחיטה זו כשרה משום שנעשית בכוחו. \u0003הא בסרנא דמיא\u0004 \u0005[זו\u0006 שפוסלת עוסקת \u0005בגלגל שמונע בכוח המים],\u0006 ששחיטתו פסולה, מפני שאינה נעשית בכוח אדם.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003הא והא בסרנא דמיא\u0004 \u0005[זו וזו\u0006 עוסקת \u0005בגלגל של מים],\u0006 \u0003ולא קשיא\u0004 \u0005[ואינו קשה]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 מדברת \u0003בכח ראשון,\u0004 שהשחיטה מתבצעת מיד כשמאפשר למים לזרום ולסובב את הגלגל שהסכין קבועה בו, \u0003הא\u0004 \u0005[זה]\u0006 \u0003בכח שני,\u0004 לאחר שהגלגל הסתובב פעם נוספת מחמת המים.","\u0003וכי הא\u0004 \u0005[וכמו זו]\u0006 ש\u0003אמר רב פפא\u0004 לענין אחר: \u0003האי מאן דכפתיה לחבריה ואשקיל עליה בידקא דמיא ומית\u0004 \u0005[מי שכפת את חבירו והיטה לעברו שטף מים ומת]\u0006 — \u0003חייב\u0004 משום רוצח, \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 והרי לא הרגו בידים! מפני ש\u0003גירי דידיה הוא דאהני ביה\u0004 \u0005[חיציו שלו הוא שהועילו בו],\u0006 וכאילו ירה בו חיצים. והוסיף רב פפא: \u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 אמורים \u0003בכח ראשון,\u0004 כלומר, שחבירו היה קרוב אליו, ומיד כשאיפשר למים לזרום נחנק על ידם, \u0003אבל בכח שני,\u0004 לאחר שהמים זרמו בעצמם — אין זה מעשה שלו, אלא \u0003גרמא בעלמא\u0004 \u0005[גורם בלבד]\u0006 \u0003הוא,\u0004 ופטור.","בענין שעסקנו בו תחילה, מסופר: \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב אחוריה\u0004 \u0005[אחרי]\u0006 \u0003רבי חייא, ורבי חייא\u0004 ישב \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רבי, ויתיב\u0004 \u0005[ויושב]\u0006 היה \u0003רבי וקאמר\u0004 \u0005[ואומר]:\u0006 \u0003מנין לשחיטה שהוא\u0004 דווקא \u0003בתלוש? שנאמר\u0004 באברהם: \u0003\"ויקח את המאכלת לשחוט\"\u0004 (בראשית כב, י), הרי שצריך לקחת בידו דבר כדי לשחוט בו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב לרבי חייא: מאי קאמר\u0004 \u0005[מה הוא אומר]?\u0006 מה טיבה של הוכחה \u0003זו?\u0004 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003וי\"ו דכתיב אאופתא קאמר\u0004 \u0005[וי\"ו שכתובה על עץ מבוקע אמר],\u0006 כלומר, דבר שאין בו ממש. ושואלים: \u0003והא קרא קאמר\u0004 \u0005[והרי מקרא הוא אומר]\u0006 כראיה לדבריו! ומשיבים: \u0003קרא זריזותיה\u0004 \u0005[המקרא\u0006 רק את \u0005זריזותו]\u0006 של \u0003אברהם קא משמע לן\u0004 \u0005[משמיע לנו],\u0006 שהיתה לו סכין מוכנה לידו לשם כך, ואין ללמוד מכאן איך צריכה להיות השחיטה.","ובענין שחיטה בדבר שהיה תלוש וחיברו, מביאים מה ש\u0003אמר רבא: פשיטא\u0004 \u0005[פשוט]\u0006 \u0003לי,\u0004 דבר שהיה \u0003תלוש ולבסוף חברו, לענין\u0004 \u0003עבודה זרה הוי\u0004 \u0005[הרי הוא]\u0006 נידון כ\u0003תלוש. דאמר מר\u0004 \u0005[שאמר החכם]:\u0006 \u0003המשתחוה לבית שלו\u0004 — \u0003אסרו\u0004 בהנאה, כדין עבודה זרה, \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 שתלוש ולבסוף חיברו \u0003הוי\u0004 \u0005[הריהו]\u0006 נחשב \u0003מחובר,\u0004 מדוע נאסר? הרי נאמר בענין עבודה זרה \u0003\"אלהיהם על ההרים\"\u0004 (דברים יב, ב), ומשם דייקו חכמים — \u0003ולא ההרים\u0004 עצמם \u0003אלהיהם,\u0004 שדבר המחובר לקרקע אינו נאסר משום עבודה זרה! אלא מכאן שהתלוש שחיברו, כגון בית הבנוי מאבנים תלושות שחוברו לקרקע, נדון כתלוש.","והוסיף רבא, \u0003לענין הכשר זרעים\u0004 (ושאר אוכלים) לקבלת טומאה — \u0003תנאי\u0004 \u0005[מחלוקת תנאים]\u0006 \u0003היא\u0004 מה דינו של תלוש ואחר כך חיברו. \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003הכופה\u0004 (הופך) \u0003קערה על הכותל בשביל שתודח,\u0004 כדי שישטפו אותה הגשמים היורדים על הכותל — \u0003הרי זה ב\"כי יותן\",\u0004 כלומר, המים שנפלו עליה מכשירים אוכלים לקבלת טומאה. משום שירדו לרצונו על הקערה. אבל אם כפה את הקערה רק \u0003בשביל שלא ילקה\u0004 (יינזק) \u0003הכותל,\u0004 ואינו מעוניין במים — \u0003אינו ב\"כי יותן\".\u0004","ויש לשאול: \u0003הא גופא קשיא\u0004 \u0005[\u0006משנה \u0005זו עצמה קשה]\u0006 מתוכה, שכן מתחילה \u0003אמרת\u0004 \u0005[אומר אתה]:\u0006 כפה את הקערה \u0003בשביל שתודח\u0004 הקערה עצמה — \u0003הרי זה ב\"כי יותן\",\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם עשה זאת \u0003בשביל שיודח הכותל,\u0004 להביא עליו את מי הגשמים באמצעות הקערה — \u0003אין זה ב\"כי יותן\",\u0004 שאין מים מכשירים אם חשב עליהם לשם דבר מחובר,","\u0003והדר תני\u0004 \u0005[וחזר ושנה]:\u0006 כפה את הקערה \u0003בשביל שלא ילקה הכותל\u0004 — \u0003אינו ב\"כי יותן\",\u0004 ומכאן נדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם כפאה \u0003בשביל שיודח הכותל\u0004 — \u0003הרי זה ב\"כי יותן\"!\u0004","ובהסבר הדבר \u0003אמר ר' אלעזר: תברא\u0004 \u0005[שבורה]\u0006 המשנה, ו\u0003מי ששנה זו,\u0004 את ההלכה הראשונה, \u0003לא שנה זו,\u0004 את ההלכה השניה. ונמצא כי יש במשנה זו מחלוקת תנאים, האם כותל, שהוא תלוש וחיברו, נחשב כמחובר או כתלוש, וכדברי רבא. \u0003רב פפא אמר: כולה חד תנא\u0004 \u0005[כשיטת תנא אחד]\u0006 \u0003הוא,\u0004 הסבור שתלוש וחיברו דינו כתלוש לענין זה. אלא \u0003הא\u0004 \u0005[\u0006הלכה \u0005זו,\u0006 הראשונה\u0005]\u0006 שממנה דייקנו שאם רצונו שיודח הכותל אין זה ב\"כי יותן\", עוסקת \u0003בכותל\u0004 של \u0003מערה,\u0004 שהוא מחובר מתחילתו. \u0003הא\u0004 \u0005[\u0006הלכה \u0005זו,\u0006 השניה\u0005]\u0006 שדייקנו ממנה שאם רצינו שיודח הכותל הרי זה ב\"כי יותן\", עוסקת \u0003בכותל בנין,\u0004 שנבנה מאבנים שהיו תלושות.","\u0003והכי קאמר\u0004 \u0005[וכך הוא אומר]:\u0006 \u0003הכופה קערה על הכותל בשביל שתודח\u0004 — \u0003הרי זה ב\"כי יותן\", הא\u0004 \u0005[הרי]\u0006 אם כפאה \u0003בשביל שיודח הכותל\u0004 — \u0003אין זה ב\"כי יותן\".\u0004","\u0003במה דברים אמורים? בכותל מערה\u0004, משום שכותל המערה מחובר לקרקע מעיקרו. \u0003אבל בכותל בנין\u0004 — אם כפאה \u0003בשביל שלא ילקה הכותל\u0004 — \u0003הוא\u0004 ש\u0003אינו ב\"כי יותן\",\u0004 מפני שאינו רוצה במים, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003בשביל שיודח הכותל\u0004 — \u0003הרי זה ב\"כי יותן\".\u0004 וממשיכים בדברי רבא.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא:\u0004"],["\u0003תלוש ולבסוף חברו לענין שחיטה מאי\u0004 \u0005[מה דינו]?\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 תשובה לדבר ממה ששנינו בברייתא: \u0003היה צור יוצא מן הכותל, או שהיה קנה עולה מאליו ושחט בו\u0004 — \u0003שחיטתו פסולה.\u0004 והרי הכותל עצמו הוא תלוש ולבסוף חיברו, שנעשה מאבנים שנחצבו (\"נתלשו\")!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003בכותל מערה,\u0004 סלע שזיז חד יוצא ממנו, והרי זה מחובר מעיקרו. ומעירים: \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 הדבר מלשון הברייתא, \u0003דקתני\u0004 \u0005[ש\u0006הרי \u0005הוא שונה]\u0006 צור \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003קנה\u0004 ש\u0003עולה מאליו,\u0004 שצומח מן הקרקע. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא, ואין מכאן ראיה.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 תשובה לדבר ממה ששנינו באותה ברייתא: \u0003נעץ סכין בכותל ושחט בה\u0004 — \u0003שחיטתו כשרה,\u0004 הרי שסכין שהיא תלושה וחיברה — כשרה לשחיטה! ודוחים: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003סכין, דלא מבטל ליה\u0004 \u0005[שאינו מבטל אותה]\u0006 לגבי הכותל, שאין אדם מתכוון לעשותה חלק מן הכותל, ולכן הרי זה כשוחט בתלוש.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו שם מתחילה: \u0003במחובר לקרקע\u0004 — \u0003שחיטתו כשרה,\u0004 ובהכרח הכוונה היא לתלוש ולבסוף חיברו, שהרי בהמשך הברייתא שנינו שאם שחט בצור היוצא מן הכותל שחיטתו פסולה! ודוחים: \u0003דלמא\u0004 \u0005[שמא]\u0006 אין הלכה זו עומדת לעצמה, אלא מה שהוא שונה מיד לאחר מכן: נעץ סכין בכותל ושחט בה, \u0003פרושי קא מפרש לה\u0004 \u0005[פירוש הוא שמפרש]\u0006 אותה: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 ב\u0003מחובר לקרקע\u0004 — ב\u0003סכין, דלא מבטל ליה\u0004 \u0005[שאינו מבטל אותה]\u0006 לכותל, אבל אם נעץ בה צור וכדומה, ושחט בו — שחיטתו פסולה. ולא נפתרה, איפוא, שאלתו של רבא.","ודנים במה ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003נעץ סכין בכותל ושחט בה\u0004 — \u0003שחיטתו כשרה. אמר רב ענן אמר שמואל: לא שנו אלא שהסכין\u0004 נמצאת \u0003למעלה וצואר בהמה למטה,\u0004 והוא מגביה את הצואר ומוליך ומביא אותו על להב הסכין, \u0003אבל\u0004 כשה \u0003סכין למטה וצואר בהמה למעלה\u0004 — אין זו שחיטה כשרה, כי \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא ידרוס,\u0004 שהסימנים ייחתכו בגלל כובדה של הבהמה, ולא בדרך הולכה והבאה, ושחיטה פסולה היא.","ומקשים: \u0003והא קתני\u0004 \u0005[והרי הוא שונה]\u0006 בברייתא במפורש: בכל שוחטין, בין בתלוש בין במחובר, \u0003בין שהסכין למטה וצואר בהמה למעלה, בין שהסכין למעלה וצואר בהמה למטה!\u0004","\u0003אמר רב זביד, לצדדין קתני\u0004 \u0005[הוא שונה]\u0006 הלכה זו, במקביל לשתי האפשרויות ששנה מתחילה, בתלוש ובמחובר; מה שהוא שונה \u0003סכין למטה וצואר בהמה למעלה\u0004 — הוא דווקא \u0003בתלוש,\u0004 שנוטל סכין בידו ושוחט, ומה שהוא שונה \u0003סכין למעלה וצואר בהמה למטה\u0004 — הוא \u0003במחובר. רב פפא אמר\u0004 הסבר אחר: מה ששנינו ששוחטין אפילו במחובר כשהסכין למטה, הוא \u0003בעופא דקליל\u0004 \u0005[בעוף, שהוא קל],\u0006 ואין חשש ללחץ עד שיגרום לדריסה.","\u0003אמר רב חסדא אמר ר' יצחק, ואמרי לה במתניתא תנא\u0004 \u0005[ויש אומרים שבברייתא היא שנויה],\u0006 \u0003חמשה דברים נאמרו בקרומית\u0004 (קליפה) \u0003של קנה,\u0004 שהיא חדה, ואנשים משתמשים בה לחיתוך: \u0003אין שוחטין בה,\u0004 מפני שבשעת החיתוך קיסמים נפרדים ממנה וננעצים בקנה ובוושט ופוגמים את השחיטה. \u0003ו\u0004לכן גם \u0003אין מלין בה,\u0004 מחשש סכנה. \u0003ואין מחתכין בה בשר\u0004 שמא יינעצו בתוכו חתיכות קטנות ויבוא לידי סכנה. \u0003ואין מחצצין בה\u0004 \u0003שינים,\u0004 שמא ייפצע בה. \u0003ואין מקנחים בה\u0004 לאחר עשיית צרכים.","ודנים בדבר. על מה שנאמר: \u0003אין שוחטין בה\u0004, תוהים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא מפורשת\u0005],\u0006 \u0003בכל שוחטין: בין בצור, בין בזכוכית, בין בקרומית של קנה! אמר רב פפא:\u0004 שם מדובר \u0003ב\u0004צמח הקרוי \u0003סימונא דאגמא\u0004 \u0005[קנה של אגם],\u0006 שכשהוא מתייבש הריהו מתקשה ואינו נפגם.","ועל מה שנאמר: \u0003ואין מחתכין בה בשר,\u0004 מסופר ש\u0003רב פפא\u0004 היה \u0003מחתך בה קרבי דגים,\u0004 מפני \u0003דזיגי\u0004 \u0005[שהם שקופים],\u0006 ואפשר לראות אם נשארו בהם קיסמים. \u0003רבה בר רב הונא\u0004 היה \u0003מחתך בה עופא דרכיך\u0004 \u0005[עוף, ש\u0006בשרו \u0005רך],\u0006 ואין חשש שתיפגם הקרומית ויצאו ממנה קיסמים.","ועל מה שנאמר: \u0003ואין מקנחין בה,\u0004 שואלים: \u0003תיפוק ליה\u0004 \u0005[תצא לו]\u0006 הלכה זו \u0003משום\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003המקנח ב\u0004כל \u0003דבר שהאור\u0004 (האש) \u0003שולטת בו,\u0004 כלומר, דבר שמתלקח בקלות — \u0003שיניו\u0004 (שבאזור פי הטבעת) \u0003נושרות! אמר רב פפא:\u0004 לא בקינוח לאחר עשיית צרכים מדובר, אלא ל\u0003קינוח פי מכה\u0004 \u0005[פצע]\u0006 מן הדם או מלכלוך \u0003קאמרינן\u0004 \u0005[אומרים אנו].\u0006","שנינו במשנה: \u0003הכל שוחטין, ולעולם שוחטין.\u0004 ומבארים: מה שנאמר \u0003הכל שוחטין\u0004 כוונתו: \u0003הכל\u0004 דינו \u0003בשחיטה, ואפילו עוף.\u0004","ועל מה ששנינו: \u0003לעולם שוחטין,\u0004 שואלים: \u0003מאן תנא\u0004 \u0005[מיהו התנא]\u0006 שלשיטתו נאמר דבר זה? \u0003אמר רבה:\u0004 שיטת \u0003רבי ישמעאל היא. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 על הפסוק: \u0003\"כי ירחיב ה' אלהיך את גבולך כאשר דבר לך ואמרת אוכלה בשר\u0004 וכו' בכל אות נפשך תאכל בשר\" (דברים יב, כ), \u0003ר' ישמעאל אומר: לא בא הכתוב אלא להתיר להם\u0004 שחיטה ואכילה של \u0003בשר תאוה,\u0004 כלומר, בשר חולין.","\u0003שבתחלה,\u0004 כשהיו ישראל במדבר והוקם המשכן, \u0003נאסר להם בשר תאוה,\u0004 ומי שרצה לאכול בשר צריך היה לשחוט את הבהמה כקרבן בחצר המשכן, ואינו אוכלו אלא לאחר שהכהנים זורקים מדמו ומקריבים את אימוריו על המזבח. \u0003משנכנסו לארץ הותר להם בשר תאוה,\u0004 והיו רשאים לשחוט ולאכול בכל מקום.","והוסיף רבה: \u0003ועכשיו שגלו\u0004 מן הארץ \u0003יכול יחזרו לאיסורן הראשון? לכך שנינו\u0004 במשנתנו: \u0003לעולם שוחטין\u0004 בשר חולין.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יוסף: האי\u0004 \u0005[זה]\u0006 הביטוי \u0003\"לעולם שוחטין\"\u0004 אינו מתאים לפירוש זה, אלא \u0003לעולם שוחטין ואוכלין מבעי ליה\u0004 \u0005[צריך היה לו לומר],\u0006 שהרי עיקר ההיתר הוא האכילה, ולא השחיטה! \u0003ועוד, מעיקרא מאי טעמא איתסר\u0004 \u0005[מתחילה,\u0006 במדבר, \u0005מה טעם נאסר]\u0006 עליהם בשר תאוה — \u0003משום דהוו מקרבי\u0004 \u0005[שהיו קרובים]\u0006 \u0003למשכן,\u0004 ויכולים היו לאכול בשר כקרבן, כסמוכים על שולחנו של מקום, \u0003ולבסוף\u0004 כשנכנסו לארץ \u0003מאי טעמא אישתרו\u0004 \u0005[מה טעם הותרו]\u0006 — משום \u0003דהוו מרחקי\u0004 \u0005[שהיו רחוקים]\u0006 \u0003מ\u0004ה\u0003משכן,\u0004"],["\u0003ו\u0004אם כן \u0003כל שכן השתא דארחיקו להו טפי\u0004 \u0005[עכשיו,\u0006 שגלו \u0005שהרחיקו להם יותר],\u0006 שיהיו מותרים לשחוט לצורך בשר תאוה!","\u0003אלא אמר רב יוסף:\u0004 מה ששנינו \"לעולם שוחטין\" — לשיטת \u0003רבי עקיבא היא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"כי ירחק ממך המקום אשר יבחר ה' אלהיך לשום שמו שם וזבחת מבקרך ומצאנך\"\u0004 (דברים יב, כא), \u0003ר' עקיבא אומר: לא בא הכתוב אלא לאסור להן\u0004 לבני ישראל \u0003בשר נחירה,\u0004 כלומר, בשר בהמה שהומתה שלא בשחיטה ראויה על פי התורה. \u0003שבתחלה,\u0004 בהיותם במדבר, \u0003הותר להן בשר נחירה, משנכנסו לארץ נאסר להן בשר נחירה,\u0004 ואין אוכלים בשר אלא לאחר שנשחט כראוי. ומוסיף רב יוסף:","\u0003ועכשיו שגלו, יכול יחזרו להתירן הראשון? לכך שנינו\u0004 במשנתנו: \u0003לעולם שוחטין,\u0004 מצווים בשחיטה דווקא.","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עיקרון \u0005הם,\u0006 ר' ישמעאל ור' עקיבא \u0005חולקים]?\u0006 ומשיבים, \u0003רבי עקיבא סבר\u0004 \u0005[סבור]:\u0006 \u0003בשר תאוה לא איתסר\u0004 \u0005[נאסר]\u0006 \u0003כלל,\u0004 וגם במדבר היו מותרים בו, ולכן לא הוצרך הכתוב להתירו בכניסתם לארץ. ואילו \u0003ר' ישמעאל סבר\u0004 \u0005[סבור]:\u0006 \u0003בשר נחירה לא אישתרי\u0004 \u0005[לא הותר]\u0006 \u0003כלל,\u0004 וכבר במדבר היו חייבים לשחוט, ולא הוצרך לאוסרו בארץ.","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רבי ישמעאל\u0004 שבשר נחירה אסור היה במדבר — \u0003היינו דכתיב\u0004 \u0005[זה שנאמר]\u0006 ביחס לקרבן העולה באהל מועד שבמדבר: \u0003\"ושחט את בן הבקר\"\u0004 (ויקרא א, ה), \u0003אלא לרבי עקיבא מאי\u0004 \u0005[מהו]\u0006 \u0003\"ושחט\"?\u0004 והרי לשיטתו היו מותרים בנחירה! ומשיבים: \u0003קדשים שאני\u0004 \u0005[שונים],\u0006 שדינם היה תמיד בשחיטה, אבל בחולין לא היתה חובת שחיטה.","ועוד שואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רבי ישמעאל,\u0004 שבמדבר היתה שחיטה ולא נחירה — \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 כשהיו במדבר: \u0003\"הצאן ובקר ישחט להם\"\u0004 (במדבר יא, כב), \u0003אלא ל\u0004שיטת \u0003ר' עקיבא מאי\u0004 \u0005[מה פירוש]\u0006 \u0003\"הצאן ובקר ישחט להם\"? \"ינחר להם\" מיבעי ליה\u0004 \u0005[צריך היה לו לומר]!\u0006 ומשיבים: \u0003נחירה שלהן זו היא שחיטתן.\u0004","ועוד שואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' ישמעאל\u0004 — \u0003היינו דתנן\u0004 \u0005[זהו ששנינו\u0006 במשנה\u0005]\u0006 לענין מצות כיסוי הדם: \u0003השוחט\u0004 חיה \u0003ונתנבלה בידו,\u0004 שלא שחט כראוי, \u0003ו\u0004כן \u0003הנוחר\u0004 חיה, הורג אותה, או \u0003המעקר,\u0004 שעוקר את הקנה והוושט ממקומם קודם השחיטה — \u0003פטור מלכסות\u0004 את דמה, כדין שוחט חיה או עוף, מפני שרק שחיטה ראויה מחייבת בכיסוי הדם, \u0003אלא לר' עקיבא אמאי\u0004 \u0005[מדוע]\u0006 \u0003פטור מלכסות?\u0004 הרי כבר בשעה שנצטוו על כיסוי הדם, היו מותרים בנחירה, ולשיטתו נחירתם היא שחיטתם!","ומשיבים: \u0003הואיל ואיתסר איתסר\u0004 \u0005[הואיל ונאסר\u0006 לאכול בשר נחירה \u0005נאסר],\u0006 ושוב אין זה בכלל שחיטה.","ומצד אחר שואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004דעת \u0003ר' עקיבא\u0004 ש\u0003אמר\u0004 ש\u0003בשר תאוה לא איתסר\u0004 \u0005[לא נאסר]\u0006 \u0003כלל\u0004 במדבר — \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 לפני כניסתם לארץ: \u0003\"אך כאשר יאכל את הצבי ואת האיל כן תאכלנו\u0004 הטמא והטהור יחדיו\" (דברים יב, כב), כלומר, כשם שמותרים אתם במדבר לאכול את בשר הצבי והאיל (ושאר חולין) בטומאה, כן תהיו מותרים לאוכלם בטומאה משתיכנסו לארץ, למרות שבאותה שעה כבר אינם כשרים על ידי נחירה סתם, אלא דווקא בשחיטה כקדשים (שאסור לאוכלם בטומאה). \u0003אלא לרבי ישמעאל,\u0004 הסבור שבשר תאוה היה אסור במדבר, וכי \u0003צבי ואיל גופיה\u0004 \u0005[עצמו]\u0006 \u0003מי הוי שרי\u0004 \u0005[האם היו מותרים]\u0006 במדבר?","ומשיבים: \u0003כי אסר רחמנא\u0004 \u0005[כאשר אסרה התורה]\u0006 לאכול בשר תאוה הרי זה דווקא ב\u0003בהמה דחזיא\u0004 \u0005[שראויה]\u0006 \u0003להקרבה, אבל חיה דלא חזיא\u0004 \u0005[שאינה ראויה]\u0006 \u0003להקרבה לא אסר רחמנא\u0004 \u0005[לא אסרה התורה].\u0006","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבי ירמיה:\u0004 לפי שיטת ר' עקיבא, שבמדבר הותר להם בשר נחירה, \u0003אברי בשר נחירה שהכניסו ישראל עמהן לארץ, מהו\u0004 דינם?","ושואלים: \u0003אימת\u0004 \u0005[מתי]?\u0006 על איזה זמן הוא שואל? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003בשבע\u0004 השנים הראשונות \u0003שכבשו\u0004 את הארץ, \u0003השתא\u0004 \u0005[עכשיו, הרי]\u0006 \u0003דבר טמא אישתרי להו\u0004 \u0005[הותר להם]\u0006 לאכול, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"והיה כי יביאך ה' אלקיך אל הארץ וכו' לתת לך ערים וכו' \u0003ובתים מלאים כל טוב\u0004 וגו' ואכלת ושבעת\" (דברים ו, י— יא), \u0003ו\u0004בפירוש כתוב זה \u0003אמר ר' ירמיה בר אבא אמר רב: כתלי דחזירי\u0004 \u0005[נתחי בשר חזיר]\u0006 שמצאו בבתים, גם הם היו מותרים להם, \u0003בשר נחירה\u0004 של בהמה טהורה שנחרו בהיתר \u0003מבעיא\u0004 \u0005[נצרכה לומר]\u0006 שמותר?","\u0003אלא\u0004 צריכים לומר שהשאלה היתה ביחס לבשר מיובש שנשאר עד \u0003לאחר מכאן,\u0004 לאחר שבע שנות הכיבוש. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם\u0004 מדובר \u0003בשבע\u0004 שנים \u0003שכבשו,\u0004 ולמרות זאת עומדת השאלה בעינה, שכן יש לומר: \u0003כי אשתרי להו\u0004 \u0005[כאשר הותר להם]\u0006 לאכול אפילו דבר איסור הרי זה דווקא מ\u0003שלל של גוים,\u0004 אבל \u0003דידהו לא אישתרי\u0004 \u0005[\u0006דבר איסור \u0005שלהם לא הותר].\u0006 ועל כל פנים, שאלה זו לא נפתרה ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","ושבים לדון בביאור לשון המשנה \"הכל שוחטין ולעולם שוחטין ובכל שוחטין\". \u0003אמר רבה: שנית\u0004 \u0005[תירצת,\u0006 הסברת\u0005]\u0006 מה ששנינו \u0003\"הכל שוחטין\"\u0004 שעניינו — את הכל צריך לשחוט, ואפילו עוף, \u0003ו\u0004כן \u0003\"לעולם שוחטין\"\u0004 — שדין השחיטה קיים לעולם, גם לאחר שגלו ישראל (כר' ישמעאל, או כר' עקיבא), אבל \u0003\"בכל שוחטים\" מאי משנית ליה\u0004 \u0005[איך אתה מתרץ,\u0006 מסביר \u0005אותו]?\u0006 מה הוא בא לרבות?","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שבא לומר שהשחיטה כשרה \u0003בין בצור בין בזכוכית בין בקרומית של קנה,\u0004 ולא רק בסכין — \u0003הא דומיא דהנך קתני\u0004 \u0005[הרי בדומה לאחרים הוא שונה],\u0006 \"הכל שוחטין ולעולם שוחטין\", ואם כן, \u0003אי הנך\u0004 \u0005[אם האחרים]\u0006 מדברים על ה\u0003שוחטין\u0004 — \u0003האי נמי\u0004 \u0005[זה גם כן]\u0006 מדבר \u0003בשוחטין, ואי הנך\u0004 \u0005[ואם אלה]\u0006 מדברים \u0003בנשחטין\u0004 — \u0003האי נמי\u0004 \u0005[זה גם כן]\u0006 \u0003בנשחטין.\u0004 והרי \"הכל שוחטין\" פירשנו בנשחטים — הכל נשחטים, וכן \"לעולם שוחטין\" — אין בשר נאכל אלא בשחיטה, וכיצד ניתן לפרש \"בכל שוחטין\"?","\u0003אלא אמר רבא:\u0004 צריך להסביר את כל המשנה באופן אחר, מה שנאמר \u0003\"הכל שוחטין\"\u0004 כוונתו שכל האנשים כשרים לשחוט. ואף ששנינו דבר זה בתחילת המסכת (ב,א), הוצרך לשניהם, \u0003חדא לאתויי\u0004 \u0005[אחת להביא,\u0006 להוסיף\u0005]\u0006 \u0003כותי,\u0004 שגם הוא שוחט, \u0003וחדא לאתויי\u0004 \u0005[ואחת להביא]\u0006 \u0003ישראל משומד.\u0004 מה שנאמר \u0003\"לעולם שוחטין\"\u0004 — כוונתו \u0003בין ביום, בין בלילה, בין בראש הגג, בין בראש הספינה,\u0004 ואין חוששים שמא ייראה כשוחט לצבא השמים או לשר הים. \u0003\"בכל שוחטין\"\u0004 — כוונתו בכל דבר, \u0003בין בצור, בין בזכוכית, בין בקרומית של קנה.\u0004","שנינו במשנה: \u0003חוץ ממגל קציר והמגירה\u0004 (משור) שאין שוחטים בהם. מסופר, \u0003אבוה\u0004 \u0005[אביו]\u0006 של \u0003שמואל פגם\u0004 \u0005[היה עושה פגם]\u0006 בסכין \u0003ושדר\u0004 \u0005[ושולח]\u0006 לארץ ישראל לשאול אם כשר הוא, ושוב \u0003פגם ושדר\u0004 \u0005[היה פוגם\u0006 באופן אחר \u0005ושולח],\u0006 כדי לדעת מהי פגימה שפוסלת. \u0003שלחו ליה\u0004 \u0005[לו],\u0006 הכלל הוא: \u0003כמגירה שנינו,\u0004 כמו שיניים של משור שנו שהן פונות כלפי מעלה, ולא הצידה, ובכל הולכה או הבאה של הסכין, הריהי פוגמת את השחיטה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006"],["\u0003סכין שיש בה פגימות הרבה\u0004 — \u0003תידון\u0004 (תיחשב) \u0003כמגירה, ושאין בה אלא פגימה אחת,\u0004 אם היא \u0003אוגרת\u0004 — \u0003פסולה,\u0004 אם היתה \u0003מסוכסכת\u0004 — \u0003כשרה.\u0004 ושואלים: \u0003היכי דמיא\u0004 \u0005[איך היא בדיוק]\u0006 \u0003אוגרת, היכי דמיא\u0004 \u0005[איך היא בדיוק]\u0006 \u0003מסוכסכת? אמר ר' אליעזר: אוגרת\u0004 — שיש לפגימה עוקצים \u0003משתי רוחות,\u0004 משני צידיה, \u0003מסוכסכת\u0004 — שיש עוקץ \u0003מרוח אחת\u0004 של הפגימה.","ושואלים: \u0003מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 \u0003משתי רוחות\u0004 שהיא פסולה — מפני \u0003דמורשא קמא מחליש ומורשא בתרא בזע\u0004 \u0005[שהעוקץ הראשון מחליש,\u0006 מוריד את העור והבשר, \u0005והעוקץ האחר קורע]\u0006 את הסימנים. והרי כאשר יש עוקץ \u0003מרוח אחת נמי\u0004 \u0005[גם כן]\u0006 \u0003חורפא דסכינא מחליש מורשא בזע\u0004 \u0005[חוד הסכין מחליש,\u0006 חותך את העור והבשר, \u0005והעוקץ קורע]\u0006 את הסימנים! ומשיבים: מדובר בעוקץ \u0003דקאים ארישא דסכינא\u0004 \u0005[שנמצא בראש הסכין],\u0006 במקום בו מתחילה השחיטה, כך שהעור נקרע על ידי העוקץ, ולא הסימנים. ואומרים: \u0003סוף סוף,\u0004 הואיל והשחיטה נעשית גם בהולכה וגם בהבאה של הסכין, \u0003כי אזלא מחלשא\u0004 \u0005[כאשר\u0006 העוקץ \u0005הולך הוא מחליש],\u0006 \u0003כי אתא בזע\u0004 \u0005[וכאשר הוא\u0006 חוזר ו\u0005בא הוא קורע]!\u0006 ומשיבים: מדובר \u0003כגון שהוליך\u0004 את הסכין \u0003ולא הביא\u0004 אותה חזרה.","ובסיכום הדברים להלכה \u0003אמר רבא, שלש מדות בסכין:\u0004 אם היתה \u0003אוגרת\u0004 — \u0003לא ישחוט\u0004 בה, \u0003ואם שחט\u0004 בה — \u0003שחיטתו פסולה. מסוכסכת\u0004 — \u0003לא ישחוט בה לכתחלה, ואם שחט\u0004 — \u0003שחיטתו כשרה\u0004 בדיעבד. אם היה \u0003עולה ויורד בסכין,\u0004 שלא היו בה עוקצים, אלא מעלות ומורדות — \u0003שוחט בה לכתחלה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמיה לרב אשי, אמרת לן משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: מסוכסכת\u0004 — \u0003פסולה, והא\u0004 \u0005[והרי]\u0006 \u0003אמר רבא: מסוכסכת\u0004 — \u0003כשרה\u0004 בדיעבד! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003כאן שהוליך והביא\u0004 הרי היא פסולה אף בדיעבד, \u0003כאן שהוליך ולא הביא\u0004 הריהי כשרה בדיעבד.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אויא לרב אשי:\u0004 אם הסכין \u0003דמיא לסאסאה\u0004 \u0005[דומה לשער השיבולת]\u0006 שאינה חלקה לגמרי, אבל אין בה פגימות של ממש, \u0003מאי\u0004 \u0005[מה]\u0006 דינה? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאן יהיב לן מבשריה ואכלינן\u0004 \u0005[מי יתן לנו מבשרה ונאכל],\u0006 כלומר, כשרה לגמרי.","\u0003אמר רב חסדא: מנין לבדיקת סכין\u0004 שהיא חובה \u0003מן התורה? שנאמר: \"ושחטתם בזה ואכלתם\"\u0004 (שמואל א יד, לד), ומשמע שבדק סכין תחילה, ונתן להם לשחוט בה. ומתקשים:","\u0003פשיטא\u0004 \u0005[פשוט]\u0006 הדבר שסכין צריכה בדיקה לפני השחיטה, \u0003כיון דכי נקב\u0004 \u0005[שאם עשה\u0006 על ידה \u0005נקב]\u0006 בוושט הרי זו \u0003טריפה,\u0004 ולשם כך אין צורך בלימוד מן הכתוב! ומשיבים: מנין שהסכין \u0003בעיא\u0004 \u0005[צריכה]\u0006 \u0003בדיקה לחכם קאמרינן\u0004 \u0005[אומרים אנו],\u0006 ולא די שהשוחט עצמו בודק. ומקשים: וכי מן התורה הוא? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבי יוחנן: לא אמרו\u0004 חכמים \u0003להראות סכין לחכם אלא מפני כבודו של חכם!\u0004 ומשיבים: אכן, דבר זה הוא רק \u0003מדרבנן\u0004 \u0005[מדברי סופרים],\u0006 \u0003וקרא\u0004 \u0005[והפסוק]\u0006 \u0003אסמכתא בעלמא\u0004 \u0005[סמך בלבד]\u0006 \u0003הוא,\u0004 ולא ראיה גמורה.","ומעירים: \u0003במערבא בדקי לה בשימשא\u0004 \u0005[במערב,\u0006 בארץ ישראל \u0005היו\u0006 \u0005בודקים את הסכין בשמש]\u0006 לראות אם יש בה פגם. \u0003בנהרדעא בדקו לה במיא\u0004 \u0005[היו בודקים אותה במים]\u0006 שמעבירים את הלהב על המים, ואם היה נוצר מעין חריץ במים הריהו סימן לפגימה. \u0003רב ששת בדק לה בריש לישניה\u0004 \u0005[היה בודק אותה בקצה לשונו].\u0006 \u0003רב אחא בר יעקב בדק לה\u0004 \u0005[היה בודק אותה]\u0006 \u0003בחוט השערה,\u0004 שהיה מעביר על הסכין לראות אם הוא נתקל בפגימה.","\u0003בסורא אמרי\u0004 \u0005[אמרו]:\u0006 \u0003בישרא אכלה, בישרא לבדקה\u0004 \u0005[\u0006את ה\u0005בשר\u0006 הסכין \u0005אוכלת, הבשר יבדוק אותה],\u0006 שיש לבדוק את הפגימה בבשר דווקא, כגון בקצה הלשון (או בקצה האצבע), שהרי החשש היא שמא תפגום בבשר. \u0003אמר רב פפא: צריכא\u0004 \u0005[צריכה]\u0006 הסכין \u0003בדיקה אבישרא ואטופרא ואתלתא רוחתא\u0004 \u0005[על הבשר ועל הציפורן, ועל שלוש רוחות],\u0006 שיבדוק את חוד הסכין, וגם את שני צידיו, שמא נפגמה הסכין מן הצד, ועוקץ בולט ממנה וקורע את הסימנים.","ובענין זה מסופר, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי, אמר לן\u0004 \u0005[לנו]\u0006 \u0003רב סמא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב משרשיא משמך, דאמרת ליה משמיה\u0004 \u0005[שאמרת לו משמו]\u0006 של \u0003רבא: צריכא\u0004 \u0005[צריכה]\u0006 הסכין \u0003בדיקה אבישרא ואטופרא ואתלתא רוחתא\u0004 \u0005[על הבשר ועל הציפורן ועל שלוש רוחות].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003אבישרא ואטופרא אמרי\u0004 \u0005[על הבשר ועל הציפורן אמרתי],\u0006 \u0003ואתלתא רוחתא לא אמרי\u0004 \u0005[ועל שלוש רוחות לא אמרתי].\u0006 אלא די שיבדוק את החוד. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שכן השיב רב אשי: \u0003אבישרא ואטופרא ואתלתא רוחתא אמרי\u0004 \u0005[על הבשר ועל הציפורן ועל שלוש רוחות אמרתי],\u0006 אבל \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא לא אמרי\u0004 \u0005[אמרתי]\u0006 דבר זה, אלא כהלכה \u0003סתם.\u0004","מסופר, \u0003רבינא ורב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא הוו יתבי קמיה\u0004 \u0005[היו יושבים לפני]\u0006 \u0003רב אשי, אייתו\u0004 \u0005[הביאו]\u0006 \u0003סכין לקמיה\u0004 \u0005[לפני]\u0006 \u0003רב אשי לבדקה, אמר ליה\u0004 \u0005[לו]\u0006 רב \u0003אשי\u0004 \u0003לרב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא: בידקא\u0004 \u0005[בדוק אותה],\u0006 \u0003בדקה אטופרא ואבישרא ואתלתא רוחתא\u0004 \u0005[בדק אותה על הציפורן\u0006 ו\u0005על הבשר ועל שלוש רוחות].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003יישר\u0004 \u0005[יפה הדבר],\u0006 \u0003וכן אמר רב כהנא\u0004 שכך צריך לבדוק.","ואילו \u0003רב יימר אמר: אטופרא ואבישרא צריכא\u0004 \u0005[על ציפורן ועל בשר צריכה\u0006 בדיקה\u0005],\u0006 \u0003אתלתא רוחתא לא צריכא\u0004 \u0005[על שלוש רוחות אינה צריכה];\u0006 וטעם הדבר: \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא אמר ר' זירא אמר שמואל: ליבן סכין ו\u0004מיד \u0003שחט בה\u0004 — \u0003שחיטתו כשרה,\u0004 ואין לחשוש שהוושט נפגם מן הכויה והבהמה נעשית טריפה קודם החיתוך, מפני \u0003שחידודה\u0004 החיתוך בחוד הסכין \u0003קודם ל\u0004כויה שגורם \u0003ליבונה; וקשיא לן\u0004 \u0005[והיה קשה לנו]:\u0006 \u0003האיכא\u0004 \u0005[הרי יש]\u0006 ה\u0003צדדין\u0004 של הסכין שהם גורמים לכויה! \u0003ואמרינן\u0004 \u0005[ואמרנו]\u0006 כתשובה לכך: \u0003בית השחיטה מרווח רווח\u0004 \u0005[מתרווח],\u0006 כשמותח את הצואר וחותך, ולכן אין צידי הסכין נוגעים בו. ולפי זה, \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 לענין החשש מפגימה שיש בצידי הסכין, יש לומר כי \u0003בית השחיטה מרווח רווח\u0004 \u0005[מתרווח],\u0006 ולכן צידי הסכין אינם נוגעים בו.","\u0003אמר רב הונא בר רב קטינא אמר רבי שמעון בן לקיש, שלש פגימות הן,\u0004 שיש להן שיעור אחד: \u0003פגימת עצם בפסח,\u0004 שנאמר: \"ועצם לא תשברו בו\" (שמות יב, מו). \u0003פגימת אוזן בבכור\u0004 בהמה, כדי להחשיבו כבעל מום שאינו ראוי להקרבה, ומותר לכהן לשוחטו בכל מקום ולאוכלו. וכן \u0003פגימת מום ב\u0004שאר \u0003קדשים.\u0004","\u0003ורב חסדא אמר: אף פגימת סכין\u0004 של שחיטה. ושואלים: \u0003ואידך\u0004 \u0005[והאחר],\u0006 ר' שמעון בן לקיש, מדוע לא מנה זאת? ומשיבים: \u0003ב\u0004ענייני \u0003חולין לא קא מיירי\u0004 \u0005[אינו עוסק]\u0006 אלא רק בקדשים.","והוסיף: \u0003וכולן,\u0004 כל הפגימות הללו, שיעור \u0003פגימתן כדי\u0004 שיעור \u0003פגימת המזבח,\u0004 שאם היה נפגם כך לא היה ראוי להקרבה."],["\u0003וכמה פגימת המזבח? כדי שתחגור\u0004 (תתעכב) \u0003בה צפורן.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים על כך]\u0006 ממה ששנינו בברייתא: \u0003כמה\u0004 שיעור \u0003פגימת המזבח? ר' שמעון בן יוחאי אומר: טפח, ר' אליעזר בן יעקב אומר: כזית!\u0004 ומתרצים: \u0003לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 ששנינו שצריך שתהא הפגימה טפח או כזית כדי לפוסלו — \u0003בסידא\u0004 \u0005[בסיד]\u0006 שמצפים בו את המזבח, \u0003הא\u0004 \u0005[זו]\u0006 שאמרנו שדי בחגירת ציפורן כדי לפסול — \u0003באבנא\u0004 \u0005[באבן]\u0006 עצמה.","\u0003אמר רב הונא: האי טבחא דלא סר סכינא קמי\u0004 \u0005[טבח,\u0006 שוחט \u0005זה שלא הראה סכינו לפני]\u0006 ה\u0003חכם\u0004 — \u0003משמתינן ליה\u0004 \u0005[מנדים אותו].\u0006 \u0003ורבא אמר: מעברינן ליה\u0004 \u0005[מעבירים אותו]\u0006 מתפקידו, \u0003ומכרזינן אבשריה\u0004 \u0005[ומכריזים על בשרו]\u0006 על הבשר ששחט, ש\u0003טרפה היא.\u0004","ומעירים: \u0003ולא פליגי\u0004 \u0005[ואינם חלוקים]:\u0006 \u0003כאן,\u0004 שרק מנדים אותו — \u0003בשנמצאת סכינו יפה,\u0004 ורק מנדים אותו על שזלזל בכבוד החכם. \u0003כאן,\u0004 כשמעבירים אותו ואף מכריזים על הבשר שהוא טריפה — \u0003בשלא נמצאת סכינו יפה,\u0004 שיש לחשוש לכל מה ששחט. \u0003רבינא אמר: היכא\u0004 \u0005[במקום]\u0006 ש\u0003לא נמצאת סכינו יפה\u0004 — \u0003ממסמס ליה בפרתא\u0004 \u0005[מורח אותו,\u0006 את הבשר \u0005בפרש,\u0006 צואה\u0005]\u0006 ש\u0003אפילו לגוי נמי לא מזדבן\u0004 \u0005[גם כן לא יימכר].\u0006","\u0005ומסופר,\u0006 \u0003ההוא טבחא דלא סר סכינו קמיה\u0004 \u0005[\u0006מעשה ב\u0005טבח אחד שלא הראה את סכינו לפני]\u0006 \u0003רבא בר חיננא\u0004 שהיה ממונה על כך במקומו, \u0003שמתיה ועבריה ואכריז אבשריה\u0004 \u0005[נידהו והעביר אותו מתפקידו והכריז שבשרו]\u0006 \u0003טרפה היא. אקלעו\u0004 \u0005[הזדמנו]\u0006 \u0003מר זוטרא ורב אשי לגביה\u0004 \u0005[אצלו]\u0006 למקומו של רבא בר חיננא, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003ליעיינו רבה במלתיה\u0004 \u0005[יעיינו חכמים בעניינו]\u0006 של שוחט זה, שמא תוכלו להקל בדינו, \u0003דתלו ביה טפלי\u0004 \u0005[שתלויים בו ילדים קטנים],\u0006 שהוא צריך לפרנסם, ואני עצמי איני יכול להכשירו לאחר שפסלתיו.","\u0003בדקה\u0004 \u0003רב אשי לסכיניה\u0004 \u0005[לסכינו]\u0006 של אותו שוחט \u0003ונמצאת יפה, ואכשריה\u0004 \u0005[והכשיר אותו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מר זוטרא\u0004 לרב אשי: \u0003ולא ליחוש מר לסבא\u0004 \u0005[ואין אדוני חושש ל\u0006כבודו של \u0005זקן],\u0006 לרבא בר חיננא, שהוא העבירו ואתה מכשירו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003שליחותיה קא עבדינן\u0004 \u0005[שליחותו אנו עושים],\u0006 שביקש מאיתנו לעיין בדבר, ומשום כך אין זה חסרון כבוד לו.","בעניין ששנינו במשנתנו שאין שוחטים בשיניים ובציפורן \u0003אמר רבה בר הונא: שן תלושה וצפורן תלושה מותר לשחוט בה לכתחלה.\u0004 ומקשים: \u0003והא אנן תנן\u0004 \u0005[והרי אנו שנינו]:\u0006 \u0003חוץ ממגל קציר והמגירה, והשינים והצפורן, מפני שהן חונקין!\u0004","ומתרצים: מ\u0003שן\u0004 על \u0003שן לא קשיא\u0004 \u0005[לא קשה]:\u0006 \u0003הא בחדא\u0004 \u0005[זו בשן אחת]\u0006 שוחטים בה לכתחילה, \u0003הא בתרתי\u0004 \u0005[זו בשתים]\u0006 אסור, מפני הרווח שביניהן, שהוא חונק (קורע) את הסימנים. מ\u0003צפורן\u0004 על \u0003צפורן לא קשיא\u0004 \u0005[אינו קשה]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 \u0003בתלושה\u0004 מותר, \u0003הא\u0004 \u0005[זו]\u0006 \u0003במחוברת\u0004 אסור.","\u0003השוחט במגל קציר\u0004 שהיא משוננת, אלא ששיניה כפופות מאד לצד אחד, ושחט \u0003בדרך הליכתה,\u0004 בכיוון שאין העוקצים פוגעים בבשר — \u0003בית שמאי פוסלין, ובית הלל מכשירין. ו\u0004לדעת הכל, \u0003אם החליקו\u0004 את \u0003שיניה\u0004 עד שאינה פוגמת — \u0003הרי היא כסכין.\u0004","\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: אף כשהכשירו בית הלל\u0004 כששחט במגל קציר בדרך הליכתה, \u0003לא הכשירו אלא לטהרה מידי נבילה,\u0004 כלומר, להחשיבה כשחוטה, ולא כנבילה שמטמאה את הנוגע בה והנושאה, \u0003אבל באכילה אסורה. אמר רב אשי: דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 הדבר מלשון המשנה, \u0003דקתני\u0004 \u0005[שהוא שונה\u0006 בה\u0005]:\u0006 \u0003\"בית שמאי פוסלין ובית הלל מכשירין\", ולא קתני\u0004 \u0005[ואינו שונה]\u0006 בלשון: \u0003\"בית שמאי אוסרין ובית הלל מתירין\",\u0004 שאין בית הלל מתירים אותה באכילה. ותוהים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 שמדובר כאן רק לענין טומאת נבילות, \u0003ליתני\u0004 \u0005[שישנה]:\u0006 \u0003בית שמאי מטמאין ובית הלל מטהרין! אלא\u0004 הביטויים \u0003פוסלין ומכשירין, ואוסרין ומתירין\u0004 — \u0003חדא מילתא היא\u0004 \u0005[דבר אחד הוא],\u0006 ואין לדקדק בלשון זו.","\u0003השוחט מתוך הטבעת\u0004 הגדולה, העליונה בין הטבעות של קנה הנשימה, \u0003ושייר בה\u0004 אפילו \u0003מלא\u0004 רוחב \u0003החוט על פני כולה,\u0004 ולא יצאה הסכין מחוץ לטבעת לכיוון הראש — \u0003שחיטתו כשרה. ר' יוסי בר' יהודה אומר:\u0004 אפילו שייר \u0003מלא חוט על פני רובה,\u0004 ולא על פני כולה — הרי זה כשר.","\u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003הלכה כר' יוסי בר' יהודה,\u0004 שאם שחט רוב טבעת — כאילו שחט כולה. \u0003ו\u0004מכל מקום \u0003אף ר' יוסי בר' יהודה לא אמר\u0004 שהשחיטה כשרה \u0003אלא בטבעת הגדולה\u0004 העליונה, \u0003הואיל ומקפת את כל הקנה,\u0004 \u0003אבל בשאר טבעות,\u0004 שהטבעת אינה שלמה, אלא רצועת בשר מחברת את קצותיה — \u0003לא,\u0004 אין שחיטתו כשרה, שאינו רשאי לשחוט בטבעת עצמה, אלא ברווח שבין טבעת לטבעת.","ותוהים: \u0003ובשאר טבעות לא\u0004 אמר? \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יוסי בר' יהודה אומר:\u0004"],["\u0003השוחט בשאר טבעות, אף על פי שאין מקיפות את כל הקנה, הואיל ומקיפות את רוב הקנה\u0004 — \u0003שחיטתו כשרה.\u0004 והוסיפה הברייתא: \u0003ומוגרמת,\u0004 ששחט למעלה מן הטבעת הגדולה שבראש הקנה, \u0003פסולה; העיד רבי חנינא בן אנטיגנוס על מוגרמת שהיא כשרה.\u0004 הרי שר' יוסי בר' יהודה מכשיר שחיטה בשאר טבעות, שלא כפי שאמרו רב ושמואל משמו!","\u0003אמר רב יוסף: רבי יוסי בר יהודה תרתי קאמר\u0004 \u0005[שני\u0006 דברים \u0005אמר],\u0006 ואילו \u0003רב ושמואל סברי כוותיה בחדא\u0004 \u0005[סבורים כמותו בדבר אחד],\u0006 שהשוחט רובו של קנה בטבעת הגדולה — הרי זה כשר, \u0003ופליגי עליה בחדא\u0004 \u0005[וחולקים עליו באחד],\u0006 שלדעתם שחיטה בשאר הטבעות אינה כשרה, הואיל ואין מקיפות את כל הקנה.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 בלשון \u0003\"לא אמר\" קאמרי\u0004 \u0005[הם אומרים],\u0006 משמע שלדעתם כך היא דעתו של ר' יוסי בר' יהודה! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר],\u0006 לכך הכוונה: \u0003הלכה כמותו בטבעת הגדולה, ואין הלכה כמותו בשאר טבעות.\u0004","מסופר, \u0003כי סליק\u0004 \u0005[כאשר עלה]\u0006 \u0003רבי זירא\u0004 מבבל לארץ ישראל \u0003אכל\u0004 בהמה שנחשבת ל\u0003מוגרמת\u0004 לפי דעת \u0003רב ושמואל,\u0004 ובארץ ישראל לא נהגו בה איסור. \u0003אמרי ליה\u0004 \u0005[אמרו לו]:\u0006 \u0003לאו מאתריה\u0004 \u0005[והאם לא ממקומם]\u0006 של \u0003רב ושמואל את\u0004 \u0005[אתה],\u0006 מבבל? ואם כן אתה צריך לנהוג כמנהגם! \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מאן אמרה\u0004 \u0005[מי אמר את ההלכה הזו]\u0006 בשם רב ושמואל? \u0003יוסף בר חייא\u0004 (הוא רב יוסף), והרי \u0003יוסף בר חייא מכולי עלמא גמיר\u0004 \u0005[מכל העולם הוא לומד],\u0006 \u0005וגם מתלמידי רב ושמואל שלא דקדקו בשמועותיהם!\u0006","\u0003שמע רב יוסף\u0004 את הערתו של ר' זירא ו\u0003איקפד\u0004 \u0005[הקפיד]\u0006 עליו, \u0003אמר:\u0004 וכי \u0003אנא מכולי עלמא גמירנא\u0004 \u0005[אני מכל העולם למדתי]?\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 \u0003מרב יהודה גמירנא\u0004 \u0005[למדתי],\u0006 ש\u0003אפילו ספיקי דגברי גריס\u0004 \u0005[ספיקות\u0006 שיש ביחס לשמות \u0005אנשים הוא גורס].\u0006 ומביאים דוגמה לכך, ש\u0003אמר רב יהודה: אמר ר' ירמיה בר אבא, ספק משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב\u0004 אמר \u0003ספק משמיה\u0004 \u0005[משמו]\u0006 של \u0003שמואל: שלשה\u0004 אנשים \u0003מתירין את הבכור\u0004 בשחיטה מחוץ למקדש כאשר היה בו מום \u0003במקום שאין\u0004 חכם \u0003מומחה.\u0004","ועוד שואלים: \u0003ו\u0004כי \u0003ר' זירא,\u0004 שכשהגיע לארץ ישראל שוב לא נהג כמנהג בבל (שאסרו מוגרמת של רב ושמואל), \u0003לית ליה\u0004 \u0005[האם אין לו,\u0006 חלוק הוא\u0005],\u0006 על מה ששנינו במשנה בענייני מנהגים, שההולך ממקום למקום \u0003נותנין עליו\u0004 \u0003חומרי המקום שיצא משם וחומרי המקום שהלך לשם?\u0004","\u0003אמר אביי: הני מילי\u0004 \u0005[דברים אלה אמורים]\u0006 \u0005באדם שהולך\u0006 \u0003מ\u0004מקום אחד ב\u0003בבל ל\u0004מקום אחר ב\u0003בבל, ו\u0004כן \u0003מארץ ישראל לארץ ישראל, אי נמי\u0004 \u0005[או גם כן]\u0006 במי שיורד \u0003מארץ ישראל לבבל. אבל\u0004 העולה \u0003מבבל לארץ ישראל, כיון דאנן כייפינן להו עבדינן כוותייהו\u0004 \u0005[שאנו\u0006 בבבל \u0005כפופים להם\u0006 לחכמי ארץ ישראל בענייני הלכה \u0005עושים אנו כמותם].\u0006","\u0003רב אשי אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שנותנים עליו חומרי המקום שיצא משם גם בהולך \u0003מבבל לארץ ישראל\u0004 — \u0003הני מילי היכא\u0004 \u0005[דברים אלה אמורים במקום]\u0006 ש\u0003דעתו לחזור\u0004 למקומו, שאז נותנים עליו שתי החומרות, ואילו \u0003ר' זירא\u0004 כשעלה לארץ \u0003אין דעתו לחזור הוה\u0004 \u0005[היה],\u0006 ולכן נהג כמנהג ארץ ישראל.","בהמשך למסופר, שנהגו בבבל איסור במוגרמת לשיטת רב ושמואל, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף\u0004 שישב בפומבדיתא: \u0003והא רבנן דאתו\u0004 \u0005[והרי חכמים שבאו]\u0006 לכאן \u0003מ\u0004העיר \u0003מחוזא אמרי\u0004 \u0005[אומרים],\u0006 \u0003אמר רבי זירא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב נחמן: מוגרמת כשרה! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003נהרא נהרא ופשטיה\u0004 \u0005[נהר נהר והילוכו],\u0006 כלומר, כל מקום הולך אחר מנהגו, ובמחוזא לא נהגו כרב ושמואל.","מסופר, \u0003רבי שמעון בן לקיש אכשר\u0004 \u0005[הכשיר]\u0006 בהמה שנשחטה \u0003בחודא דכובעא\u0004 \u0005[בחוד,\u0006 בקצה \u0005הכובע]\u0006 שנמצא מעבר לטבעת הגדולה, והוא קצה הקנה, \u0003קרי עליה\u0004 \u0005[קרא עליו]\u0006 \u0003רבי יוחנן\u0004 על ריש לקיש: \u0003גיסא גיסא\u0004 \u0005[הרבה, הרבה],\u0006 \u0005שהתיר יותר מדי — הגזים (גס = גדול). ועוד בענין מקום השחיטה\u0006 \u0003אמר רב פפי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא:\u0004 שחט ו\u0003פגע בחיטי\u0004 \u0005[בחיטים]\u0006 שתי בליטות כעין חיטים, היוצאות סמוך לטבעת העליונה לכיוון הלוע (ומכוסות בכובע) — הרי הוא \u0003טרפה.\u0004","וביחס לכך \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 לחכמים: האם הכוונה ש\u0003פגע ונגע בהן,\u0004 כלומר, שחתך מקצתן, וכמו \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויפגע בו וימת\"\u0004 (מלכים א ב, כה), \u0003או דלמא\u0004 \u0005[שמא]\u0006 כוונתו \u0003פגע ולא נגע,\u0004 אלא חתך ממש בסמוך להן בקצה הטבעת הגדולה, \u0003כדכתיב\u0004 \u0005[כמו שנאמר]:\u0006 \u0003\"ויפגעו בו מלאכי אלהים\"\u0004 (בראשית לב, א), שפגשו בו?","ובניגוד לדברי רב פפי בשם רבא, מביאים מה ש\u0003איתמר\u0004 \u0005[נאמר],\u0006 \u0003אמר רב פפא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא:\u0004 אם \u0003שייר בחיטי\u0004 \u0005[בחיטים]\u0006 ששחט באמצעו — \u0003כשרה. אמר רב אמימר בר מר ינוקא: הוה קאימנא קמיה\u0004 \u0005[הייתי עומד לפני]\u0006 \u0003ר' חייא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אויא, ואמר לי: שייר בחיטי\u0004 \u0005[בחיטים]\u0006 — \u0003כשרה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: אמר לי רב שמן מ\u0004המקום \u0003סוברא, איקלע\u0004 \u0005[הזדמן]\u0006 \u0003מר זוטרא לאתרין\u0004 \u0005[למקומנו]\u0006 \u0003ודרש: שייר בחיטי\u0004 \u0005[בחיטים]\u0006 — \u0003כשרה. מר בר רב אשי אמר:\u0004 אם \u0003פגע בחיטי\u0004 \u0005[בחיטים]\u0006 — \u0003כשרה,\u0004 אם \u0003שייר בחיטי\u0004 \u0005[בחיטים]\u0006 — \u0003טרפה.\u0004"],["ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005],\u0006 שחט \u0003משיפוי\u0004 (משיפוע) \u0003ה\u0004\u0003כובע ולמטה\u0004 לכיוון הקנה — \u0003כשרה, והיינו\u0004 \u0005[וזהו]\u0006 כדעת מי שאמר שאם \u0003שייר בחיטי\u0004 \u0005[בחיטים]\u0006 — כשרה, שהחיטים נמשכות מעבר לקו זה.","מסופר, \u0003רב נחמן אכשר\u0004 \u0005[הכשיר]\u0006 כששחט \u0003משיפוי\u0004 ה\u0003כובע ולמטה, אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חנן בר רב קטינא לרב נחמן: כמאן\u0004 \u0005[כמי]\u0006 אתה אומר זאת? \u0003לא כרבנן\u0004 \u0005[כדעת חכמים]\u0006 במשנתנו \u0003ולא כר' יוסי בר' יהודה,\u0004 שלדעת שניהם חוץ לטבעת העליונה של הקנה אינו מקום שחיטה!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אנא\u0004 \u0005[אני]\u0006 \u0003לא חילק ידענא\u0004 \u0005[יודע אני]\u0006 \u0003ולא בילק ידענא\u0004 \u0005[יודע אני],\u0006 כלומר, איני יודע טעמו של זה ולא של זה, \u0003אנא שמעתא ידענא\u0004 \u0005[אני דבר שמועה,\u0006 הלכה, \u0005יודע אני],\u0006 ש\u0003אמר ר' חייא בר אבא אמר ר' יוחנן, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003ר' אבא בר זבדא אמר ר' חנינא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003ר' יעקב בר אידי אמר ר' יהושע בן לוי:\u0004 שחט \u0003משיפוי\u0004 ה\u0003כובע ולמטה\u0004 — \u0003כשרה.\u0004","ושבים לברייתא ששנינו בעמוד הקודם: מוגרמת פסולה, ור' חנינא בן אנטיגנוס העיד על מוגרמת שהיא כשרה. \u0003ו\u0004ביחס בינה לבין משנתנו, \u0003אמר רבי יהושע בן לוי: מוגרמת דרבנן\u0004 \u0005[של שיטת חכמים]\u0006 במשנתנו, שאם שחט אפילו מיעוט חוץ לטבעת הגדולה פסולה — \u0003כשרה ל\u0004שיטת \u0003ר' יוסי בר' יהודה,\u0004 שהכשיר כששחט רוב בטבעת הגדולה, \u0003ו\u0004מוגרמת של","\u0003ר' יוסי בר' יהודה,\u0004 שאם שחט רוב מחוץ לטבעת פסולה — \u0003כשרה ל\u0004שיטת \u0003ר' חנינא בן אנטיגנוס,\u0004 שלדעתו ניתן לשחוט לגמרי מחוץ לקנה.","ותוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכן הוא! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003ר' חנינא בן אנטיגנוס\u0004 שאמר שמוגרמת כשרה — \u0003אדרבנן קאי\u0004 \u0005[על דברי חכמים הוא מתייחס],\u0006 שנאמרו בסתם בתחילת הברייתא, וגם הוא סבור כר' יוסי שאם שחט רוב מחוץ לטבעת — פסולה, על כן \u0003קא משמע\u0004 \u0003לן\u0004 \u0005[משמיע לנו]\u0006 שאין זה כך. ושואלים:","\u0003ואימא הכי נמי\u0004 \u0005[ואמור\u0006 ש\u0005כך הוא גם כן]!\u0006 ומשיבים: \u0003אם כן \"העיד עליה\" מיבעי ליה\u0004 \u0005[צריך היה לו לומר],\u0006 כלומר, על דעת חכמים שנזכרה שם תחילה, ומה שאמר בלשון כללית \"העיד על מוגרמת שהיא כשרה\", מלמד שהכוונה לכל הדעות שנאמרו בענין זה. ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 \u0003כר' חנינא בן אנטיגנוס, דקאי\u0004 \u0005[שעומד]\u0006 \u0003רב נחמן כוותיה\u0004 \u0005[כשיטתו],\u0006 שהכשיר משיפוי כובע ולמטה, והוא מעבר לטבעת הגדולה.","ושבים למחלוקת במשנתנו, שלדעת חכמים השוחט מתוך הטבעת (הגדולה) ולא שייר מלוא החוט על פני כולה, שחיטתו פסולה, ולדעת ר' יוסי בר' יהודה אם שייר על פני רובה — כשרה. \u0003אמר רב הונא אמר רב אסי: מחלוקת בששחט\u0004 תחילה \u0003שני שליש\u0004 בטבעת \u0003ו\u0004אחר כך \u0003הגרים\u0004 (יצא למעלה) לכיוון הראש \u0003שליש\u0004 אחד, \u0003דרבנן סברי\u0004 \u0005[שחכמים סבורים]:\u0006 \u0003כולה\u0004 \u0005[את כל]\u0006 ה\u0003שחיטה בעינן\u0004 \u0005[צריכים אנו]\u0006 שתהיה \u0003בטבעת\u0004 ה\u0003גדולה, ור' יוסי בר' יהודה סבר\u0004 \u0005[סבור]:\u0006 \u0003רובו ככולו.\u0004","\u0003אבל\u0004 אם \u0003הגרים שליש\u0004 תחילה, ששחט שליש ראשון מחוץ לטבעת, \u0003ו\u0004אחר כך \u0003שחט שני שליש\u0004 בטבעת — \u0003דברי הכל פסולה,\u0004 ומדוע? \u0003דכי נפקא חיותא בעינן רובא\u0004 \u0005[שכאשר יוצאת\u0006 ה\u0005חיות,\u0006 והוא בשעה שנחתך רובו של הקנה, \u0005צריכים אנו שיהיה אותו רוב]\u0006 נשחט \u0003בשחיטה\u0004 כשרה, \u0003וליכא\u0004 \u0005[ואין כאן],\u0006 שהרי חלקו נעשה בהגרמה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא: אדרבה\u0004 \u0005[גדולה מזו],\u0006 \u0003לימא מר איפכא\u0004 \u0005[שיאמר אדוני להיפך]:\u0006 \u0003מחלוקת\u0004 ר' יוסי וחכמים במשנה היא \u0003כשהגרים שליש\u0004 תחילה \u0003ו\u0004אחר כך \u0003שחט שני שליש,\u0004 ש\u0003ר' יוסי בר' יהודה סבר\u0004 \u0005[סבור]\u0006 שהוא כשר, מפני שבשעה שהחיות יוצאת, כשנשחט רובו של הקנה — היה זה בשחיטה כשרה, למרות שרוב הקנה לא נשחט בשחיטה כשרה, \u0003מידי\u0004 \u0003דהוה\u0004 \u0005[כמו שהוא\u0006 הדין\u0005]\u0006 כאשר יש \u0003חצי קנה פגום,\u0004 שאם הוסיף ושחט כל שהוא שחיטתו כשרה, הואיל ובשעה שנשחט רובו היה זה בשחיטה כשרה.","\u0003ו\u0004אילו \u0003רבנן\u0004 \u0005[וחכמים]\u0006 סבורים שאין הדברים דומים, שכן \u0003התם\u0004 \u0005[שם]\u0006 היה הפגם ב\u0003מקום שחיטה,\u0004 ונמצא שרוב חיותה של הבהמה יצאה במקום הראוי, ואילו \u0003הכא לאו\u0004 \u0005[כאן,\u0006 כשהגרים, \u0005אין\u0006 זה\u0005]\u0006 \u0003מקום שחיטה.\u0004","\u0003אבל\u0004 אם \u0003שחט\u0004 תחילה \u0003שני שליש ו\u0004אחר כך \u0003הגרים שליש\u0004 — \u0003דברי הכל כשרה, דהא תנן\u0004 \u0005[שהרי שנינו\u0006 במשנה\u0005]\u0006 להלן: \u0003רובו של\u0004 סימן \u0003אחד\u0004 (קנה או ושט) \u0003כמוהו,\u0004 שאם נשחט רובו כאילו נשחט כולו!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003רב יוסף: מאן נימא לן דההוא רובא דהתם\u0004 \u0005[מי יאמר לנו שאותו רוב ש\u0006שנינו \u0005שם]\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003ר' יוסי בר' יהודה קתני לה\u0004 \u0005[שונה אותה]?\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003רבי יוסי בר' יהודה קתני לה\u0004 \u0005[שונה אותה],\u0006 אבל חכמים אינם סבורים כן!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אטו כל רובי דעלמא\u0004 \u0005[וכי כל\u0006 המקומות ששנינו \u0005שהולכים אחר הרוב]\u0006 \u0003ר' יוסי בר' יהודה קתני להו\u0004 \u0005[\u0006הוא ש\u0005שונה אותם]?\u0006 ומדוע נייחס את הדברים דווקא לו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003אנא רובא\u0004 \u0005[אני\u0006 לענין \u0005רוב]\u0006 ב\u0003שחיטה קאמינא\u0004 \u0005[אמרתי],\u0006 \u0003דשמענא להו דפליגי\u0004 \u0005[ששמעתי אותם שהם חלוקים\u0006 בענין זה\u0005]\u0006 במשנה שלנו.","\u0003לישנא אחרינא אמרי לה\u0004 \u0005[בלשון אחרת אומרים אותה]\u0006 את כל השמועה הזו, באופן זה, \u0003אמר רב הונא אמר רב אסי:\u0004 ה\u0003מחלוקת\u0004 במשנתנו בענין המוגרמת הוא דווקא באופן \u0003שהגרים שליש\u0004 תחילה \u0003ו\u0004אחר כך \u0003שחט שני שליש,\u0004 ש\u0003רבי יוסי בר ר' יהודה סבר\u0004 \u0005[סבור]:\u0006 שחיטה כשרה היא, \u0003מידי דהוה\u0004 \u0005[כמו שהוא\u0006 הדין\u0005]\u0006 ב\u0003חצי קנה פגום,\u0004 שאם הוסיף ושחט כלשהו — שחיטתו כשרה. \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 סבורים: אין הדברים דומים, שכן \u0003התם\u0004 \u0005[שם]\u0006 הפגם שהיה בתחילה הוא ב\u0003מקום שחיטה,\u0004 אבל \u0003הכא לאו\u0004 \u0005[כאן,\u0006 כשהגרים, \u0005לא היה\u0006 זה\u0005]\u0006 ב\u0003מקום שחיטה.\u0004","\u0003אבל שחט\u0004 מתחילה \u0003שני שליש ו\u0004אחר כך \u0003הגרים שליש\u0004 — \u0003דברי הכל כשרה, דהא תנן\u0004 \u0005[שהרי שנינו\u0006 במשנה\u0005]\u0006 להלן: \u0003רובו של אחד כמוהו.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב חסדא: מאן לימא לן דההוא רובא דהתם\u0004 \u0005[מי יאמר לנו שאותו רוב ש\u0006שנינו \u0005שם]\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003ר' יוסי בר' יהודה קתני לה\u0004 \u0005[שונה אותה]?\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003ר' יוסי בר' יהודה קתני לה\u0004 \u0005[הוא\u0006 ש\u0005שונה אותה]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף: אטו כל רובי דעלמא\u0004 \u0005[וכי כל מקום\u0006 ששנינו \u0005שהולכים אחר הרוב]\u0006 \u0003ר' יוסי בר' יהודה קתני להו\u0004 \u0005[שונה אותם]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב חסדא: \u0003אנא רובא\u0004 \u0005[אני ברוב]\u0006 של \u0003שחיטה קאמינא\u0004 \u0005[אמרתי],\u0006 \u0003דשמענא להו דפליגי\u0004 \u0005[ששמעתי אותם שהם חלוקים\u0006 בזה\u0005]\u0006 במשנתנו.","ומביאים דיון במקרים דומים. אם \u0003הגרים\u0004 תחילה \u0003שליש\u0004 ואחר כך הוסיף \u0003ושחט שליש ו\u0004לבסוף \u0003הגרים שליש\u0004 — \u0003רב הונא אמר רב: כשרה, רב יהודה אמר רב: טרפה.\u0004 ומבארים: \u0003רב הונא אמר רב\u0004 שהיא \u0003כשרה,\u0004 שכן \u0003כי נפקא חיותא\u0004 \u0005[כאשר יוצאת החיות],\u0006 בשעה שנחתך רוב הקנה — \u0003בשחיטה\u0004 כשרה \u0003קא נפקא\u0004 \u0005[היא יוצאת].\u0006 \u0003רב יהודה אמר רב\u0004 שהיא \u0003טרפה,\u0004 ומדוע? \u0003בעינן רובא\u0004 \u0005[צריכים אנו שיהיה רובה]\u0006 \u0003בשחיטה\u0004 כשרה \u0003וליכא\u0004 \u0005[ואין כאן],\u0006 שהרי שני שליש הגרים ושליש שחט.","ובמקרה ש\u0003שחט\u0004 מתחילה \u0003שליש ו\u0004אחר כך \u0003הגרים שליש ו\u0004שוב \u0003שחט שליש\u0004 — \u0003רב יהודה אמר רב: כשרה. אתו שיילוה\u0004 \u0005[הלכו ושאלו]\u0006 את \u0003רב הונא\u0004 בענין זה, \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003טרפה. שמע רב יהודה\u0004 את דברי רב הונא ו\u0003איקפד\u0004 \u0005[הקפיד],\u0006 \u0003אמר: טריפנא ומכשר, ומכשרנא טריף\u0004 \u0005[\u0006כש\u0005אני מטריף והוא מכשיר, ו\u0006כש\u0005אני מכשיר הוא מטריף]!\u0006 \u0003אמר רב הונא: שפיר קא מיקפד\u0004 \u0005[יפה הוא מקפיד],\u0006 משתי סיבות: \u0003חדא\u0004 \u0005[אחת] —\u0006 \u0003איהו שמיע ליה מיניה\u0004 \u0005[הוא שמע\u0006 את הדברים \u0005הללו ממנו]\u0006 מ\u0003רב\u0004 ובשמו מסרם, \u0003ואנא לא שמיע לי\u0004 \u0005[ואני לא שמעתי]\u0006 הלכה זו מרב, ואמרתיה מדעתי. \u0003ועוד, האיכא רובא\u0004 \u0005[הרי יש כאן רוב]\u0006 \u0003בשחיטה\u0004 כשרה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא\u0004 לרב הונא: \u0003לא תהדר בך\u0004 \u0005[אל תחזור בך]\u0006 מדברים שאמרת,"],["ש\u0003אם כן\u0004 אתה חוזר בך \u0003מפסדת לה לקמייתא\u0004 \u0005[אתה מפסיד את\u0006 מה שאמרת \u0005בראשונה],\u0006 שאם הגרים שליש ושחט שליש והגרים שליש — כשרה. שכן \u0003התם מאי טעמא קא מכשרת\u0004 \u0005[שם מה טעם אתה מכשיר]?\u0006 מפני \u0003דכי נפקא חיותא\u0004 \u0005[שכאשר יוצאת החיות],\u0006 בשעה שנחתך רוב הקנה, והוא בשליש השני — \u0003בהכשירה קא נפקא\u0004 \u0005[בהכשר היא יוצאת].\u0006 ולפי זה, \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 כששחט שליש והגרים שליש ושחט שליש, \u0003כי נפקא חיותא\u0004 \u0005[כאשר יוצאת החיות]\u0006 — \u0003בהגרמה קא נפקא\u0004 \u0005[היא יוצאת],\u0006 ולכן היא טריפה.","מסופר, \u0003איקלע\u0004 \u0005[הזדמן]\u0006 \u0003רב נחמן לסורא, בעו מיניה\u0004 \u0005[שאלו אותו]\u0006 שם שאלה זו: \u0003שחט שליש והגרים שליש ושחט שליש, מהו? אמר להו\u0004 \u0005[להם]:\u0006 \u0003לאו היינו\u0004 \u0005[האם אין זו\u0006 הלכה\u0005]\u0006 של \u0003ר' אלעזר בר מניומי,\u0004 ש\u0003אמר ר' אלעזר בר מניומי: שחיטה העשויה כ\u0004שיניים של \u0003מסרק,\u0004 עולה ויורדת — \u0003כשרה?\u0004","ודחו את דבריו: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 אמר זאת כשעשה הכל \u0003במקום שחיטה,\u0004 וכאן מדובר כשהגרים, שיצא חוץ למקום השחיטה! השיב להם: אם \u0003במקום שחיטה\u0004 דיבר ר' אלעזר בר מניומי, \u0003מאי למימרא\u0004 \u0005[מה\u0006 בא \u0005לומר]?\u0006 פשוט הוא, הרי שחט במקום הראוי! ומשיבים, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 \u0003שחיטה\u0004 שתהיה \u0003מפורעת\u0004 (גלויה, ישרה) \u0003וליכא\u0004 \u0005[ואין כאן],\u0006 שהרי אינו שוחט בקו ישר, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאף שאינה מפורעת הריהי כשרה.","(\u0003סימן\u0004 לסדר החכמים: ר' א\u0003ב\u0004א, רב \u0003כ\u0004הנא, רב יהו\u0003ד\u0004ה)","עוד מסופר, \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רבי אבא אחוריה\u0004 \u0005[אחרי]\u0006 \u0003רב כהנא ויתיב\u0004 \u0005[וישב]\u0006 \u0003רב כהנא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב יהודה, ויתיב וקאמר\u0004 \u0005[ויושב היה ואומר,\u0006 שואל\u0005]\u0006 את רב יהודה: \u0003שחט שליש והגרים שליש ושחט שליש, מהו? אמר ליה\u0004 \u0005[לו]\u0006 רב יהודה: \u0003שחיטתו כשרה.\u0004","ועוד שאל רב כהנא: \u0003הגרים שליש ושחט שליש והגרים שליש, מהו? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שחיטתו פסולה.\u0004","עוד שאל רב כהנא: \u0003שחט במקום נקב,\u0004 שהיה נקב בחלקו הקדמי של הקנה, והוסיף ושחט \u0003מהו? אמר ליה\u0004 \u0005[לו]\u0006 רב יהודה: \u0003שחיטתו כשרה.\u0004","הוסיף ושאל: \u0003שחט ופגע בו נקב,\u0004 שלאחר ששחט חצי הקנה פגע בנקב, וכך נשלמה השחיטה של הקנה, \u0003מהו? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שחיטתו פסולה.\u0004","לאחר ששמע דברים אלה \u0003אזל\u0004 \u0005[הלך]\u0006 \u0003רבי אבא\u0004 לארץ ישראל ו\u0003אמרה קמיה\u0004 \u0005[אמר\u0006 שמועה זו \u0005לפני]\u0006 \u0003ר' אלעזר, אזל\u0004 \u0005[הלך]\u0006 \u0003ר' אלעזר אמרה קמיה\u0004 \u0005[אמר אותה לפני]\u0006 \u0003ר' יוחנן,\u0004 ו\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003מאי שנא\u0004 \u0005[במה שונה]\u0006 הדבר, אם שחט במקום נקב או שחט ופגע בו נקב?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 אם \u0003שחט במקום נקב, נעשה כמי ששחט\u0004 תחילה \u0003גוי\u0004 חצי קנה \u0003וגמר ישראל\u0004 את שחיטת חציו האחר ששחיטה זו כשרה. ואולם אם \u0003שחט ופגע בו נקב, נעשה כמי ששחט ישראל\u0004 חצי קנה \u0003וגמר גוי,\u0004 ששחיטה זו פסולה. \u0003קרי עליה\u0004 \u0005[קרא עליו]\u0006 ר' יוחנן בלגלוג: \u0003\"גוי גוי\",\u0004 כלומר, סתם חוזר אתה ומזכיר אתה גוי, ולא קיבל את דבריו.","\u0003אמר רבא: שפיר קרי עליה\u0004 \u0005[יפה קרא עליו]\u0006 \u0003\"גוי גוי\",\u0004 שכן \u0003בשלמא התם מדהוה ליה\u0004 \u0005[נניח שם מכיון שהיה לו]\u0006 \u0003לישראל למשחט רובא\u0004 \u0005[לשחוט את הרוב]\u0006 \u0003ולא שחט, כי נפקא חיותא\u0004 \u0005[כאשר יצאה החיות]\u0006 בשעה שנחתך רוב הקנה — \u0003בידא\u0004 \u0005[ביד]\u0006 של \u0003גוי קא נפקא\u0004 \u0005[יצאה].\u0006 \u0003אלא הכא\u0004 \u0005[כאן],\u0006 כששחט ופגע בנקב, \u0003מכדי משחט שחיט\u0004 \u0005[הואיל ושחט]\u0006 את כל שהיה בידו לשחוט, ולא היתה טריפה קודם לכן — \u0003מה לי\u0004 ששחט \u0003במקום נקב, מה לי פגע בו נקב?\u0004","\u0003השוחט מן הצדדין\u0004 של הצוואר — \u0003שחיטתו כשרה, המולק\u0004 עוף קדשים \u0003מן הצדדין\u0004 — \u0003מליקתו פסולה. השוחט מן העורף\u0004 — \u0003שחיטתו פסולה, המולק מן העורף\u0004 — \u0003מליקתו כשירה. השוחט מן הצואר\u0004 — \u0003שחיטתו כשרה, המולק מן הצואר\u0004 — \u0003מליקתו פסולה. שכל העורף כשר למליקה, וכל הצואר כשר לשחיטה. נמצא,\u0004 מה ש\u0003כשר בשחיטה פסול במליקה,\u0004 מה ש\u0003כשר במליקה פסול בשחיטה.\u0004","שנינו במשנה: השוחט מן העורף שחיטתו פסולה. ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003עורף? אילימא\u0004 \u0005[אם תאמר]\u0006 ששוחט ב\u0003עורף ממש,\u0004 בחלקה האחורי של הגולגולת, \u0003מאי אריא\u0004 \u0005[מה שייך]\u0006 דווקא ש\u0003שוחט\u0004 שם? \u0003אפילו מולק נמי\u0004 \u0005[גם כן]\u0006 יהיה פסול שם, שהרי \"ומלק את ראשו \u0003ממול ערפו\"\u0004 (ויקרא ה, ח) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 כלומר, הצד האחורי של הצוואר, למטה משם, \u0003ולא ערפו\u0004 ממש! \u0003אלא מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003עורף\u0004 שבמשנה? כוונתו \u0003ממול עורף,\u0004 הצד האחורי של הצוואר, משם רואים את העורף, \u0003כדקתני סיפא\u0004 \u0005[כמו שהוא שונה בסוף\u0006 המשנה\u0005]:\u0006 \u0003כל העורף כשר למליקה,\u0004 ואם בעורף עצמו מדובר אין לדבר על \"כל העורף\", מפני שהוא קטן מאד.","ומבררים: \u0003מנהני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 \u0003\"ממול ערפו\"\u0004 — \u0003מול\u0004 הוא \u0003הרואה את העורף\u0004 ולא העורף עצמו, \u0003וכן הוא אומר: \"והוא יושב ממולי\"\u0004 (במדבר כב, ה), \u0003ואומר: \"כי פנו אלי עורף ולא פנים\"\u0004 (ירמיהו ב, כז). ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 ראייה מוסיף על ידי \u0003ואומר\u0004 \"כי פנו אלי עורף ולא פנים\"? ומשיבים, \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003עורף גופיה\u0004 \u0005[עצמו]\u0006 \u0003לא ידעינן היכא, דנדע מול דידיה היכא\u0004 \u0005[אין אנו יודעים היכן\u0006 הוא, \u0005כדי שנדע מול שלו היכן הוא],\u0006 לכך \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]:\u0006 \u0003\"כי פנו אלי עורף ולא פנים\", מכלל\u0004 הדברים אתה למד ש\u0003עורף\u0004 הוא \u0003להדי\u0004 \u0005[כנגד]\u0006 ה\u0003פנים,\u0004 בצד האחורי.","\u0003אמרי\u0004 \u0005[אמרו]\u0006 \u0003בני ר' חייא: מצות מליקה\u0004 של קרבן מן העוף, איך היא נעשית? \u0003מחזיר סימנים\u0004 הקנה והוושט \u0003לאחורי העורף ומולק.\u0004 ונחלקו חכמים בפירוש המדוייק של דבריהם. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003אף\u0004 אם \u0003מחזיר\u0004 הרי זה כשר, ולכתחילה המצוה היא לחתוך את השדרה תחילה ומשם להמשיך ולחתוך את הקנה והוושט. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003מחזיר דוקא.\u0004","ומעירים: \u0003ומסתברא כמאן דאמר\u0004 \u0005[ומסתבר כ\u0006דעת \u0005מי שאומר]:\u0006 \u0003אף מחזיר, ממאי\u0004 \u0005[ממה]?\u0006 \u0003מדקתני\u0004 \u0005[ממה ש\u0006התנא \u0005שונה]:\u0006 \u0003השוחט מן העורף\u0004 — \u0003שחיטתו פסולה, המולק מן העורף\u0004 — \u0003מליקתו כשרה;\u0004"],["\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 ש\u0003מחזיר דוקא\u0004 כשר במליקה, ובכך עוסקת המשנה, \u0003מאי איריא\u0004 \u0005[מה שייך],\u0006 מדוע רק \u0003מולק\u0004 מן העורף כשר? \u0003אפילו שוחט\u0004 מן העורף \u0003נמי\u0004 \u0005[גם כן]\u0006 יהיה כשר, אם החזיר את הסימנים לאחור ושחטם! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 שמה שאמרו בני ר' חייא שמצות מליקה היא במחזיר סימנים לאחור ומולק, כוונתם — \u0003אף מחזיר,\u0004 והוא הדין אם אינו מחזיר, \u0003ו\u0004לפי זה \u0003מתניתין\u0004 \u0005[משנתנו],\u0006 שפוסלת בשוחט מן מהעורף, יש לפרשה \u0003בדלא אהדר\u0004 \u0005[בשלא החזיר]\u0006 את הסימנים לאחור.","ולעיקר דבריהם של בני ר' חייא \u0003אמר ר' ינאי: יקבלו הרובין\u0004 (הצעירים) \u0003את תשובתן\u0004 דחיה לדבריהם, ממה \u0003דקתני\u0004 \u0005[ש\u0006התנא \u0005שונה]\u0006 בסוף משנתנו: \u0003נמצא כשר בשחיטה\u0004 — \u0003פסול במליקה, כשר במליקה\u0004 — \u0003פסול בשחיטה.\u0004 ונברר, \u0003למעוטי מאי\u0004 \u0005[למעט את מה]\u0006 הוא בא? \u0003לאו למעוטי\u0004 \u0005[האם לא\u0006 כדי \u0005למעט]\u0006 \u0003מחזיר סימנין לאחורי העורף,\u0004 ש","\u0003לא\u0004 כשר במליקה אלא רק בשחיטה? \u0003אמר רבה בר בר חנה: לא,\u0004 אפשר לומר שעיקרו בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003שן וצפורן\u0004 שאינם תלושים, שהם כשרים במליקה דווקא, ופסולים בשחיטה. ותוהים: \u0003שן וצפורן בהדיא\u0004 הלא \u0003קתני להו\u0004 \u0005[במפורש שנה אותם]\u0006 במשנה לעיל (טו,ב) שהם פסולים בשחיטה, ולא הוצרך לחזור ולשנות דבר זה!","\u0003אלא אמר ר' ירמיה:\u0004 מה ששנינו שהכשר בשחיטה פסול במליקה, בא \u0003למעוטי\u0004 \u0005[למעט]\u0006 \u0003מוליך ומביא,\u0004 שאין המולק רשאי לחתוך את הסימנים בהולכה והבאה של צפורנו, כפי ששוחטים בסכין, אלא צריך ללחוץ ולחתוך אותם בבת אחת. ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח לשיטת מי שאומר]\u0006 \u0003מוליך ומביא במליקה\u0004 — \u0003פסול, אלא למאן דאמר\u0004 \u0005[ל\u0006דעת מי \u0005שאומר]\u0006 שהוא \u0003כשר, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומשיבים: \u0003בני ר' חייא סברי לה כמאן דאמר\u0004 \u0005[סבורים כ\u0006דעת \u0005האומר]\u0006 \u0003מוליך ומביא במליקה\u0004 — \u0003פסול.\u0004","בענין זה מביאים מה ש\u0003אמר רב כהנא: מצות מליקה קוצץ,\u0004 לוחץ בציפורנו מצד העורף, \u0003ויורד, וזו היא מצותה. סבר\u0004 \u0005[סבור\u0006 היה\u0005]\u0006 \u0003רבי אבין למימר\u0004 \u0005[לומר],\u0006 דברים אלה משמעם: \u0003קוצץ ויורד\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003מוליך ומביא\u0004 — \u0003לא. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה: כל שכן\u0004 ש\u0003מוליך ומביא במליקה כשר. ומאי\u0004 \u0005[ומה]\u0006 פירוש \u0003\"זו היא מצותה\",\u0004 שלכאורה משמעו דווקא זו ולא אחרת? \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003אף זו היא מצותה.\u0004","\u0003אמר ר' ירמיה אמר שמואל: כל\u0004 מקום בצואר \u0003הכשר בשחיטה\u0004 — \u0003כנגדו בעורף כשר במליקה\u0004 של קרבן מן העוף. ומעירים, מכאן נדייק: \u0003הא\u0004 \u0005[הרי]\u0006 כל מקום ש\u0003פסול בשחיטה\u0004 — כנגדו בעורף \u0003פסול במליקה.\u0004 ומבררים: \u0003למעוטי מאי\u0004 \u0005[למעט את מה]\u0006 הוא בא? \u0003אילימא למעוטי\u0004 \u0005[אם תאמר למעט]\u0006 \u0003עיקור סימנין,\u0004 שכשם שאם עקר את הקנה והוושט ממקומם ושחטם הוא פסול, מפני שאין זה מקום שחיטה, הוא הדין למליקה, \u0003והא תני\u0004 \u0005[והרי שנה]\u0006 \u0003רמי בר יחזקאל: אין\u0004 פסול של \u0003עיקור סימנין בעוף\u0004 כלל!","\u0003אמר רב פפא: למעוטי\u0004 \u0005[למעט]\u0006 מליקה באחורי \u0003ראשו\u0004 של העוף, כפי ששחיטה אינה כשרה בראש, אלא בצוואר. ותוהים: ב\u0003ראשו, פשיטא\u0004 \u0005[פשוט]\u0006 שלא ניתן למלוק, הרי \u0003\"ממול ערפו\"\u0004 (ויקרא ה, ח) \u0003אמר רחמנא\u0004 \u0005[אמרה התורה],\u0006 כלומר, במקום הרואה את העורף, באחורי הצוואר, \u0003ולא בראשו,\u0004 בעורף עצמו!","ומסבירים: \u0003מאי\u0004 \u0005[מה פירוש]\u0006 \u0003ראשו\u0004 שבא למעט במליקה — \u0003שיפוי\u0004 (שיפוע) \u0003ראשו, כגון דנקט\u0004 \u0005[שנטל\u0006 התחיל\u0005]\u0006 למלוק \u0003משיפוי ראשו, והגרים ואזל עד דמטא תתאי\u0004 \u0005[ומלק חוץ למקום והלך עד שהגיע למטה],\u0006 למקום הסימנים, ושם השלים את המליקה. שהואיל והתחיל את המליקה מחוץ למקומה הרי זה פסול כמו בשחיטה, \u0003וכ\u0004דברי \u0003רב הונא אמר רב אסי,\u0004 ש\u0003אמר רב הונא אמר רב אסי: הגרים\u0004 שחט מחוץ למקום השחיטה \u0003שליש ו\u0004אחר כך \u0003שחט שני שליש\u0004 במקום השחיטה — \u0003פסולה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: הא דתני\u0004 \u0005[זו ששנה]\u0006 \u0003רמי בר יחזקאל\u0004 ש\u0003אין\u0004 פסול \u0003עיקור סימנין בעוף, לא אמרן\u0004 \u0005[לא אמרנו]\u0006 דברים אלה \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 ש\u0003אין\u0004 מצוות \u0003שחיטה לעוף מן התורה\u0004 כלל,"],["\u0003אבל למאן דאמר\u0004 \u0005[לדעת מי שאומר]\u0006 ש\u0003יש שחיטה לעוף מן התורה,\u0004 אם כן, \u0003יש\u0004 גם פסול של \u0003עיקור\u0004 סימנים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003אדרבה\u0004 \u0005[גדולה מזו],\u0006 \u0003איפכא מסתברא\u0004 \u0005[ההיפך הוא המסתבר]!\u0006 \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003יש שחיטה לעוף מן התורה,\u0004 הרי פרטי דיניה של שחיטה אינם מפורשים, ונמסרו למשה על פה, ולכן \u0003איכא למימר דהכי אגמריה\u0004 \u0005[יש לומר שכך לימד אותו]\u0006 הקדוש ברוך הוא את משה, שבעוף \u0003אין\u0004 פסול \u0003עיקור. ואפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שדינו \u0003כבהמה,\u0004 שהלכות שחיטת העוף נלמדו מהלכות שחיטת בהמה, ובבהמה העיקור פוסל — לימד אותו הקדוש ברוך הוא ש\u0003לענין עיקור לא ליהוי\u0004 \u0005[שלא יהיה]\u0006 \u0003כבהמה.\u0004","\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005האומר]\u0006 ש\u0003אין שחיטה לעוף מן התורה אלא מדברי סופרים, מהיכא גמירי לה\u0004 \u0005[מהיכן למדו אותה]\u0006 חכמים את הלכות השחיטה בעוף? \u0003מבהמה,\u0004 ואם כן \u0003כולה מילתא\u0004 \u0005[כל הדבר],\u0006 לכל ענין יהיה דין העוף \u0003כבהמה!\u0004","\u0003אמר רבינא, אמר לי רבין בר קיסי: הא דתני\u0004 \u0005[זו ששנה]\u0006 \u0003רמי בר יחזקאל: אין\u0004 פסול \u0003עיקור סימנין בעוף\u0004 — \u0003לא אמרן\u0004 \u0005[לא אמרנו]\u0006 דבר זה \u0003אלא במליקה, אבל בשחיטה יש\u0004 פסול \u0003עיקור.\u0004 ומקשים: \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003ירמיה אמר שמואל: כל הכשר בשחיטה, כנגדו בעורף כשר במליקה,\u0004 ומכאן מדייקים: \u0003הא\u0004 \u0005[הרי]\u0006 מה ש\u0003פסול\u0004 בשחיטה — \u0003פסול\u0004 גם במליקה! ואומרים: אכן, \u0003ההוא פליגא\u0004 \u0005[אותה\u0006 הלכה \u0005חולקת]\u0006 על דין זה.","\u0003אמר זעירי:\u0004 אם \u0003נשברה\u0004 ה\u0003מפרקת\u0004 של בהמה או עוף \u0003ורוב\u0004 ה\u0003בשר\u0004 ש\u0003עמה\u0004 נחתך — הרי זו \u0003נבלה,\u0004 שבכך היא נחשבת כמתה לגמרי, וגם אם שחטה — לא תועיל שחיטתה להוציאה מדין נבילה, שמטמאה במגע ובמשא.","\u0003אמר רב חסדא, אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 לדבר זה במשנה במסכת זבחים: \u0003מלק\u0004 עוף קדשים \u0003בסכין\u0004 (ולא בציפורן) — הרי זה העוף \u0003מטמא בגדים\u0004 של האוכל ממנו בשעה שהוא נמצא ב\u0003בית הבליעה\u0004 שלו, כדין נבלת עוף טהור. \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 שאם נשברה המפרקת ורוב הבשר שעמה אינה נחשבת כנבילה, אלא \u0003טרפה הויא\u0004 \u0005[היא]\u0006 נחשבת, כעומדת למות, ולא כמתה ממש. אם כן הואיל ו\u0003מליקתה\u0004 של קרבן מן העוף \u0003זו היא שחיטתה\u0004 — \u0003תהני לה\u0004 \u0005[תועיל לה]\u0006 ה\u0003סכין לטהרה מידי\u0004 טומאת \u0003נבלה,\u0004 כדין כל טריפה שנשחטה בסכין, שאף שאינה כשרה לאכילה אינה מטמאה! אלא מכאן שבשעה שנשברה המפרקת ורוב הבשר שעמה על ידי הסכין, נעשתה נבילה.","בתשובה לכך \u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 הטעם שמליקה בסכין אינה מועילה לטהר, אינו משום שהיא עושה נבילה, אלא \u0003משום דלאו\u0004 \u0005[שלא]\u0006 \u0003שחיטה היא כלל,\u0004 שאינה נחשבת שחיטה כשרה, המועילה לטהר טריפה מטומאת נבילה. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003רב הונא אמר: מפני שהוא מחליד,\u0004 מכניס את הסכין מתחת לסימנים, ורק אז שוחט, וחלדה היא אחד הדברים הפוסלים את השחיטה. \u0003רבא אמר: מפני שהוא דורס\u0004 בסכין את הסימנים, ואינו מוליך ומביא.","ושואלים: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003מפני שהוא מחליד, מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר מפני שהוא דורס?\u0004 ומשיבים: \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003מוליך ומביא במליקה\u0004 — \u0003כשר,\u0004 ואם כן יש אפשרות למלוק בסכין באופן שהוא כשר בשחיטה. ושואלים: \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003מפני שהוא דורס, מאי טעמא לא אמר\u0004 \u0005[מה טעם אינו אומר]\u0006 \u0003מפני שהוא מחליד?\u0004 ומשיבים: \u0003אמר\u0004 \u0005[יכול היה לומר]\u0006 \u0003לך:\u0004 פסול \u0003חלדה היכי דמי\u0004 \u0005[כיצד הוא בדיוק]?\u0006 \u0003כחולדה הדרה בעיקרי בתים\u0004 בחורים שבקרקע, \u0003דמכסיא\u0004 \u0005[ש\u0006הסכין \u0005מכוסה]\u0006 בשעת השחיטה, שתוחב את הסכין בין השדרה והסימנים, ואז חותך. ואילו \u0003הכא הא מיגליא\u0004 \u0005[כאן,\u0006 כשמתחיל את החיתוך מן העורף, הסכין \u0005הרי היא גלויה],\u0006 שעובייה של הסכין נראה מאחור.","\u0003אמר רבא: אי קשיא לי\u0004 \u0005[אם קשה לי]\u0006 במה שאמר זעירי, שאם נשברה המפרקת ורוב בשר עמה הרי זו נחשבת כמתה — \u0003הא קשיא לי\u0004 \u0005[זה קשה לי]:\u0006 והרי כל מליקת עוף קדשים נעשית בדרך זו, שחותך תחילה את המפרקת ורוב בשר עמה, ורק אחר כך חותך את הסימנים; \u0003וכי\u0004 עוף \u0003מתה\u0004 הוא \u0003עומד ומולק?\u0004 שאם היא מתה מה תועיל המליקה?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 גם בלא להקשות על דינו של זעירי, \u0003ותקשי\u0004 \u0005[ותקשה]\u0006 \u0003לך\u0004 מדין \u0003עולת העוף, דבעיא\u0004 \u0005[שצריכה]\u0006 במליקתה חיתוך של \u0003שני\u0004 ה\u0003סימנין:\u0004 והרי די לעוף בחיתוך סימן אחד כדי להכשירו (כפי שהוא בשחיטת עוף חולין (להלן כז,א) ובמליקה של חטאת העוף), ואם כן מאותה שעה כמתה היא נחשבת, \u0003וכי מתה\u0004 הוא \u0003עומד ומולק? אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003התם\u0004 \u0005[שם]\u0006 נעשה הדבר רק \u0003כדי לקיים בה מצות הבדלה,\u0004 שצריך להבדיל בעולת העוף בין הראש לגוף.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 את ה\u0003עור נמי\u0004 \u0005[גם כן]\u0006 יצטרך לחתוך כדי לקיים מצות הבדלה, ואין מי שסבור כן! השיב לו אביי: \u0003כל המעכב בשחיטה מעכב בהבדלה, וכל שאינו מעכב בשחיטה אינו מעכב בהבדלה,\u0004 וחיתוך העור אינו מעכב בשחיטה.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 יש \u0003מיעוט סימנין\u0004 בעולת העוף \u0003ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003דלא מעכבי\u0004 \u0005[שאינם מעכבים]\u0006 \u0003בשחיטה,\u0004 שאם שחט את רוב הסימנים ומיעוטם מחובר עדיין — שחיטה כשרה היא, \u0003ומעכבי\u0004 \u0005[ו\u0006הם \u0005מעכבים]\u0006 לשיטתם \u0003ב\u0004ענין \u0003הבדלה!\u0004 ומתרצים, \u0003אלא אימא\u0004 \u0005[אמור]\u0006 כך: \u0003כל שישנו בשחיטה ישנו בהבדלה, וכל שאינו בשחיטה אינו בהבדלה,\u0004 ושני הסימנים, למרות שאינם מעכבים בשחיטה, מכל מקום הם חלק ממצות השחיטה, אבל העור אינו חלק ממצות השחיטה."],["ואומרים: \u0003מכל מקום קשיא\u0004 \u0005[קשה]\u0006 על דברי זעירי: אם כשנשברה המפרקת ורוב בשר עמה הריהי נחשבת כמתה, וכי עוף מת הוא מולק? \u0003אמר רבא, אימא\u0004 \u0005[אמור]\u0006 כך: \u0003וכן הוא עושה\u0004 במליקה, \u0003חותך\u0004 חוט ה\u0003שדרה ומפרקת\u0004 (עמוד השדרה שבצואר) \u0003בלא רוב בשר\u0004 ואז מולק את הסימנים.","וכן מסופר, \u0003כי סליק\u0004 \u0005[כאשר עלה]\u0006 \u0003רבי זירא\u0004 מבבל לארץ ישראל, \u0003אשכחיה\u0004 \u0005[מצא אותו]\u0006 את \u0003ר' אמי דיתיב וקאמר לה להא שמעתא\u0004 \u0005[שיושב ואומר את ההלכה הזו]\u0006 שאמר זעירי, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003וכי מתה עומד ומולק? אשתומם כשעה חדא\u0004 \u0005[תהה כשעה אחת]\u0006 וחשב בדבר, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אימא\u0004 \u0005[אמור],\u0006 \u0003כך הוא עושה, חותך שדרה ומפרקת בלא רוב בשר.\u0004","ומעירים, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003כיצד מולקין חטאת העוף? חותך שדרה ומפרקת בלא רוב בשר עד שמגיע לוושט או לקנה; הגיע לוושט או לקנה, חותך סימן אחד או רובו ורוב בשר עמו, ובעולה\u0004 מן העוף חותך \u0003שנים,\u0004 שני סימנים, הקנה והוושט, \u0003או רוב שנים.\u0004","ומבררים: \u0003מני\u0004 \u0005[כשיטת מי היא]\u0006 ברייתא זו שבעולה חותך שנים או רוב שנים? \u0003אי רבנן\u0004 \u0005[אם\u0006 כדעת \u0005חכמים]\u0006 — \u0003הא אמרי\u0004 \u0005[הרי אומרים הם]:\u0006 \u0003שנים דוקא! אי\u0004 \u0005[אם]\u0006 \u0003כ\u0004דעת \u0003ר' אלעזר בר' שמעון\u0004 — \u0003האמר\u0004 \u0005[הרי אמר]:\u0006 \u0003רוב שנים!\u0004","ומשיבים: \u0003אימא\u0004 \u0005[אמור]\u0006 כך: \u0003שנים ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003רוב שנים לרבי אלעזר בר' שמעון. ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003הא והא\u0004 \u0005[זו וזו]\u0006 כדעת \u0003ר' אלעזר בר' שמעון,\u0004 שאמר: רוב שנים, \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש\u0005]\u0006 \u0003שנים?\u0004 אין כוונתו לשנים שלמים, אלא \u0003שדומין לשנים.\u0004","\u0003אמר רב יהודה אמר שמואל: נשברה מפרקת\u0004 של אדם \u0003ו\u0004נחתך \u0003רוב בשר עמה\u0004 — אותו אדם \u0003מטמא באהל,\u0004 כלומר, נחשב כמת, למרות שהוא עדיין מפרכס.","\u0003ואם תאמר: אותו מעשה\u0004 של \u0003עלי\u0004 הכהן שנאמר בו: \"ותשבר מפרקתו וימת\" (שמואל א ד, יח), והרי שם \u0003מפרקת בלא רוב בשר הואי\u0004 \u0005[היתה],\u0006 שלא נחתך הבשר, ובכל זאת מת מיד! על כך יש לה להשיב: \u0003זקנה שאני\u0004 \u0005[שונה],\u0006 שהיה עלי איש זקן והוא שגרם למותו מיד, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויהי כהזכירו את ארון האלהים ויפול מעל הכסא אחורנית בעד יד השער ותשבר מפרקתו וימת כי זקן האיש וכבד\" וגו'\u0004 (שמואל א ד, יח).","באותם עניינים \u0003אמר ר' שמואל בר נחמני אמר ר' יוחנן:\u0004 אם \u0003קרעו\u0004 (חתכו) אדם \u0003כ\u0004דרך שחותכים \u0003דג\u0004 לאורכו — \u0003מטמא באהל,\u0004 משום שהוא נחשב כמת, למרות שהוא עדיין מפרכס. \u0003אמר רב שמואל בר יצחק: ו\u0004הכוונה היא שקרעו \u0003מגבו.\u0004 ושבים לדון בדיני בהמה.","\u0003אמר שמואל: עשאה גיסטרא,\u0004 שחצה אותה לרוחבה לשתים — \u0003נבלה,\u0004 למרות שהיא עדיין מפרכסת. \u0003אמר ר' אלעזר:\u0004 אם \u0003ניטל הירך\u0004 (הרגל האחורית של הבהמה), \u0003וחלל שלה ניכר\u0004 — הרי זו \u0003נבלה,\u0004 ומטמאה אפילו בעודה חיה. ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 ש\u0003חלל שלה ניכר? אמר רבא: כל ש\u0004הבהמה \u0003רבוצה ונראית חסרה\u0004 באותו מקום.","ועוד בעניינים אלו \u0003תנן התם\u0004 \u0005[שנינו שם]:\u0006 \u0003הותזו ראשיהן\u0004 של בעלי חיים, \u0003אף על פי שמפרכסין\u0004 עדיין — \u0003טמאים,\u0004 והם נחשבים \u0003כזנב הלטאה שמפרכסת,\u0004 שבאמת אין בו חיים.","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003הותזו\u0004 ראשיהן? \u0003ריש לקיש אמר: הותזו ממש,\u0004 שנחתכו. ר' אסי אמר רבי מני: כהבדלת עולת העוף.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה לרבי אסי:\u0004 האם כוונתך \u0003כהבדלת עולת העוף ל\u0004דעת \u0003רבנן\u0004 \u0005[חכמים],\u0006 שמלבד המפרקת ורוב בשר גם חותך את הסימנים לגמרי, \u0003ולא פלגיתו\u0004 \u0005[ו\u0006אם כן \u0005אין אתם,\u0006 אתה וריש לקיש, \u0005חלוקים],\u0006 שהרי זה ממש כהתזת הראש כולו, שלא נותר אלא העור. \u0003או דלמא\u0004 \u0005[שמא]\u0006 כוונתך \u0003כהבדלת עולת העוף לר' אלעזר בר' שמעון,\u0004 שאומר שהיא רוב שני סימנים, \u0003ופלגיתו\u0004 \u0005[ו\u0006אם כן \u0005חלוקים אתם],\u0006 ולדעת ריש לקיש מדובר בהתזה ממש?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אסי: \u0003כהבדלת עולת העוף לר' אלעזר בר' שמעון, ופליגינן\u0004 \u0005[וחלוקים אנו].\u0006","ומעירים: \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שבלשון זו עצמה נאמרה המחלוקת: מאי \"הותזו\"? \u0003ר' שמעון בן לקיש אמר: הותזו ממש, ר' אסי אמר ר' מני: כהבדלת עולת העוף לרבי אלעזר בר' שמעון ברוב שנים.\u0004","ואומרים: \u0003מאי רבנן ומאי\u0004 \u0005[מהי\u0006 דעת \u0005חכמים ומהי\u0006 דעת\u0005]\u0006 \u0003רבי אלעזר בר' שמעון\u0004 שהזכרנו בסוגיה זו? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 בענין קרבן \"עולה ויורד\" (שהעני שאין ביכולתו להביא חטאת בהמה מביא שני תורים או שני בני יונה, אחד לחטאת ואחד לעולה): \u0003\"ואת השני יעשה עולה כמשפט\"\u0004 (ויקרא ה, י), כוונתו — \u0003כמשפט חטאת בהמה,\u0004 שתחתיה הוא מביא קרבן זה.","ויש לשאול: \u0003אתה אומר כמשפט חטאת בהמה, או אינו אלא כמשפט חטאת העוף,\u0004 שהוזכרה עשייתה קודם לכן? על כך יש להשיב: \u0003כשהוא אומר\u0004 בפרשת עולת עוף של נדבה \u0003\"והקריבו\"\u0004 (שם א, טו), ומשמעו, והקריב אותו באופן המיוחד לו — בכך \u0003חלק הכתוב בין חטאת העוף לעולת העוף, ו\u0004אם כן \u0003מה אני מקיים \"כמשפט\"\u0004 — \u0003כמשפט חטאת בהמה.\u0004 ומהי משפטה? לאיזה ענין נאמר (שהרי הקרבת קרבן מן העוף בוודאי שונה משל בהמה)? \u0003מה חטאת בהמה אינה באה\u0004"],["\u0003אלא מן החולין\u0004 ולא ממעות מעשר שני, \u0003ו\u0004אין מקריבים אותה אלא \u0003ביום, ו\u0004עבודתה נעשית \u0003בידו הימנית\u0004 — \u0003אף עולת העוף אינה באה אלא מן החולין, וביום, ובידו הימנית.\u0004","ויש לשאול: \u0003אי\u0004 (אם כן) נאמר גם: \u0003מה להלן,\u0004 בחטאת בהמה, השחיטה כשרה \u0003ברוב שנים,\u0004 רוב שני סימנים, הקנה והוושט — \u0003אף כאן\u0004 בעולת העוף, הריהי כשרה \u0003ב\u0004מליקת \u0003רוב שנים! תלמוד לומר\u0004 בעולת העוף הבאה בנדבה: \u0003\"ומלק\u0004 את ראשו \u0003והקטיר\"\u0004 (ויקרא א, טז), \u0003מה הקטרה\u0004 — \u0003הראש בעצמו והגוף בעצמו, אף מליקה\u0004 — \u0003הראש בעצמו והגוף בעצמו.\u0004","ואילו \u0003רבי ישמעאל אומר:\u0004 \u0003\"כמשפט\"\u0004 שנאמר בעולת העוף של קרבן עולה ויורד (ויקרא ה, י), כוונתו — \u0003כמשפט חטאת העוף\u0004 שהזכיר הכתוב בפסוק הקודם, \u0003מה חטאת העוף\u0004 מולקה \u0003ממול עורף,\u0004 אחורי הצואר, ולא בעורף ממש, מאחורי הפנים, שנאמר: \"ומלק את ראשו ממול ערפו\" (שם ט) — \u0003אף עולת העוף\u0004 מולקה \u0003ממול עורף.\u0004","ויש לשאול: \u0003אי\u0004 (אם כן) נאמר גם: \u0003מה להלן,\u0004 בחטאת העוף, \u0003מולק ואינו מבדיל בסימן אחד,\u0004 שמשאיר סימן אחד שלם — \u0003אף כאן\u0004 בעולת העוף \u0003מולק ואינו מבדיל בסימן אחד! תלמוד לומר\u0004 בעולת העוף: \u0003\"והקריבו\"\u0004 (שם א, טו), ולא \"והקריב\", לומר שחלוקה הקרבתו מהקרבת החטאת.","\u0003רבי אלעזר ברבי שמעון אומר\u0004 גם כן: \u0003\"כמשפט\"\u0004 האמור בעולת העוף של קרבן עולה יורד (שם ה, י) כוונתו — \u0003כמשפט חטאת העוף\u0004 שהזכיר בפסוק הקודם, אבל הוא משווה באופן אחר: \u0003מה להלן\u0004"],["לאחר המליקה \u0003אוחז בראש ובגוף ומזה\u0004 מן הדם על המזבח — \u0003אף כאן,\u0004 בעולת העוף, \u0003אוחז בראש ובגוף ומזה.\u0004","ושואלים: \u0003מאי קאמר\u0004 \u0005[מה הוא אומר]?\u0006 ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003מה להלן,\u0004 בחטאת העוף, \u0003כשהוא\u0004 \u0003אחוז\u0004 (כשמחובר) \u0003הראש בגוף\u0004 הוא \u0003מזה,\u0004 שהרי נאמר \"לא יבדיל\", \u0003אף כאן\u0004 בעולת העוף — \u0003כשהוא אחוז הראש בגוף מזה,\u0004 ואינו מפריד את הראש לגמרי. והוא מה שנאמר לעיל בשם ר' שמעון בן אלעזר, שמבדיל בעולה רוב שנים ולא שנים. וממשיכה הברייתא:","\u0003אי\u0004 (אם כן) שהכתוב משווה עולת העוף לחטאת העוף, נאמר גם: \u0003מה להלן\u0004 בחטאת העוף — מבדיל \u0003בסימן אחד\u0004 ולא יותר, \u0003אף כאן\u0004 בעולת העוף יבדיל \u0003בסימן אחד\u0004 ולא יותר! על כן \u0003תלמוד לומר\u0004 בעולת העוף: \u0003\"והקריבו\"\u0004 (ויקרא א, טו), ולא \"והקריב\", להדגיש שהקרבתו שונה משל חטאת העוף, וצריך להבדיל יותר מסימן אחד, דהיינו רוב שנים. עד כאן לשון הברייתא.","ושואלים: \u0003ותנא קמא\u0004 \u0005[ו\u0006לשיטת \u0005התנא הראשון],\u0006 \u0003וכי מאחר דנפקא לן\u0004 \u0005[שיוצאת לנו]\u0006 ההלכה שצריך לחתוך לגמרי שני סימנים בעולת העוף \u0003מ\u0004מה שנאמר \u0003\"ומלק והקטיר\"\u0004 (שם), להקיש מליקה להקטרה, מה הקטרה — הראש בעצמו והגוף בעצמו, אף מליקה — הראש בעצמו והגוף בעצמו, אם כן מה שנאמר בעולת העוף \u0003\"והקריבו\"\u0004 להבדילו מחטאת העוף \u0003למה לי?\u0004","ומשיבים: \u0003אי לאו\u0004 \u0005[אם לא]\u0006 היה כתוב \u0003\"והקריבו\", הוה אמינא\u0004 \u0005[הייתי אומר]:\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"כמשפט\"\u0004 האמור בעולת העוף (ויקרא ה, י) — \u0003כמשפט חטאת העוף\u0004 האמור תחילה באותה פרשיה, ללמד שאינו מבדיל יותר מסימן אחד.","\u0003ואי\u0004 \u0005[ואם]\u0006 תאמר שאין ללמוד כך \u0003משום\u0004 ההיקש \u0003\"ומלק והקטיר\"\u0004 — \u0003הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 שיש ללמוד משם דין אחר: \u0003מה הקטרה\u0004 של עולת העוף נעשית \u0003בראשו של מזבח\u0004 — \u0003אף מליקה\u0004 תיעשה \u0003בראשו של מזבח,\u0004 בחציו העליון, ולא בחציו התחתון כחטאת,","\u0003השתא דכתב רחמנא\u0004 \u0005[עכשיו שכתבה התורה]\u0006 \u0003\"והקריבו\",\u0004 והבדילה לגמרי דין עולת עוף מדין חטאת העוף, \u0003דרוש ביה נמי הא\u0004 \u0005[דרוש בו גם כן,\u0006 מ\"מלק והקטיר\", \u0005את זו],\u0006 שצריך להבדיל לגמרי את הראש מהגוף. למדנו בברייתא כי לדעת התנא הראשון הוקשה עולת העוף לחטאת בהמה, שאינה באה אלא מן החולין ולא ממעות מעשר שני, ושהיא קרבה ביום דווקא ולא בלילה, ושעבודתה נעשית ביד ימין דווקא.","ושואלים: \u0003חטאת בהמה\u0004 עצמה, ש\u0003אינה באה אלא מן החולין, מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003אמר רב חסדא, דאמר קרא\u0004 \u0005[שאמר המקרא]:\u0006 \u0003\"והקריב אהרן את פר החטאת אשר לו\"\u0004 (ויקרא טז, ו, ושם יא), וההדגשה \"אשר לו\" באה ללמד: \u0003משלו\u0004 — \u0003ולא משל צבור,\u0004 וכן משלו — \u0003ולא משל מעשר\u0004 שני.","ושואלים: מה שצריכים להקריב את עולת העוף \u0003ביום,\u0004 הלוא \u0003מ\"ביום צוותו\"\u0004 (ויקרא ז, לח) \u0003נפקא\u0004 \u0005[יוצא,\u0006 נלמד \u0005הדבר],\u0006 שכל הקרבנות אינם קרבים אלא ביום! ומשיבים: אכן \u0003כדי נסבה\u0004 \u0005[לחינם הביא אותה]\u0006 כלומר, באמת אין הלכה זו נלמדת מכאן, אלא הביא אותה דרך אגב.","ועוד שואלים: מה שמולק את עולת העוף ב\u0003ידו הימנית\u0004 גם כן לא הוצרך להילמד מחטאת בהמה, שהרי דבר זה \u0003מ\u0004דברי \u0003רבה בר בר חנה נפקא\u0004 \u0005[יוצא],\u0006 ש\u0003אמר רבה בר בר חנה אמר ר' שמעון בן לקיש: כל מקום שנאמר\u0004 בקרבנות \u0003אצבע או\u0004 לשון \u0003כהונה\u0004 עבודת אותו קרבן \u0003אינה\u0004 נעשית \u0003אלא\u0004 ביד \u0003ימין,\u0004 ובעולת העוף הרי נאמר כהן (ויקרא א, טו)!","ומסבירים: \u0003ואידך\u0004 \u0005[והאחר],\u0006 הוא סבור שבמקום שנאמר \u0003כהונה בעיא\u0004 \u0005[צריך]\u0006 שיזכיר הכתוב גם \u0003אצבע,\u0004 כדי שתהא עבודת הקרבן האמור דווקא בימין, ואילו במקום שנאמר \u0003אצבע לא בעיא\u0004 \u0005[לא צריך]\u0006 הכתוב להזכיר גם לשון \u0003כהונה.\u0004 ובעולת העוף לא נזכרה אצבע, ולכן הוצרך ללומדה מחטאת בהמה. עוד נאמר בברייתא כי ר' ישמעאל למד מ\"כמשפט\" האמור בעולת העוף, שהמליקה בעולת העוף נעשית מול העורף (אחורי הצואר), כמו בחטאת העוף.","ושואלים: \u0003ותנא קמא\u0004 \u0005[והתנא הראשון]\u0006 \u0003ור' אלעזר בר' שמעון,\u0004 שלא למדו כמותו, שהמליקה \u0003ממול העורף מנא להו\u0004 \u0005[מנין להם]?\u0006 ומשיבים: \u0003גמרי\u0004 \u0005[למדים הם]\u0006 \u0003מליקה\u0004 שנאמרה בעולת העוף \"ומלק את ראשו\" (ויקרא א, טו) \u0003ממליקה\u0004 של חטאת העוף, שנאמר בה \"ומלק את ראשו ממול ערפו\" (שם ה, ח), שכך נעשית מליקה.","בתורה נאמר שהמביא קרבן מן העוף מביא תורים (בוגרים) או בני יונה (צעירים). ונמצא שה\u0003כשר בתורין,\u0004 עוף בוגר — \u0003פסול בבני יונה,\u0004 וה\u0003כשר בבני יונה,\u0004 עוף צעיר — \u0003פסול בתורין. תחלת הציהוב\u0004 של הנוצות — \u0003בזה ובזה פסול,\u0004 שיצא מגדר גוזל ועדיין לא נעשה בוגר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בפירוש משנתנו: \u0003תורין,\u0004 כשהם \u0003גדולים\u0004 — הריהם \u0003כשרים,\u0004 וכשהם \u0003קטנים\u0004 — \u0003פסולים; בני יונה\u0004 להיפך, כשהם \u0003קטנים\u0004 — הריהם \u0003כשרים,\u0004 כשהם \u0003גדולים\u0004 — הריהם \u0003פסולין. נמצא\u0004 שה\u0003כשר בתורין פסול בבני יונה,\u0004 וה\u0003כשר בבני יונה פסול בתורין.\u0004","ומביאים מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 במדרש הכתוב \"והקריב מן התורים או מן בני היונה\" (ויקרא א, יד): \u0003\"תורים\"\u0004 שאמרו הם \u0003גדולים ולא קטנים. שיכול\u0004 הייתי לומר, \u0003והלא דין הוא:\u0004"],["\u0003ומה בני יונה שלא הוכשרו בגדולים,\u0004 שהרי \"בני\" משמעו קטנים — \u0003הוכשרו בקטנים, תורים שהוכשרו בגדולים\u0004 — \u0003אינו דין שהוכשרו\u0004 גם \u0003בקטנים? תלמוד לומר: \"תורים\",\u0004 ללמד: \u0003גדולים\u0004 דווקא \u0003ולא קטנים.\u0004","ועוד דורשים: \u0003\"בני יונה\"\u0004 שהזכיר הכתוב כוונתו — \u0003קטנים\u0004 דווקא \u0003ולא גדולים.\u0004 והוצרך לכך, \u0003ש\u0004כן \u0003יכול\u0004 היית לומר: \u0003והלא דין הוא, ומה תורים שלא הוכשרו בקטנים,\u0004 שלא נאמר בהם \"בני\" — \u0003הוכשרו בגדולים, בני יונה שהוכשרו בקטנים\u0004 — \u0003אינו דין שהוכשרו\u0004 גם \u0003בגדולים?\u0004 לכך \u0003תלמוד לומר: \"בני יונה\",\u0004 ללמד: \u0003קטנים\u0004 דווקא \u0003ולא גדולים.\u0004","ושואלים: \u0003מאי תלמודא\u0004 \u0005[מהו הלימוד],\u0006 מהיכן בדיוק אנו למדים? \u0003אמר רבא:\u0004 מכך \u0003ש\u0004\u0003לא\u0004 מצאנו \u0003לישתמיט קרא ולכתוב\u0004 \u0005[\u0006ש\u0005ישתמט המקרא ויכתוב]\u0006 להיפך: \u0003\"מן בני התורים או מן היונה\",\u0004 אלא בכל מקום נכתב תורים ובני יונה, ומכאן ש\"בני יונה\" נאמר בדווקא — קטנים, ו\"תורים\" בדווקא — גדולים.","ושואלים: ושמא \u0003אימא\u0004 \u0005[אמור\u0006 כך\u0005]:\u0006 \u0003בני יונה דכתב בהו רחמנא\u0004 \u0005[שכתבה בהם התורה]\u0006 \u0003\"בני\"\u0004 כוונתו: \u0003קטנים\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003גדולים\u0004 — \u0003לא,\u0004 אבל \u0003תורים,\u0004 שנזכרו בלשון סתמית — \u0003אי בעי\u0004 \u0005[אם רוצה]\u0006 \u0003גדולים לייתי\u0004 \u0005[יביא]\u0006 \u0003אי בעי\u0004 \u0005[אם רוצה]\u0006 \u0003קטנים לייתי\u0004 \u0005[יביא]!\u0006 ומשיבים: צריך אתה לדון על תורים \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003בני יונה\u0004 כיון שנזכרו עמהם בכל מקום, כדי להקישם זה לזה: \u0003מה בני יונה, קטנים\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003גדולים\u0004 — \u0003לא, אף תורים, גדולים\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003קטנים\u0004 — \u0003לא.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003יכול יהו כל התורים\u0004 הגדולים \u0003וכל בני היונה\u0004 הקטנים \u0003כשרים? תלמוד לומר: \"מן התורים\"\u0004 (ויקרא א, יד) — \u0003ולא כל התורים, \"מן בני היונה\"\u0004 (שם) — \u0003ולא כל בני יונה, פרט לתחילת הציהוב\u0004 של נוצות הצואר \u0003שבזה ושבזה שפסול,\u0004 בתורים — מפני שאינם גדולים דיים, ובבני יונה — מפני שיצאו מכלל קטנים. ומפרטים: \u0003מאימתי התורים כשרים\u0004 — \u0003משיזהיבו,\u0004 משעה שצבע הנוצות מבריק, \u0003מאימתי בני יונה פסולין\u0004 — \u0003משיצהיבו\u0004 הנוצות.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003יעקב קרחה\u0004 ברייתא: \u0003מאימתי בני יונה כשרים? משיעלעו.\u0004 \u0003הוא תני לה\u0004 \u0005[שנה אותה]\u0006 את הברייתא הזו, \u0003והוא אמר\u0004 את הפירוש \u0003לה,\u0004 שהכוונה היא למה שנאמר \u0003\"אפרוחיו יעלעו דם\"\u0004 (איוב לט, ל). ושואלים: \u0003אימת\u0004 \u0005[מתי]\u0006 הזמן הזה? \u0003אמר אביי: מכי שמיט גדפא מיניה ואתי דמא\u0004 \u0005[מ\u0006שלב \u0005שכאשר שומט,\u0006 עוקר, \u0005נוצה ממנו יוצא דם],\u0006 שהדם מצוי בו.","בבירור מעמדו של שלב הציהוב בבני יונה ובתורים, ששנינו במשנה שהוא פסול, \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבי זירא: האומר \"הרי עלי עולה מן התורים או מן בני היונה\",\u0004 מאלו מהם שארצה, \u0003והביא\u0004 משניהם בשלב \u0003תחלת הציהוב שבזה ושבזה, מהו\u0004 דינו? האם בשלב זה \u0003ספיקא הוי\u0004 \u0005[ספק הוא]\u0006 האם נחשב העוף גדול או קטן, ולכן כשמביא משניהם \u0003נפיק\u0004 \u0005[יוצא]\u0006 ידי חובת נדרו, שהרי או בני היונה או התורים כשרים הם. \u0003או דילמא\u0004 \u0005[שמא]\u0006 שלב זה של תחילת הציהוב כ\u0003בריה\u0004 בפני עצמו \u0003הוי\u0004 \u0005[הוא],\u0006 שהעוף בשלב זה אינו נחשב קטן ולא גדול, \u0003ו\u0004אם כן, גם אם הביא משניהם \u0003לא נפיק\u0004 \u0005[אינו יוצא] ידי חובת\u0006 נדרו?","\u0003אמר רבא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו בברייתא, שהמיעוט \"מן התורים\" ו\"מן בני היונה\", בא ללמד: \u0003פרט לתחילת הציהוב שבזה ושבזה, ש\u0004הוא \u0003פסול.\u0004 ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 כי \u0003בריה\u0004 בפני עצמה \u0003הוי\u0004 \u0005[הוא]\u0006 — \u0003שפיר\u0004 \u0005[יפה],\u0006 מובן מדוע הוצרך הכתוב למעט, כדי שלא נבוא להכשירו כלל. \u0003אלא אי אמרת ספיקא הוי\u0004 \u0005[אם\u0006 \u0005אתה אומר\u0006 ש\u0005ספק הוא],\u0006 ורק משום כך אסרה המשנה להקריבו — וכי \u0003איצטריך קרא למעוטי ספיקא\u0004 \u0005[הוצרך הכתוב למעט\u0006 את ה\u0005ספק]?\u0006"],["ודוחים: לדעה זו, \u0003כי איצטריך קרא\u0004 \u0005[כאשר הוצרך הפסוק]\u0006 \"מן התורים או מן בני היונה\" (ויקרא א, יד) לא הוצרך למעט מהקרבה תחילת הציהוב שבזה ובזה, אלא \u0003למעוטי\u0004 \u0005[למעט]\u0006 עוף ש\u0003נרבע\u0004 על ידי אדם, \u0003ו\u0004עוף ש\u0003נעבד\u0004 כעבודה זרה.","שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל וכתיב\u0004 \u0005[ונאמר]\u0006 בדיני קרבנות פסולים: \u0003\"כי משחתם בהם מום בם\"\u0004 (ויקרא כב, כה), שגם השחתה וגם מום פוסלים בהם; \u0003ו\u0004פסול השחתה כולל נרבע ונעבד, כפי ש\u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003רבי ישמעאל: כל מקום שנאמר\u0004 לשון \u0003השחתה אינו אלא דבר ערוה ועבודה זרה; דבר ערוה\u0004 מנין? \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כי השחית כל בשר את דרכו על הארץ\"\u0004 (בראשית ו, יב),","\u0003עבודה זרה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"פן תשחיתון ועשיתם לכם פסל\"\u0004 (דברים ד, טז). וממה שהקיש הכתוב מום להשחתה יש ללמוד כי \u0003כל שהמום פוסל בו\u0004 — אף \u0003דבר ערוה ועבודה זרה פוסלין\u0004 \u0003בו, וכל שאין המום פוסל בו\u0004 אף \u0003אין דבר ערוה\u0004 \u0003ועבודה זרה פוסלין בו. ו\u0004לפיכך \u0003הני\u0004 \u0005[אלה]\u0006 ה\u0003עופות, הואיל ולא פסיל בהו מומא\u0004 \u0005[ואין פוסל בהם מום],\u0006 \u0003דאמר מר\u0004 \u0005[שאמר החכם]:\u0006 דין \u0003תמות,\u0004 שהקרבן צריך להיות תם ולא בעל מום, \u0003וזכרות,\u0004 שיהיה זכר ולא נקבה, הוא דווקא \u0003בבהמה ואין תמות וזכרות בעופות, אימא\u0004 \u0005[אמור]:\u0006 \u0003דבר ערוה ועבודה זרה נמי לא לפסול בהו\u0004 \u0005[גם כן לא יפסלו בהם],\u0006 וגם נרבע ונעבד בעוף יהיו כשרים להקרבה, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 המיעוט \"מן התורים או מן בני היונה\" (ויקרא א, יד), שיש תורים ובני יונה שאינם קרבים, והם הנרבע והנעבד.","בדומה לדיון במעמד שלב תחילת הציהוב בתורים ובבני יונה, מביאים ענין דומה שדנו בו חכמים האם מדובר בספק או בבריה לעצמה. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבי זירא: האומר \"הרי עלי עולת בהמה מן האיל\u0004 (כבש בוגר, משעברו עליו שלושה עשר חדשים) \u0003או מן הכבש\u0004 (בתוך שנתו הראשונה)\", שנדר להביא איזה מהם שירצה, \u0003והביא פלגס,\u0004 שהוא כבש בן יותר משנה, אלא שעדיין לא מלאו לו שלושה עשר חודש, \u0003מהו\u0004 דינו? האם יצא ידי חובת נדרו?","ומפרטים: \u0003אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003רבי יוחנן לא תבעי\u0004 \u0005[לא תישאל]\u0006 \u0003לך,\u0004 שבוודאי אינו יוצא ידי חובתו, \u0003דאמר\u0004 \u0005[\u0006מפני \u0005שהוא אומר]:\u0006 פלגס \u0003בריה\u0004 בפני עצמה \u0003הוי\u0004 \u0005[הוא]\u0006 נחשב, ואינו לא כבש ולא איל. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 היה מחוייב איל או כבש והביא פלגס ו\u0003הקריבו\u0004 — \u0003מביא עליו\u0004 מנחה ו\u0003נסכי\u0004 קרבן \u0003איל,\u0004 שני עשרונים סולת בלולים בשלישית ההין (ארבעה לוגים) שמן, ושלישית ההין יין, \u0003ו\u0004אולם \u0003אין עולה לו מזבחו,\u0004 אינו יוצא ידי חובתו.","\u0003ואמר ר' יוחנן:\u0004 טעם הדבר שמביא נסכי איל — מפני שנאמר בפרשת הנסכים \u0003\"או לאיל\u0004 תעשה מנחה\" וכו' (במדבר טו, יא), והמלה \"או\" באה \u0003לרבות את הפלגס,\u0004 שיביא גם לו נסכי איל. וכיון שלדעתו הוצרך הכתוב לרבותו, נמצא שהוא סבור שהוא בריה בפני עצמה, ואין זה מחמת הספק.","\u0003כי תבעי\u0004 \u0005[כאשר תישאל]\u0006 \u0003לך\u0004 השאלה — הרי זה \u0003אליבא\u0004 \u0005[על פי שיטתו]\u0006 של \u0003בר פדא,\u0004 הסבור שיש בו ספק,"],["\u0003דאמר\u0004 \u0005[ש\u0006הוא \u0005אומר]:\u0006 המקריב פלגס \u0003מייתי ומתני\u0004 \u0005[מביא\u0006 נסכים של איל \u0005ומתנה],\u0006 שאם איל הוא — הרי אלו נסכיו, ואם כבש הוא, שנסכיו מועטים משל איל — יהא המותר נדבה; לשיטתו,","\u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]:\u0006 ב\u0003איל וכבש מתנה, בבריה\u0004 בפני עצמה, שאינה לא זה ולא זה — \u0003לא מתנה,\u0004 שלדעתו ודאי אינו בריה לעצמה, אלא רק ספק כבש או איל. \u0003או דלמא\u0004 \u0005[שמא]\u0006 לשיטתו \u0003בבריה נמי\u0004 \u0005[גם כן]\u0006 \u0003מתנה,\u0004 \u0003דאמר\u0004 \u0005[שאומר]:\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003בריה הוה\u0004 \u0005[היא],\u0006 שאינו איל ולא כבש, ואינו חייב בנסכים האמורים בהם — \u0003ליהוי כוליה\u0004 \u0005[שיהיה כולו]\u0006 \u0003נדבה.\u0004 ולדרך זו, גם לשיטתו, אם נדר שיביא איל או כבש והביא פלגס — מספק לא יצא ידי חובתו? בעיה זו לא נפתרה, ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","ענין \"בריה בפני עצמה\" נדון גם ביחס לקרבן תודה שצריך להביא עמו עשרים עשרון ללחמי התודה, עשרה עשרונים למצה ועשרה לחמץ. \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבי זירא: האומר \"הרי עלי\u0004 עשרה עשרונים \u0003לחמי תודה, מן החמץ או מן המצה\"\u0004 מאיזה שארצה, \u0003והביא\u0004 \u0003שיאור,\u0004 שהוא ספק מצה ספק חמץ, \u0003מהו\u0004 דינו? האם יוצא בו ידי חובת נדרו?","והואיל ונחלקו חכמים בהגדרת השיאור, שואלים תחילה: \u0003ב\u0004\u0003שיאור דמאן\u0004 \u0005[של מי]?\u0006 לדעת מי מדובר? \u0003אי\u0004 \u0005[אם]\u0006 תאמר ב\u0003שיאור\u0004 לדעת \u0003ר' מאיר,\u0004 שפניו של הבצק הכסיפו (החווירו), ו\u0003ל\u0004שיטת \u0003רבי יהודה\u0004 הסבור שאינו חמץ כלל — הרי \u0003מצה מעלייתא\u0004 \u0005[מעולה]\u0006 \u0003היא,\u0004 ויצא ידי חובת נדרו במצה!","\u0003אי\u0004 \u0005[אם]\u0006 בשיאור לדעת \u0003רבי יהודה,\u0004 שכבר נתהוו בו סדקים כקרני חגבים, ו\u0003ל\u0004פי שיטת \u0003ר' מאיר\u0004 — הרי לשיטת ר' מאיר \u0003חמץ\u0004 גמור \u0003הוא,\u0004 ויצא ידי חובת נדרו בחמץ!","\u0003ו\u0004גם \u0003אי\u0004 \u0005[אם]\u0006 מדובר בשיאור לדעת \u0003ר' מאיר,\u0004 ו\u0003ל\u0004שיטת \u0003ר' מאיר,\u0004 הרי למרות שאינו חייב על אכילתו כרת, מכל מקום \u0003מדלקי עליה\u0004 \u0005[מכיון ש\u0006לדעת ר' מאיר \u0005הוא לוקה עליו]\u0006 מן התורה — ודאי \u0003חמץ הוא,\u0004 ואם כן יצא ידי חובת נדרו בחמץ!","\u0003אלא\u0004 צריך לומר ששאלת ר' זירא היא במי שהביא עשר חלות שיאור לדעת \u0003רבי יהודה,\u0004 ו\u0003ל\u0004שיטת \u0003רבי יהודה,\u0004 שאינו לוקה עליו, ומכל מקום צריך לשרוף אותו, ומכאן שיש בו צד חמץ, \u0003מאי\u0004 \u0005[מה\u0006 דינו\u0005]?\u0006 האם \u0003ספיקא הויא\u0004 \u0005[ספק הוא],\u0006 \u0003ונפיק\u0004 \u0005[ויוצא]\u0006 ידי חובת נדרו \u0003ממה נפשך\u0004 \u0005[מאיזה צד שתרצה],\u0006 שאם מצה הוא — יוצא ידי חובת חלות תודה מן המצה, ואם חמץ — יוצא ידי חובת חלות תודה חמץ. \u0003או דלמא\u0004 \u0005[שמא]\u0006 שיאור \u0003בריה\u0004 לעצמו \u0003הוא,\u0004 לא מצה ולא חמץ, \u0003ולא נפיק\u0004 \u0005[ואינו יוצא]\u0006 בו ידי חובתו כלל? ומקשים: וגם אם ספק הוא, כיצד ייתכן שיצא אדם ידי נדרו באותו שיאור?","\u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב הונא: האומר \"הרי עלי לחמי תודה\"\u0004 — \u0003מביא תודה ולחמה\u0004 בשלימות, עשרה עשרונים מצה ועשרה עשרונים חמץ; \u0003וכיון דאיחייב ליה\u0004 \u0005[שהתחייב הוא]\u0006 \u0003בתודה ו\u0004כל \u0003לחמה, הא לא ידע האי גברא\u0004 \u0005[הרי אין יודע אותו אדם]\u0006 שהביא שיאור \u0003אי\u0004 \u0005[אם]\u0006 אותו שיאור \u0003חמץ הוא, דליתי\u0004 \u0005[שיביא]\u0006 \u0003מצה\u0004 להשלים את חובת לחמי התודה, \u0003אי\u0004 \u0005[\u0006או \u0005אם]\u0006 \u0003מצה הוא, דליתי\u0004 \u0005[שיביא]\u0006 \u0003חמץ\u0004 להשלים אותו. ובכל מקרה אינו יוצא ידי חובת קרבן תודתו עד שיביא עוד קרבן שלם של לחמי תודה, חמץ ומצה!","ומשיבים: \u0003לא צריכא\u0004 \u0005[לא נצרכה]\u0006 שאלתו של ר' זירא, אלא במי ש\u0003אמר \"הרי עלי חלה\u0004 (חלות) מן החמץ או מן המצה, על מנת \u0003לפטור\u0004 חובת לחמי \u0003תודתו של פלוני\",\u0004 ונמצא שהוא עצמו יוצא ידי חובת נדרו, שהרי לא חייב עצמו בקרבן תודה.","ומקשים: \u0003סוף סוף הא לא ידע האי גברא\u0004 \u0005[הרי אין יודע אותו אדם],\u0006 החבר, \u0003אי\u0004 \u0005[אם]\u0006 מה שהביא \u0003חמץ הוא, דליתי\u0004 \u0005[שיביא]\u0006 \u0003מצה\u0004 להשלים את חובת תודתו, \u0003אי\u0004 \u0005[\u0006או \u0005אם]\u0006 \u0003מצה הוא, דליתי\u0004 \u0005[ש\u0006יוסיף ו\u0005יביא]\u0006 \u0003חמץ,\u0004 ונמצא שהנודר אינו מקיים את נדרו לפטור תודתו של חבירו, שהרי החבר לא יצא ידי קרבן תודתו במה שהביא עבורו! ומשיבים: \u0003לא צריכא\u0004 \u0005[לא נצרכה]\u0006 שאלתו של ר' זירא, אלא במקרה שאמר \"הרי עלי חלות לתודתו של פלוני\", ו\u0003לא אמר\u0004 \"על מנת \u0003לפטור\u0004 תודתו\", שאינו בא לפטור את חבירו מחובתו, אלא רק להוסיף עליו, ואם כן אין כאן אלא שאלה ביחס לנודר עצמו, האם \u0003מיפק גברא\u0004 \u0005[לצאת האיש]\u0006 \u0003ידי נדרו נפיק\u0004 \u0005[יוצא],\u0006 \u0003או לא נפיק\u0004 \u0005[אינו יוצא]?\u0006 גם שאלה זו לא נפתרה ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","מה שהוא \u0003כשר בפרה\u0004 אדומה \u0003—\u0004 \u0003פסול בעגלה\u0004 ערופה, ומה ש\u0003כשר בעגלה\u0004 — \u0003פסול בפרה.\u0004","בפירוש משנתנו מביאים מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003פרה\u0004 אדומה — \u0003בשחיטה כשרה, בעריפה פסולה; עגלה\u0004 — \u0003בעריפה כשרה, בשחיטה פסולה. נמצאת\u0004 אומר: \u0003כשר בפרה\u0004 — \u0003פסול בעגלה, כשר בעגלה\u0004 — \u0003פסול בפרה.\u0004","ומציעים: \u0003ותהא פרה כשרה בעריפה מקל וחומר, ומה עגלה שלא הוכשרה בשחיטה,\u0004 כפי שיילמד להלן (כד,א) — \u0003הוכשרה בעריפה, פרה שהוכשרה בשחיטה,\u0004 שנאמר \"ושחט אותה\" (במדבר יט, ג) — \u0003אינה דין שהוכשרה בעריפה?\u0004"],["\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בפרה אדומה \u0003\"ושחט\u0004 אותה\" (במדבר יט, ג) \u0003ו\u0004נאמרה שם לשון \u0003חוקה\u0004 \"זאת חוקת התורה\" (שם ב), לומר ש\u0003בשחיטה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003בעריפה\u0004 — \u0003לא,\u0004 שכל מקום שנאמר \"חוקה\" הרי זה לעכב.","ושואלים: \u0003וכל היכא דכתיב ביה\u0004 \u0005[וכל מקום שנאמר בו]\u0006 \u0003חוקה לא דרשינן\u0004 \u0005[אין דורשים אנו]\u0006 באותו ענין \u0003קל וחומר,\u0004 לרבות דברים נוספים? \u0003והא\u0004 \u0005[והרי]\u0006 ל\u0003גבי יום הכפורים, דכתיב ביה\u0004 \u0005[שנאמר בו]\u0006 לשון \u0003חוקה\u0004 (\"והיתה זאת לכם לחוקת עולם\", ויקרא טז, לד), \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 נאמר \"והקריב וכו' את השעיר אשר עלה עליו הגורל לה' \u0003ועשהו חטאת\"\u0004 (שם ט), ולא נאמר \"את השעיר לה' \" — ללמד: \u0003הגורל\u0004 הוא ה\u0003עושה\u0004 אותו \u0003חטאת, ואין השם\u0004 שקורא לו \"חטאת\" \u0003עושה\u0004 אותו \u0003חטאת. ש\u0004אם לא כתוב זה","\u0003יכול\u0004 היית לומר, \u0003והלא דין הוא: ומה במקום שלא קדש הגורל,\u0004 בכל שאר הקרבנות, שלא מצאנו שמקדשים אותם על ידי גורל — \u0003קדש השם,\u0004 שהקרבן נקרא לפי השם שקורא לו הבעלים, \u0003מקום שקדש הגורל,\u0004 בשעירי יום הכפורים — \u0003אינו דין שקדש השם? תלמוד לומר: \"ועשהו חטאת\",\u0004 ללמד: \u0003הגורל עושה\u0004 אותו \u0003חטאת ואין השם עושה\u0004 אותו \u0003חטאת.\u0004","ונלמד מכאן: \u0003טעמא דכתב רחמנא\u0004 \u0005[הטעם\u0006 שאין אומרים כן \u0005הוא\u0006 מפני \u0005שכתבה התורה]\u0006 \u0003\"ועשהו חטאת\", הא לאו הכי דרשינן\u0004 \u0005[הרי ללא כן היינו דורשים]\u0006 \u0003קל וחומר,\u0004 למרות שנאמרה לשון חוקה באותו ענין!","ומשיבים: אכן, באופן עקרוני ניתן לדרוש קל וחומר במקום שנאמר חוקה, אלא שבמקרה זה \u0003מיעט רחמנא\u0004 \u0005[מיעטה התורה]\u0006 ל\u0003גבי עגלה\u0004 שנאמר בה \u0003\"הערופה\"\u0004 (דברים כא, ו), בה' הידיעה, להדגיש: \u0003זאת בעריפה ואין אחרת\u0004 (פרה אדומה) \u0003בעריפה.\u0004","ושואלים: \u0003ותהא עגלה כשרה בשחיטה מקל וחומר, ומה פרה\u0004 אדומה \u0003שלא הוכשרה בעריפה\u0004 — \u0003כשרה בשחיטה, עגלה שכשרה בעריפה\u0004 — \u0003אינו דין שהוכשרה בשחיטה?\u0004 ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"וערפו\"\u0004 (שם ד), ושוב \u0003\"העגלה\u0004 הערופה\" (שם ד), לומר: \u0003בעריפה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003בשחיטה\u0004 — \u0003לא.\u0004","יש דבר שהוא \u0003כשר בכהנים\u0004 ו\u0003פסול בלוים,\u0004 ויש דבר שהוא \u0003כשר בלוים\u0004 ו\u0003פסול בכהנים.\u0004","בפירושה של משנתנו, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כהנים, במומין\u0004 — \u0003פסולים,\u0004 כלומר, אם יש בהם \u0003מום מהמומים המנויים בתורה (ויקרא כא, טז—\u0004 כג) הרי הם פסולים לעבודת המקדש, אבל \u0003בשנים\u0004 הם \u0003כשרים,\u0004 שכל כהן שאינו קטן כשר לעבודה ללא הגבלה של גיל. ואילו \u0003לוים, במומין\u0004 — \u0003כשרים,\u0004 שאין המום פוסל אותם לעבודתם במקדש, אבל \u0003בשנים\u0004 — \u0003פסולים,\u0004 שהם כשרים לעבודה מגיל עשרים וחמש ועד גיל חמשים (במדבר ח, כד— כה). \u0003נמצא\u0004 שמה ש\u0003כשר בכהנים\u0004 \u0003פסול בלוים,\u0004 ומה ש\u0003כשר בלוים פסול בכהנים.\u0004","ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 מה שנאמר \u0003\"זאת אשר ללוים\"\u0004 (במדבר ח, כד) \u0003מה תלמוד לומר?\u0004 מדוע הוצרך להדגשה זאת? \u0003לפי\u0004 שממה \u0003שנאמר: \"ומבן חמשים שנה ישוב\u0004 מצבא העבודה ולא יעבוד עוד\" (שם כה), \u0003למדנו ללוים שהשנים פוסלין בהם,\u0004 ואולם \u0003יכול מומין פוסלין\u0004 \u0003בהם\u0004 גם כן? \u0003ו\u0004לכאורה \u0003דין הוא\u0004 שנאמר כן: \u0003ומה כהנים שאין השנים פוסלין בהן,\u0004 שלא הזכיר זאת הכתוב — \u0003מומין פוסלין בהן, לוים שהשנים פוסלין בהם\u0004 — \u0003אינו דין שיהו\u0004 גם \u0003מומין פוסלין בהם? תלמוד לומר: \"זאת אשר ללוים\",\u0004 \"זאת\" הרי היא לשון דיוק וצמצום — \u0003זאת,\u0004 פסול שנים יש \u0003ללוים,\u0004 \u0003ואין אחרת,\u0004 פסול מום \u0003ללוים.\u0004","ומצד שני, \u0003יכול יהו הכהנים פסולין בשנים? ו\u0004לכאורה, \u0003הלא דין הוא\u0004 שנאמר כן: \u0003ומה לוים שאין מומין פוסלין בהם\u0004 — בכל זאת \u0003שנים פוסלין בהם, כהנים שהמומין פוסלין בהם\u0004 — \u0003אינו דין שיהו שנים פוסלין בהם? תלמוד לומר: \"אשר ללוים\"\u0004 — \u0003ולא אשר לכהנים.\u0004","\u0003יכול אף\u0004 במשכן שהיה \u0003בשילה ובבית עולמים\u0004 (בית המקדש שבירושלים) הדין \u0003כן,\u0004 שהלויים נפסלים בשנים? \u0003תלמוד לומר\u0004 במקום אחר ביחס ללויים: \"מבן שלושים שנה ומעלה ועד בן חמשים שנה כל הבא \u0003לעבוד עבודת עבודה\u0004 (כגון שירה על הקרבן) \u0003ועבודת משא\"\u0004 (שם ד, מז), להקיש את שני סוגי עבודות הלויים זו לזו, כאומר: \u0003לא אמרתי\u0004 שהם פסולים בשנים, \u0003אלא בזמן שהעבודה בכתף,\u0004 כלומר, בזמן שהם צריכים לשאת את המשכן ממקום למקום. ובשילה, כמו בירושלים, היה משכן קבוע של אבנים.","אגב הזכרת כתוב זה בענין תחילת עבודת הלוים, מעירים: \u0003כתוב אחד אומר: \"מבן חמש ועשרים שנה ומעלה\"\u0004 (שם ח, כד), \u0003וכתוב אחד אומר: \"מבן שלשים\"\u0004 (שם ד, מז), \u0003אי אפשר לומר שלשים\u0004 — \u0003ש\u0004הרי \u0003כבר נאמר חמש ועשרים, ואי אפשר לומר עשרים וחמש\u0004 — \u0003ש\u0004הרי \u0003כבר נאמר שלשים, הא כיצד? חמש ועשרים\u0004 הוא הזמן \u0003לתלמוד,\u0004 ללמוד ולהתלמד בעבודת הלויים, \u0003ו\u0004בשנת \u0003שלשים\u0004 הוא הזמן \u0003לעבודה\u0004 ממש.","\u0003מכאן\u0004 רמז \u0003לתלמיד שלא ראה סימן יפה במשנתו חמש שנים,\u0004 שלומד ואינו מבין וזוכר כראוי — \u0003שוב אינו רואה. ר' יוסי אומר: שלש שנים\u0004 הן הזמן הנצרך לתלמיד, לראות אם הוא מצליח בלימודיו, מניין? \u0003שנאמר\u0004 בדניאל וחבריו, שציוה מלך בבל: \u0003\"ולגדלם שנים שלש\"\u0004 (דניאל א, ה), ומטרת אותו זמן היתה \u0003\"וללמדם ספר ולשון כשדים\"\u0004 (שם ד).","ומעירים: \u0003ואידך\u0004 \u0005[והאחר],\u0006 שאומר שצריך חמש שנים, אינו למד מכאן, \u0003כי\u0004 \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003לשון כשדים, דקליל\u0004 \u0005[שהיא קלה]\u0006 ללימוד למי שמדבר בשפה העברית, שהיא דומה לה. \u0003ו\u0004אילו \u0003אידך\u0004 \u0005[האחר],\u0006 ר' יוסי שלמד משם ולא מן הלויים, אומר: \u0003שאני\u0004 \u0005[שונות]\u0006 \u0003הלכות עבודה, דתקיפין\u0004 \u0005[שהן קשות יותר],\u0006 אבל בלימודים אחרים די בשלוש שנים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כהן משיביא שתי שערות\u0004 במקום הערוה, משיגיע לבגרות, \u0003עד שיזקין\u0004 — \u0003כשר לעבודה, ומומין פוסלין בו.\u0004 ואילו \u0003בן לוי מבן שלשים ועד בן חמשים כשר לעבודה, ושנים פוסלין בו. במה דברים אמורים? באהל מועד שבמדבר, אבל בשילה ובבית עולמים אין\u0004 הלויים \u0003נפסלין\u0004 בשנים, \u0003אלא בקול,\u0004 כאשר אינם יכולים לשיר כראוי עם אחיהם. \u0003אמר ר' יוסי: מאי קרא\u0004 \u0005[מהו המקרא]\u0006 המלמד על כך?"],["\u0003\"ויהי כאחד למחצצרים ולמשוררים להשמיע קול אחד\"\u0004 (דברי הימים ב ה, ג), משמע שהלויים צריכים להיות כולם מסוגלים לשיר בקול אחד, ומי שאינו יכול לשיר עוד כאחד מהם הרי הוא פסול. שנינו שהכהן כשר לעבודה \u0003עד שיזקין.\u0004 ושואלים: \u0003עד כמה?\u0004","מהי הגדרת זיקנה לענין זה? \u0003אמר רבי אלעא אמר ר' חנינא: עד שירתת,\u0004 שידיו ורגליו רועדות.","ועוד בענין הגדרת זיקנה \u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במסכת מקואות: \u0003בעל קרי שטבל ולא הטיל מים\u0004 קודם שטבל, \u0003לכשיטיל\u0004 מים אחרי כן — \u0003טמא,\u0004 משום שמקצת משכבת הזרע נשאר בגופו, ויצא עם מי הרגלים, ובכך חזר ונטמא. \u0003ר' יוסי אומר:\u0004 דווקא \u0003בחולה ובזקן\u0004 — הרי הוא \u0003טמא\u0004 כשלא הטיל מים לפני הטבילה, אבל \u0003בילד\u0004 (שאינו זקן) \u0003ובבריא\u0004 — \u0003טהור,\u0004 מפני שמתחילה יצאה ממנו כל שכבת הזרע בכח.","ושואלים: \u0003ילד עד כמה?\u0004 עד מתי הוא נחשב ילד ולא זקן? \u0003אמר רבי אלעא אמר רבי חנינא: כל\u0004 זמן \u0003שעומד על רגלו אחת ו\u0004באותה שעה \u0003חולץ מנעלו\u0004 או \u0003נועל מנעלו\u0004 שברגלו האחרת. ומעירים: \u0003אמרו עליו על רבי חנינא\u0004 עצמו, \u0003שהיה בן שמונים שנה והיה עומד על רגלו אחת וחולץ מנעלו ונועל מנעלו. אמר רבי חנינא: חמין\u0004 שרחצה אותי אמי בהם \u0003ושמן שסכתני\u0004 (שסכה אותי) \u0003אמי בילדותי הן עמדו לי בעת זקנותי\u0004 שאשאר בשלימות הבריאות.","ועוד בענין הגיל הראוי לעבודה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מי ש\u0003נתמלא זקנו, ראוי ליעשות שליח ציבור\u0004 לעניינים שונים, \u0003ולירד לפני התיבה\u0004 ולהתפלל, \u0003ו\u0004אם היה כהן — \u0003לישא את כפיו\u0004 ולברך את העם. \u0003מאימתי כשר\u0004 הכהן \u0003לעבודה? משיביא שתי שערות\u0004 במקום הערוה, שאז הוא נחשב גדול. \u0003רבי אומר, אומר אני:\u0004 אינו כשר לעבודה \u0003עד שיהא בן עשרים.\u0004","\u0003אמר רב חסדא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רבי? דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויעמידו\u0004 את \u0003הלוים מבן עשרים שנה ומעלה לנצח על מלאכת בית ה' \"\u0004(עזרא ג, ח). \u0003ואידך\u0004 \u0005[והאחר,\u0006 התנא הראשון\u0005],\u0006 מדוע אינו לומד מכאן? לדעתו \u0003לנצח\u0004 על מלאכת בית ה', \u0003שאני\u0004 \u0005[שונה],\u0006 שצריך לזה איש בוגר, אבל לעבוד עבודה אחרת הוא יכול כבר מזמן שמגיע לבגרות גופנית.","ושואלים: וכיצד למדים מכאן לכהנים? \u0003והא האי קרא\u0004 \u0005[והרי מקרא זה]\u0006 \u0003בלוים כתיב\u0004 \u0005[נאמר]!\u0006 ומשיבים: צריכים לפרש אותו \u0003כ\u0004דברי \u0003ר' יהושע בן לוי,\u0004 ש\u0003אמר רבי יהושע בן לוי\u0004 לענין אחר: \u0003בעשרים וארבעה מקומות\u0004 במקרא \u0003נקראו כהנים \"לוים\", וזה אחד מהן: \"והכהנים הלוים בני צדוק\"\u0004 (יחזקאל מד, טו), וגם הפסוק שאנו עוסקים בו הוא בין אותם מקומות.","ועוד בענין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר בפרשת הכהנים הפסולים לעבודה: \"דבר אל אהרן וכו' \u0003איש מזרעך לדורותם\u0004 אשר יהיה בו מום לא יקרב להקריב לחם א-להיו\" (ויקרא כא, יז), \u0003מכאן,\u0004 ממה שהקדים הכתוב ואמר \"איש\", \u0003אמר רבי אלעזר: קטן פסול לעבודה, ואפילו\u0004 היה \u0003תם\u0004 שלם בלא מום. \u0003מאימתי\u0004 הכהן \u0003כשר לעבודה? משיביא שתי שערות, אבל אחיו הכהנים אין מניחין אותו לעבוד עד שיהא בן עשרים.\u0004 ונחלקו בהבנה המדוייקת של ברייתא זו.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 כשיטת \u0003רבי היא,\u0004 שאמר בברייתא לעיל כי הכהן כשר לעבודה משעה שיהא בן עשרים, \u0003ו\u0004מכאן אנו למדים כי קודם לכן \u0003אפילו פסול דרבנן לית ליה\u0004 \u0005[שמדברי חכמים אין בו]\u0006 בדיעבד, אלא שלכתחילה כך צריכים הכהנים לנהוג. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003רבי אית ליה\u0004 \u0005[יש לו]\u0006 \u0003פסול מדרבנן\u0004 \u0005[מדברי סופרים]\u0006 עד שיהא בן עשרים, \u0003והא\u0004 \u0005[\u0006וברייתא \u0005זו]\u0006 כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003היא,\u0004 החולקים על רבי בברייתא, ומכשירים כהן לעבודה משיביא שתי שערות. ולשיטתם \u0003לכתחלה הוא\u0004 ש\u0003לא\u0004 יעבוד עד שיהא בן עשרים, כפי ששנינו בברייתא זו, \u0003אבל דיעבד\u0004 — \u0003עבודתו כשרה,\u0004 כפי ששנו לעיל.","ועוד בסגנון המשניות הקודמות: מה ש\u0003טהור בכלי חרש\u0004 — \u0003טמא בכל\u0004 שאר \u0003הכלים,\u0004 כגון כלי מתכת וכלי עץ. ומה ש\u0003טהור בכל\u0004 שאר \u0003הכלים\u0004 — \u0003טמא בכלי חרש.\u0004","בפירוש משנתנו \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אויר\u0004 (חלל) \u0003כלי חרש טמא,\u0004 שאם נפל דבר טמא, כגון שרץ מת לתוך חללו של כלי חרס — טימא אותו, גם אם לא נגע בו. \u0003ו\u0004אילו \u0003גבו,\u0004 אם נגע שרץ בצידו החיצוני של כלי חרס — הרי הוא \u0003טהור.\u0004 ולהיפך, \u0003אויר כל\u0004 שאר \u0003הכלים טהור,\u0004 שאין הכלי עצמו נטמא כל זמן שלא נגעה בו הטומאה, \u0003ו\u0004אילו \u0003גבן טמא,\u0004 אם נגעה טומאה בגבם. \u0003נמצא,\u0004 שה\u0003טהור בכלי חרש,\u0004 שנגעה טומאה בגבו — \u0003טמא בכל הכלים,\u0004 וה\u0003טהור בכל הכלים,\u0004 שהגיעה טומאה לאוירו — \u0003טמא בכלי חרש.\u0004","ואומרים: \u0003מנהני מילי\u0004 \u0005[מנין דברים אלה]\u0006 שכלי חרס נטמא באוירו ולא מגבו? \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים],\u0006 נאמר בפרשת השרצים הטמאים: \"וכל כלי חרש אשר יפול מהם אל תוכו כל אשר בתוכו יטמא, ואותו תשבורו\" (ויקרא יא, לג), ונדייק: \"אל \u0003תוכו\"\u0004 — \u0003ואף על פי שלא נגע\u0004 בו נטמא הכלי.","ויש לשאול, \u0003אתה אומר\u0004 שנטמא באוירו \u0003אף על פי שלא נגע? או אינו\u0004 נטמא \u0003אלא אם כן נגע\u0004 בו השרץ! בתשובה לכך \u0003רבי יונתן בן אבטולמוס אומר: נאמר\u0004 בפסוק זה \u0003\"תוכו\"\u0004 לענין \u0003לטמא,\u0004 שהכלי מטמא את האוכלים שבתוכו, שנאמר: \"כל אשר בתוכו יטמא\", \u0003ונאמר \"תוכו\"\u0004 לענין \u0003ליטמא,\u0004 שהכלי עצמו נטמא על ידי השרץ שנמצא בתוכו, שנאמר שם: \"אשר יפול מהם אל תוכו... ואותו תשבורו\", ויש ללמוד בגזירה שווה: \u0003מה \"תוכו\" האמור לטמא\u0004 מה שבתוכו, הוא \u0003אף על פי שלא נגע\u0004 השרץ בכלי החרס עצמו, אלא נמצא באוירו, \u0003אף \"תוכו\" האמור ליטמא\u0004 הכלי עצמו — \u0003אף על פי שלא נגע\u0004 בו השרץ.","ושואלים: \u0003והתם\u0004 \u0005[ושם],\u0006 לטמא אחרים שבתוכו, \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שהוא מטמא אפילו לא נגע בו השרץ? \u0003אמר רבי יונתן: התורה העידה על כלי חרס\u0004 שכל שבתוכו נטמא"],["\u0003ואפילו\u0004 הכלי \u0003מלא\u0004 גרגרי \u0003חרדל,\u0004 שרוב גרגרי החרדל אינם נוגעים בדפנותיו, ולמרות זאת הם נטמאים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא בר אהבה לרבא: ויהא כלי חרס מיטמא מגבו, מקל וחומר: ומה כל\u0004 שאר \u0003הכלים\u0004 (שאינם כלי חרס) \u0003שאין מיטמאין מ\u0004טומאה המצויה ב\u0003אוירן\u0004 — \u0003מיטמאין מגבן,\u0004 אם נגעה בהם טומאה, \u0003כלי חרס שמיטמא\u0004 \u0003מאוירו\u0004 — \u0003אינו דין שיטמא מגבו?\u0004","ומשיבים, \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בדין הכלים הנמצאים באוהל המת: \u0003\"וכל כלי פתוח אשר אין צמיד פתיל\u0004 (שאין מכסהו מהודק) \u0003עליו\u0004 טמא הוא\" (במדבר יט, טו), ומשמע שטומאתו תלויה בפתחו, ויש לשאול: \u0003איזהו כלי שטומאתו קודמת\u0004 (מקדימה) \u0003לפתחו,\u0004 שנטמא ברגע שהטומאה נכנסת בפתחו — \u0003הוי אומר: זה כלי חרס,\u0004 כפי שנאמר בטומאת השרץ: \"וכל כלי חרש אשר יפול מהם אל תוכו\" וכו' (ויקרא יא, לג). ועל כלי זה אמר הכתוב שדווקא \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003אין צמיד פתיל עליו הוא\u0004 ש\u0003טמא\u0004 מפני שהטומאה נכנסת לאוירו, \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003יש צמיד פתיל עליו,\u0004 ואין הטומאה נכנסת לאוירו — \u0003טהור,\u0004 שאינו נטמא מגבו למרות שהוא באוהל המת.","ושואלים מצד אחר: \u0003ויהיו כל\u0004 שאר \u0003הכלים\u0004 שאינם כלי חרס \u0003מיטמאין מאוירן, מקל וחומר: ומה כלי חרס שאין מיטמא מגבו\u0004 — \u0003מיטמא מאוירו, כל הכלים שמיטמאין מגבן\u0004 — \u0003אינו דין שמיטמאין מאוירן?\u0004","ומשיבים, \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין שרצים: \"וכל כלי חרס אשר יפול מהם אל \u0003תוכו\"\u0004 (ויקרא יא, לג), להדגיש: \u0003תוכו של\u0004 כלי \u0003זה, ולא תוכו של\u0004 כלי \u0003אחר.\u0004","ושואלים: \u0003ו\u0004הרי \u0003הני\u0004 \u0005[אלה]\u0006 פעמיים \u0003\"תוכו\"\u0004 שכתובות בפסוק זה, \u0003הא דרשינהו\u0004 \u0005[כבר דרשנו אותן]\u0006 בתחילת הסוגיה ללמד: מה \"תוכו\" האמור לטמא — אף על פי שלא נגע, אף \"תוכו\" האמור ליטמא — אף על פי שלא נגע!","ומשיבים: \u0003ארבעה \"תוכו\" כתיבי\u0004 \u0005[כתובים]\u0006 בפסוק זה, כיצד? נאמר \u0003\"תוכו\"\u0004 והיה יכול לכתוב \u0003\"תוך\"\u0004 — הרי שנים, ושוב נאמר \u0003\"תוכו\"\u0004 והיה יכול לכתוב \u0003\"תוך\";\u0004","\u0003חד לגופיה\u0004 \u0005[אחד לגופו]\u0006 של הענין, לומר שמטמא כל אוכל שבאוירו, למרות שלא נגע בו. \u0003וחד\u0004 \u0005[ואחד]\u0006 \u0003לגזירה שוה,\u0004 ללמד שגם הכלי עצמו נטמא מאוירו בלי מגע. \u0003וחד\u0004 \u0005[ואחד]\u0006 ללמד: \u0003תוכו של זה ולא תוכו של אחר,\u0004 שכלים אחרים אינם מקבלים טומאה מאוירם. \u0003וחד\u0004 \u0005[ואחד]\u0006 בא ללמד: \u0003תוכו ולא תוך תוכו,\u0004 שכלי שנמצא בתוך כלי חרס, מציל על מה שבתוכו מן הטומאה שבאויר כלי החרס, \u0003ואפילו\u0004 היה זה \u0003כלי שטף,\u0004 כלומר, כלי שאינו כלי חרס.","ושואלים עוד: \u0003ולא יהו\u0004 (יהיו) \u0003כל\u0004 שאר \u0003הכלים מיטמאין מגבן, אלא\u0004 רק \u0003מתוכן ובנגיעה,\u0004 ונלמד זאת \u0003מקל וחומר: ומה כלי חרס שמיטמא מאוירו\u0004 — \u0003אינו מיטמא מגבו, כל הכלים שאין מיטמאין מאוירן\u0004 — \u0003אינו דין שאין מיטמאין מגבן?\u0004","ומשיבים, \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"וכל כלי פתוח אשר אין צמיד פתיל עליו טמא הוא\"\u0004 (במדבר יט, טו), ונדייק: \u0003האי\u0004 \u0005[זה],\u0006 כלי חרס, \u0003הוא דכי\u0004 \u0005[שכאשר]\u0006 \u0003אין צמיד פתיל עליו\u0004 הוא \u0003טמא, הא\u0004 \u0005[אבל]\u0006 אם \u0003יש צמיד פתיל עליו\u0004 — \u0003טהור,\u0004 ואפילו נגעה טומאה בגבו; \u0003הא\u0004 \u0005[אבל]\u0006 \u0003כל\u0004 שאר \u0003הכלים, בין שיש צמיד פתיל עליהם בין שאין צמיד פתיל עליהם\u0004 — \u0003מיטמאין,\u0004 מפני שהטומאה באה להם גם מגבם.","יש \u0003טהור בכלי עץ\u0004 שכיוצא בו \u0003טמא בכלי מתכות,\u0004 ו\u0003טהור בכלי מתכות\u0004 שכיוצא בו \u0003טמא בכלי עץ.\u0004","בפירוש משנתנו \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003גולמי כלי עץ\u0004 כלומר, כלי עץ שיש להם בית קיבול, וראויים למלאכתם, אלא שעדיין לא נגמרה עשייתם — הרי הם כבר \u0003טמאין,\u0004 ראויים לקבל טומאה. אבל \u0003פשוטיהן,\u0004 כלי עץ שטוחים, שאין להם בית קיבול, כגון לוח — \u0003טהורין.\u0004 ואילו \u0003גולמי כלי מתכות,\u0004 שראויים למלאכתם, אלא שלא נגמרה כל עשייתם — \u0003טהורין,\u0004 אבל \u0003פשוטיהן\u0004 כגון מחט — \u0003טמאין,\u0004 אם הם ראויים למלאכה. \u0003נמצא\u0004 שה\u0003טהור בכלי עץ\u0004 (כלי פשוט) — \u0003טמא\u0004 בכיוצא בו \u0003בכלי מתכות,\u0004 ואילו \u0003טהור בכלי מתכות\u0004 (גולם) — \u0003טמא בכלי עץ.\u0004","\u0003ואלו הן גולמי כלי עץ: כל שעתיד\u0004 עוד \u0003לשוף\u0004 (לשייף) אותו, \u0003לשבץ\u0004 בו אבנים טובות וכדומה, או \u0003לגרר,\u0004 להחליק אותו במפסלת, \u0003לכרכב,\u0004 לעשות סביבו חריצים ובליטות לנוי, \u0003להטיח בטונס,\u0004 לשפשף ולהחליק אותו בעור של דג, או כלי שהיה \u0003מחוסר כן\u0004 (בסיס), \u0003או אוגן\u0004 (שפה), \u0003או אוזן\u0004 (ידית) — \u0003טמא\u0004 כלומר, ראוי לקבל טומאה, כיוון שהוא ראוי למלאכתו. אבל אם היה \u0003מחוסר חטיטה,\u0004 שעדיין לא נעשה בו בית קיבול — הרי הוא \u0003טהור.\u0004","ותוהים: \u0003מחוסר חטיטה פשיטא\u0004 \u0005[פשוט]\u0006 שאינו מקבל טומאה, הרי אין זה כלי כלל! ומשיבים: \u0003לא צריכא\u0004 \u0005[לא נצרכה]\u0006 הלכה זו אלא במקרה \u0003דחק קפיזא בקבא\u0004 \u0005[שחקק\u0006 חלל של \u0005שלושה לוגים בתוך\u0006 דבר שרוצה לחקוק בו \u0005קב שלם,\u0006 ששה לוגים\u0005],\u0006 שלמרות שיש לו בית קיבול, הואיל ולא נגמרה מלאכתו של כלי זה עצמו — אינו מקבל טומאה.","וממשיכה הברייתא, \u0003ואלו הן גולמי כלי מתכות: כל שעתיד\u0004"],["\u0003לשוף\u0004 (להחליק), \u0003לשבץ\u0004 בו אבנים טובות, \u0003לגרר\u0004 (לגרד), \u0003לכרכר\u0004 (לצרוב בו ציורים), \u0003להקיש בקורנס\u0004 כדי ליישר אותו, וכן אם היה \u0003מחוסר כן\u0004 (בסיס) \u0003או אוגן\u0004 (שפה) \u0003או אוזן\u0004 (ידית) — הרי זה \u0003טהור,\u0004 אינו ראוי לקבל טומאה. אבל אם היה הכלי עצמו גמור, אלא שהיה \u0003מחוסר כסוי\u0004 — \u0003טמא,\u0004 ראוי לקבל טומאה.","ושואלים: \u0003מאי שנא הני ומאי שנא הני\u0004 \u0005[במה שונים אלה,\u0006 גולמי כלי עץ, \u0005ובמה שונים אלה,\u0006 גולמי כלי מתכת\u0005],\u0006 שבכלי עץ די שיהיו ראויים למלאכתם כדי לקבל טומאה, ואילו כלי מתכות שלא נגמרה מלאכתם לגמרי אינם מקבלים טומאה? \u0003רבי יוחנן אמר: הואיל ו\u0004כלי מתכת \u0003לכבוד עשויין,\u0004 ולכן כל זמן שהכלי אינו מושלם ואינו מכובד אינו נחשב ככלי לעניינו. \u0003רב נחמן אמר: הואיל ודמיהן\u0004 של כלי מתכות \u0003יקרים,\u0004 וכל זמן שלא נגמרה מלאכתם אינם נמכרים בדמים יקרים, ואינם ראויים לעניינם.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל להלכה \u0005ביניהם,\u0006 בין שני הטעמים\u0005]?\u0006 ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 לגבי \u0003כלי עצם,\u0004 כגון כלים העשויים מקרנים, שדמיהם יקרים, אבל אינם עשויים לכבוד, שלפי הסברו של ר' יוחנן גולמיהם מקבלים טומאה, ולפי הסברו של רב נחמן אינם מקבלים טומאה, כגולמי כלי מתכות. ומעירים: \u0003ואזדא\u0004 \u0005[והולך]\u0006 \u0003רב נחמן לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 ש\u0003אמר רב נחמן: כלי עצם\u0004 לענין טומאה \u0003ככלי מתכות דמו\u0004 \u0005[נחשבים].\u0006","ושואלים: האם \u0003מכלל\u0004 הדברים אתה למד \u0003ש\u0004\u0003כלי עצם מקבלי\u0004 \u0005[מקבלים]\u0006 \u0003טומאה\u0004 הם? ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003רבי ישמעאל בנו של ר' יוחנן בן ברוקה אומר: מה תלמוד לומר\u0004 בפרשת טהרת כלי מדין מטומאתם: \u0003\"וכל מעשה עזים תתחטאו\"\u0004 (במדבר לא, כ)? \u0003להביא\u0004 (לרבות) \u0003דבר הבא\u0004 (הנעשה) \u0003מן העזים\u0004 \u0003מן הקרנים ומן הטלפים\u0004 (הפרסות) שהוא מקבל טומאה. ומה שבא מקרנים וטלפים של \u0003שאר בהמה וחיה, מנין\u0004 שהוא מקבל טומאה? \u0003תלמוד לומר: \"וכל מעשה\"\u0004 בלשון ריבוי. \u0003אם כן, מה תלמוד לומר \"עזים\"?\u0004 שהרי דבר זה אינו מיוחד לעיזים! \u0003פרט לעופות,\u0004 שדבר שנעשה מעצמות עופות אינו מטמא.","\u0003החייב בשקדים המרים\u0004 בתרומות ובמעשרות — \u0003פטור ב\u0004שקדים ה\u0003מתוקים,\u0004 ו\u0003החייב במתוקים\u0004 — \u0003פטור במרים.\u0004","בפירוש משנתנו \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שקדים המרים,\u0004 כשהם \u0003קטנים\u0004 — \u0003חייבין\u0004 בתרומות ובמעשרות, משום שאז עדיין אינם מרים, והם ראויים לאכילה, אבל כשהם \u0003גדולים\u0004 — \u0003פטורין,\u0004 מפני שהם מרים ואינם ראויים לאכילה. ואילו השקדים ה\u0003מתוקים,\u0004 כשהם \u0003גדולים\u0004 — \u0003חייבין,\u0004 שנגמר הפרי וראוי לאכילה, אבל כשהם \u0003קטנים\u0004 — \u0003פטורין,\u0004 מפני שאין דרך לאכול אותם.","\u0003רבי ישמעאל בר' יוסי אומר משום\u0004 בשם \u0003אביו\u0004 ביחס לשקדים המרים: \u0003זה וזה לפטור,\u0004 בין כשהם קטנים ובין כשהם גדולים. \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 בנוסח אחר: \u0003זה וזה לחיוב,\u0004 בין בגדולים ובין בקטנים. \u0003אמר ר' אלעא: הורה ר' חנינא בצפורי כדברי האומר זה וזה לפטור\u0004 במרים.","ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ולמי שאומר]\u0006 \u0003זה וזה לחיוב,\u0004 שקדים מרים \u0003גדולים למאי חזו\u0004 \u0005[למה\u0006 הם \u0005ראויים]?\u0006 הרי מרים הם ואי אפשר לאכול אותם! \u0003אמר ר' יוחנן: הואיל ויכול למתקן על ידי האור,\u0004 שכאשר קולים אותם באש הם מתמתקים וניתנים לאכילה.","\u0003התמד\u0004 משקה העשוי ממים שניתנו על גבי פסולת של ענבים ועברו תהליך של תסיסה, \u0003עד שלא החמיץ\u0004 הוא נחשב כמים, ולכן \u0003אינו ניקח\u0004 (נקנה) \u0003בכסף מעשר\u0004 שני, לשתותו בירושלים, לפי שאינו יין, \u0003ופוסל את המקוה,\u0004 אם היו בו שלושה לוגין ונפל לתוך מקוה חסר, וכדין מים שאובים. \u0003משהחמיץ\u0004 התמד דינו כיין, ולכן \u0003ניקח בכסף מעשר, ואינו פוסל את המקוה,\u0004 שאיננו עוד בגדר מים.","\u0003האחין\u0004 שהיו \u0003שותפין\u0004 בירושת אביהם, \u0003כשחייבין בקלבון\u0004 (מטבע קטנה שמוסיפים \u0003בזמן שנותנים את מחצית השקל), כלומר, בזמן שיש להם דין של שותפים רגילים —\u0004 הרי הם \u0003פטורין מ\u0004להפריש \u0003מעשר בהמה\u0004 מן העדר שהוריש אביהם, וכדין שותפים. אבל \u0003כשחייבין במעשר בהמה,\u0004 כלומר, כשאינם נחשבים שותפים, אלא כסמוכים על שולחן אביהם — \u0003פטורין מן הקלבון,\u0004 כדין אב הנותן מחצית השקל עבור בניו, שפטור מלתת קלבון עבורם.","על מה ששנינו במשנה בענין התמד, שואלים: \u0003מני מתניתין\u0004 \u0005[\u0006כשיטת \u0005מי היא משנתנו]?\u0006 הרי לכאורה \u0003לא\u0004 כדעת \u0003רבי יהודה ולא\u0004 כדעת \u0003רבנן\u0004 \u0005[חכמים]\u0006 החולקים עליו! \u0003דתניא\u0004 \u0005[ששנויה\u0006 משנה\u0005]:\u0006 \u0003המתמד,\u0004 שנתן מים על גבי פסולת ענבים, \u0003ונתן מים במדה\u0004 מסויימת \u0003ומצא כדי מדתו,\u0004 כלומר, בדיוק אותה מידה של מים — הרי זה \u0003פטור\u0004 מן המעשר, למרות שיש בו טעם יין, שהרי אין כאן אלא מים. \u0003ור' יהודה מחייב,\u0004 מפני שלשיטתו הטעם נותן לו דין יין.","ומעתה, \u0003מני\u0004 \u0005[כשיטת מי היא]\u0006 משנתנו? \u0003אי רבנן\u0004 \u0005[אם\u0006 כשיטת \u0005חכמים],\u0006 הרי הם אומרים שהכל תלוי במידה, ואם אין יותר מכפי מידתו — פטור \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003החמיץ.\u0004 \u0003אי\u0004 \u0005[אם]\u0006 שיטת \u0003ר' יהודה,\u0004 הרי הוא מחייב \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא החמיץ,\u0004 שהרי לא הזכירו חלוקה זו בדבריהם! \u0003אמר רב נחמן אמר רבה בר אבוה:\u0004"]]};
